const a={"les-n4-u01-01":{pedagogical_framework:{what:{summary:"Pola pembentukan bentuk kehendak (volitional / 意向形 ikoukei), menyatakan niat yang sedang dipikirkan (〜ようと思う), rencana matang yang sudah diputuskan (〜つもりだ), serta kebiasaan hidup yang ditetapkan atas disiplin diri (〜ことにしている).",canDo:"Bisa menyampaikan niat spontan kepada teman, menjelaskan rencana karier/studi jangka menengah kepada atasan, dan memaparkan disiplin jadwal harian.",targetPatterns:["[Verba Bentuk-You (Ikoukei)] (ayo / berniat)","[Verba Bentuk-You] と 思っています (berniat)","[Verba Kamus / Nai] つもりです (berencana)","[Verba Kamus / Nai] ことに しています (membiasakan diri)"],coreVocabSample:["いこう","がんばろう","けいかく","よてい","きめる","ごうかく","しけん","まいあさ"]},sensei_context:{sceneIntro:"Budi dan Sakura sedang minum teh di kafetaria asrama Tokyo. Sakura menanyakan target belajar Budi menjelang ujian JLPT akhir tahun dan rencana liburan musim dingin.",dailyMission:'Mampu mengubah kata kerja Golongan 1, 2, dan 3 ke bentuk kehendak (ikoukei), membedakan nuansa "V-you to omou" vs "tsumori desu", serta menjelaskan komitmen kebiasaan pribadi.',whyOrder:"Menyatakan niat dan rencana adalah fondasi pertama di level N4. Di level N5 kita hanya bisa menyatakan keinginan pasif (〜たい). N4 menuntut komitmen tindakan nyata (actionable agency)!"},cultural_notes:{title:'Hierarki Pernyataan Niat & Pantangan Menanyakan "Tsumori" ke Atasan',etiquette:'Bentuk 〜つもりです (tsumori desu) mencerminkan keyakinan kuat dalam benak sendiri. Jangan pernah bertanya kepada atasan "Sensei wa doko e iku tsumori desu ka?" karena terdengar lancang seperti menginterogasi isi pikiran mereka. Gunakan bentuk jadwal "go-yotei" atau Keigo.',taboos:"Bentuk kehendak biasa (ikoukei: ikou, tabeyou) HANYA untuk teman akrab atau monolog batin. Kepada orang baru atau atasan, wajib menggunakan bentuk 〜ましょう (mashou)."},pronunciation_tips:{title:"Pemanjangan Vokal O pada Bentuk Kehendak (Ikoukei)",moraNote:"Pada verba Golongan 1, akhiran vokal u berubah menjadi baris o panjang (2 mora): Iku -> Ikou (い・こ・う), Kaku -> Kakou (か・こ・う), Nomu -> Nomou (の・も・う).",soundTip:"Pastikan vokal panjang [ou] diucapkan penuh 2 ketukan mora agar tidak tertukar dengan bentuk perintah pendek."},common_pitfalls:[{title:'Salah Menghubungkan Bentuk Verba Sebelum "Tsumori desu"',caseScenario:'Menempelkan bentuk masu ke tsumori desu: "Ikimasu tsumori desu".',pitfallWarning:'"あした とうきょうへ いきます つもりです。"',rightSolution:'"あした とうきょうへ いく つもりです。"',explanation:"Pola 〜つもりです WAJIB didahului oleh Bentuk Kamus (Jisho-kei) untuk rencana positif, atau Bentuk Nai untuk rencana pembatalan (ikanai tsumori desu)."},{title:'Terbalik Antara "Koto ni shite iru" vs "Koto ni natte iru"',caseScenario:'Ingin bilang "saya mendisiplinkan diri lari pagi" tapi menggunakan aturan luar lembaga.',pitfallWarning:'"まいあさ はしる ことに なっています。" (Artinya: ada peraturan eksternal yang mewajibkan saya lari)',rightSolution:'"まいあさ はしる ことに しています。" (Benar: keputusan disiplin pribadi)',explanation:"Koto ni shite iru = keputusan tekad diri sendiri. Koto ni natte iru = aturan organisasi/hukum dari pihak luar."}],who_and_when:{situational_context:"Diskusi target kerja dengan atasan, wawancara beasiswa/magang, resolusi tahun baru, obrolan santai rencana akhir pekan.",social_relations:"Ikoukei untuk teman sebaya; 〜ようと思っています untuk formal kerja; 〜つもりです untuk komitmen pribadi.",when_not_to_use:"Jangan gunakan tsumori desu untuk menanyakan rencana orang yang status sosialnya lebih tinggi."},scenario:{title:"Mendiskusikan Rencana Ujian dan Resolusi Hidup di Jepang",setting:"Kafetaria Asrama Tokyo pukul 19.00",narrative:"Sakura menanyakan persiapan Budi menghadapi ujian JLPT N4. Budi memaparkan target kelulusan dan rutinitas belajarnya setiap malam."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Mentor Pembelajar",avatar:"👩‍🏫",jp:"ブディさん、今年【ことし】の 冬休【ふゆやす】みは どうするの？ インドネシアへ 帰【かえ】る？",furigana:"ブディさん、今年の 冬休みは どうするの？ インドネシアへ 帰る？",romaji:"Budi-san, kotoshi no fuyuyasumi wa dou suru no? Indonesia e kaeru?",idText:"Budi-san, liburan musim dingin tahun ini mau bagaimana? Pulang ke Indonesia?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"いいえ、今年【ことし】は 国【くに】へ 帰【かえ】らない つもりです。東京【とうきょう】で 勉強【べんきょう】しようと 思【おも】っています。",furigana:"いいえ、今年は 国へ 帰らない つもりです。東京で 勉強しようと 思っています。",romaji:"Iie, kotoshi wa kuni e kaeranai tsumori desu. Toukyou de benkyou shiyou to omotte imasu.",idText:"Tidak, tahun ini saya berencana tidak pulang ke tanah air. Saya berniat belajar di Tokyo."},{id:"d3",speaker:"Sakura",speakerRole:"Mentor Pembelajar",avatar:"👩‍🏫",jp:"そうなの？ １２月【じゅうにがつ】の Ｎ４の 試験【しけん】を 受【う】けるのね。頑張【がんば】って！",furigana:"そうなの？ １２月の Ｎ４の 試験を 受けるのね。頑張って！",romaji:"Sou na no? Juunigatsu no N4 no shiken o ukeru no ne. Ganbatte!",idText:"Oh begitu ya? Kamu mau ikut ujian N4 bulan Desember kan ya. Semangat ya!"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、絶対【ぜったい】に 合格【ごうかく】したいので、毎晩【まいばん】 ２時間【にじかん】 日本語【にほんご】を 勉強【べんきょう】する ことに しています。",furigana:"はい、絶対に 合格したいので、毎晩 ２時間 日本語を 勉強する ことに しています。",romaji:"Hai, zettai ni goukaku shitai node, maiban nijikan nihongo o benkyou suru koto ni shite imasu.",idText:"Iya, karena ingin pasti lulus, saya membiasakan diri belajar bahasa Jepang 2 jam setiap malam."},{id:"d5",speaker:"Sakura",speakerRole:"Mentor Pembelajar",avatar:"👩‍🏫",jp:"素晴【すば】らしい 心【こころ】がけね！ 今度【こんど】 一緒【いっしょ】に 模擬試験【もぎしけん】を やってみようよ。",furigana:"素晴らしい 心がけね！ 今度 一緒に 模擬試験を やってみようよ。",romaji:"Subarashii kokorogake ne! Kondo issho ni mogishiken o yatte miyou yo.",idText:"Sikap tekad yang luar biasa! Lain kali ayo kita coba kerjakan simulasi ujian bersama-sama ya."}],vocab_breakdown:[{id:"v1",word:"べんきょうしよう",reading:"べんきょうしよう",romaji:"benkyou shiyou",meaning:"ayo belajar / mari kita belajar (bentuk kehendak dari べんきょうする)",nuance:"Bentuk kehendak kasual dari kata kerja Golongan 3 suru -> shiyou.",exampleSentence:{jp:"きょうは としょかんで いっしょに べんきょうしよう。",furigana:"今日は 図書館で 一緒に 勉強しよう。",romaji:"Kyou wa toshokan de issho ni benkyou shiyou.",idText:"Hari ini ayo kita belajar bersama di perpustakaan."}},{id:"v2",word:"つもり",reading:"つもり",romaji:"tsumori",meaning:"niat / rencana pasti dalam pikiran",nuance:"Didahului bentuk kamus (positif) atau bentuk nai (negatif). Menunjukkan keputusan bulat.",exampleSentence:{jp:"らいねん 日本の だいがくを うける つもりです。",furigana:"来年 日本の 大学を 受ける つもりです。",romaji:"Rainen Nihon no daigaku o ukeru tsumori desu.",idText:"Tahun depan saya berencana mengikuti ujian masuk universitas Jepang."}},{id:"v3",word:"ことに している",reading:"ことに している",romaji:"koto ni shite iru",meaning:"membiasakan diri / menjadikannya kebiasaan rutin",nuance:"Menunjukkan rutinitas yang lahir dari aturan disiplin diri sendiri.",exampleSentence:{jp:"けんこうのために、まいあさ やさいジュースを のむ ことに しています。",furigana:"健康のために、毎朝 野菜ジュースを 飲む ことに しています。",romaji:"Kenkou no tame ni, maiasa yasai juusu o nomu koto ni shite imasu.",idText:"Demi kesehatan, saya membiasakan diri minum jus sayur setiap pagi."}},{id:"v4",word:"ごうかく",reading:"ごうかく",romaji:"goukaku",meaning:"lulus ujian / passing grade",nuance:"Sering dipasangkan dengan partikel ni: shiken ni goukaku suru (lulus ujian).",exampleSentence:{jp:"Ｎ４の しけんに ごうかくしました！",furigana:"Ｎ４の 試験に 合格しました！",romaji:"N4 no shiken ni goukaku shimashita!",idText:"Saya telah lulus ujian N4!"}}],explanations:[{id:"e1",title:"1. Bentuk Kehendak (意向形 Ikoukei / Volitional Form)",formula:"Gol 1: akhiran -u -> -ou | Gol 2: buang -ru + you | Gol 3: suru -> shiyou, kuru -> koyou",meaning:"Ayo ... / Mari ... (ragam kasual) atau menyatakan tekad spontan.",nuanceNotes:'Bentuk ini adalah pasangan akrab dari 〜ましょう (mashou). Jika berbicara dengan rekan akrab, gunakan ikoukei: "Asobi ni ikou!" (Ayo main!). Jika berbicara sendiri (monolog batin): "Yoshi, ganbarou!" (Baiklah, ayo semangat!).',examples:[{jp:"ちょっと きゅうけいしよう。",furigana:"ちょっと 休憩しよう。",romaji:"Chotto kyuukei shiyou.",idText:"Ayo kita istirahat sebentar."}]},{id:"e2",title:"2. Menyatakan Niat yang Sedang Dipikirkan: 〜ようと 思っています",formula:"[Verba Ikoukei] + と 思っています",meaning:"Saya berniat / sedang berpikir untuk melakukan [aksi].",nuanceNotes:"Bentuk 〜と思っています menunjukkan bahwa niat tersebut sudah dipikirkan sejak beberapa waktu lalu dan masih berlangsung hingga sekarang. Sangat sopan dan alami digunakan dalam wawancara kerja atau obrolan santai formal.",examples:[{jp:"らいしゅう あたらしい パソコンを かおうと おもっています。",furigana:"来週 新しい パソコンを 買おうと 思っています。",romaji:"Raishuu atarashii pasokon o kaou to omotte imasu.",idText:"Minggu depan saya berniat membeli laptop baru."}]},{id:"e3",title:"3. Rencana Pasti Pribadi: 〜つもりです",formula:"[Verba Kamus / Verba-nai] + つもりです",meaning:"Berencana / berniat pasti untuk (atau tidak) melakukan [aksi].",nuanceNotes:'Menunjukkan niat yang lebih mantap dan terencana dibandingkan ikoukei. Untuk pembatalan atau rencana tidak melakukan, gunakan bentuk-nai: "Ikanai tsumori desu" (Saya berencana tidak pergi).',examples:[{jp:"らいねんは くにへ かえらない つもりです。",furigana:"来年は 国へ 帰らない つもりです。",romaji:"Rainen wa kuni e kaeranai tsumori desu.",idText:"Tahun depan saya berencana tidak pulang ke tanah air."}]},{id:"e4",title:"4. Komitmen Disiplin Rutinitas: 〜ことに している",formula:"[Verba Kamus / Verba-nai] + ことに している",meaning:"Membiasakan diri untuk ... / berkomitmen rutin untuk ...",nuanceNotes:"Pola ini menegaskan keputusan sadar pembicara untuk menjalani pola hidup atau kebiasaan tertentu secara berkesinambungan.",examples:[{jp:"まいあさ ６じに おきる ことに しています。",furigana:"毎朝 ６時に 起きる ことに しています。",romaji:"Maiasa rokuji ni okiru koto ni shite imasu.",idText:"Saya membiasakan diri bangun jam 6 setiap pagi."}]}],drills:[{id:"drill-u01-01-1",type:"vocab_context",instruction:"Pilihlah makna yang tepat untuk kalimat: 「こんどの にちようびは ともだちと えいがを みようと おもっています。」",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["Minggu depan saya berniat menonton film bersama teman.","Minggu depan saya terpaksa menonton film bersama teman.","Minggu depan saya dilarang menonton film bersama teman.","Minggu depan saya disuruh menonton film bersama teman."],correctAnswer:"Minggu depan saya berniat menonton film bersama teman.",explanation:"Pola V-you to omotte imasu menyatakan niat yang sedang direncanakan (berniat menonton film).",diagnosticFeedback:{"Minggu depan saya terpaksa menonton film bersama teman.":"Ini adalah pola kausatif-pasif (mirareta/misesaserareta), bukan niat.","Minggu depan saya dilarang menonton film bersama teman.":"Ini adalah pola larangan (mite wa ikenai).","Minggu depan saya disuruh menonton film bersama teman.":"Ini adalah pola kausatif (misesaseru)."}},{id:"drill-u01-01-2",type:"cloze",instruction:"Lengkapilah kalimat rencana tidak membeli mobil: 「おかねが ないので、くるまを（　）つもりです。」",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["かわない","かいます","かわなくて","かう"],correctAnswer:"かわない",explanation:"Untuk menyatakan rencana TIDAK melakukan sesuatu, gunakan bentuk verba-nai sebelum tsumori desu (kawanai tsumori desu).",diagnosticFeedback:{かいます:"Bentuk masu tidak boleh menempel langsung ke tsumori desu.",かわなくて:"Bentuk te tidak cocok menyambung ke tsumori desu.",かう:"Kau tsumori desu berarti berencana membeli, bertentangan dengan alasan tidak punya uang (okane ga nai node)."}},{id:"drill-u01-01-3",type:"reorder",instruction:"Susunlah kata-kata berikut menjadi komitmen kebiasaan rutin: [まいあさ] [ことに] [はしる] [しています] [３０ぷん]",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["まいあさ ３０ぷん はしる ことに しています。","３０ぷん はしる まいあさ ことに しています。","ことに しています まいあさ ３０ぷん はしる。","はしる まいあさ ３０ぷん ことに しています。"],correctAnswer:"まいあさ ３０ぷん はしる ことに しています。",explanation:"Urutan baku: Keterangan waktu (maiasa) -> Durasi (sanjuppun) -> Verba kamus (hashiru) -> Predikat kebiasaan (koto ni shite imasu).",diagnosticFeedback:{"３０ぷん はしる まいあさ ことに しています。":"Posisi keterangan waktu maiasa terbalik di tengah verba.","ことに しています まいあさ ３０ぷん はしる。":"Predikat di awal menyalahi struktur SOV bahasa Jepang.","はしる まいあさ ３０ぷん ことに しています。":"Susunan acak dan tidak gramatikal."},tokens:["まいあさ","３０ぷん","はしる","ことに","しています。"],correctOrder:["0","1","2","3","4"]},{id:"drill-u01-01-4",type:"trap_detect",instruction:"Manakah bentuk perubahan kehendak (ikoukei) yang BENAR untuk kata kerja 飲みます (nomimasu)?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["のもう","のみよう","のまよう","のめよう"],correctAnswer:"のもう",explanation:"Kata kerja Golongan 1 nomu (baris u) diubah menjadi baris o panjang (ou): no-mu -> no-mou (のもう).",diagnosticFeedback:{のみよう:"Salah: akhiran mi-you adalah jebakan mencampurkan bentuk masu dengan you.",のまよう:"Salah: baris a digunakan untuk bentuk negatif (nomanai), bukan ikoukei.",のめよう:"Salah: baris e adalah bentuk potensial (nomeru), bukan ikoukei."}},{id:"drill-u01-01-5",type:"response",instruction:"Teman kantormu mengajak saat jam istirahat: 「おなかが すいたね。いっしょに ひるごはんを たべにいこうよ！」 Bagaimana merespons setuju dengan ragam akrab?",sentencePrompt:"Pilihlah jawaban yang paling tepat:",options:["いいね！ あそこの ラーメンやへ いこう！","いいえ、たべたくありませんでした。","はい、たべる つもりではありません。","いかなければ なりません。"],correctAnswer:"いいね！ あそこの ラーメンやへ いこう！",explanation:'Merespons ajakan ikoukei teman sebaya dengan ungkapan setuju antusias: "Ii ne! Asoko no raamen-ya e ikou!" (Boleh juga! Ayo kita pergi ke kedai ramen di sana!).',diagnosticFeedback:{"いいえ、たべたくありませんでした。":"Bentuk lampau negatif formal kaku yang tidak selaras dengan ajakan santai.","はい、たべる つもりではありません。":"Kontradiktif antara hai dan tsumori dewa arimasen.","いかなければ なりません。":'Artinya "saya harus pergi", bukan ekspresi setuju makan siang.'}}],can_do_challenge:{statement:"Bisa menyampaikan niat belajar dan rencana masa depan di Jepang secara sopan dan terstruktur.",situation:"Sedang wawancara evaluasi kerja magang atau berbincang dengan mentor di Tokyo.",promptTask:"Katakan bahwa kamu berniat mengambil ujian JLPT N4 bulan depan, dan membiasakan diri belajar kanji 30 menit setiap malam!",modelAnswer:"らいげつ Ｎ４の しけんを うけようと おもっています。そして、まいばん ３０ぷん かんじを べんきょうする ことに しています。",modelAnswerId:"Bulan depan saya berniat mengikuti ujian N4. Dan saya membiasakan diri belajar kanji 30 menit setiap malam.",culturalEtiquette:"Ucapkan dengan tatap muka percaya diri dan nada vokal yang bersemangat.",skillUnlocked:["Menguasai tangga perubahan bentuk kehendak (ikoukei)","Mampu membedakan intensitas niat 〜ようと思う vs 〜つもりです","Mampu menyusun komitmen disiplin harian dengan 〜ことにしている"],pocketSummary:{keyFormula:"[V-ikou] と 思っています (niat) | [V-kamus/nai] つもり (rencana) | [V-kamus] ことにしている (rutinitas)",coreWords:["いこう (ayo pergi)","べんきょうしよう (ayo belajar)","つもり (rencana)","よてい (jadwal)"],coreWarning:"Jangan gunakan tsumori desu untuk menanyakan rencana atasan! Ubah Golongan 1 ke baris o panjang (-ou)!",quickDialogue:"A: 何をするつもり？ → B: 日本語を勉強しようと思っているよ。"}},pocket_summary:{keyFormula:"[V-ikou] と 思っています (niat) | [V-kamus/nai] つもり (rencana) | [V-kamus] ことにしている (rutinitas)",coreWords:["いこう (ayo pergi)","べんきょうしよう (ayo belajar)","つもり (rencana)","ごうかく (lulus)"],coreWarning:"Ikoukei Golongan 1 berakhiran vokal panjang 2 mora (-ou). Tsumori hanya untuk rencana pribadi!",quickDialogue:"A: 来年はどうするの？ → B: 国へ帰らないで、日本で働くつもりです。"}},"les-n4-u01-02":{pedagogical_framework:{what:{summary:"Menyatakan kebiasaan hidup yang ditetapkan atas disiplin pribadi (〜ことにしている) dan upaya sadar secara terus-menerus (〜ようにしている / ようにする).",canDo:"Bisa menceritakan komitmen kedisiplinan diri, pola hidup sehat, dan rutinitas belajar mandiri di Jepang.",targetPatterns:["[Verba Kamus / Nai] ことに している (membiasakan diri atas tekad)","[Verba Kamus / Nai] ように している (berupaya secara sadar)"],coreVocabSample:["きそく","けんこう","まいあさ","うんどう","やさい","まもる","つづける"]},sensei_context:{sceneIntro:"Di ruang istirahat kantor setelah jam makan siang. Sakura melihat Budi membawa bekal sehat dan bertanya rahasia staminanya yang selalu prima selama magang di Tokyo.",dailyMission:'Mampu membedakan nuansa "koto ni shite iru" (keputusan aturan sendiri) dan "you ni shite iru" (upaya kebiasaan bertahap), serta mengungkapkan tekad menjaga kesehatan.',whyOrder:"Setelah menyatakan rencana masa depan di Lesson 1 (tsumori / ikoukei), Lesson 2 mengajarkan eksekusi harian melalui kedisiplinan dan pembiasaan diri."},cultural_notes:{title:"Manajemen Kesehatan Pribadi (自己管理 - Jiko Kanri) di Dunia Kerja Jepang",etiquette:'Di Jepang, menjaga kesehatan pribadi dipandang sebagai tanggung jawab profesional. Mengatakan "Saya berupaya tidur tepat waktu" mencerminkan kedewasaan dan kesiapan kerja.',taboos:"Hindari memakai 〜ことにしている untuk aturan umum yang dipaksakan pihak luar (seperti peraturan perusahaan). Pola ini khusus keputusan dari dalam diri sendiri."},pronunciation_tips:{title:"Intonasi Sambung pada Frasa Hiragana Panjang",moraNote:'Frasa "koto ni shite iru" terdiri dari 7 mora datar tanpa aksen kejut tinggi mendadak: ko-to-ni-shi-te-i-ru.',soundTip:'Ucapkan "you ni" dengan vokal [o] panjang 2 mora: yo-o-ni, bukan yoni pendek.'},common_pitfalls:[{title:"Tertukar Antara 〜ことにしている (Keputusan Sendiri) vs 〜ことになっている (Aturan dari Luar)",caseScenario:'Ingin mengatakan "Saya bertekad bangun jam 6", tetapi malah memakai aturan luar.',pitfallWarning:'"毎朝【まいあさ】６時【ろくじ】に 起【お】きる ことに なっています。" (Kurang pas jika tekad pribadi)',rightSolution:'"毎朝【まいあさ】６時【ろくじ】に 起【お】きる ことに しています。" (Tepat)',explanation:"〜ことにしている adalah keputusan dan komitmen inisiatif sendiri, sedangkan 〜ことになっている adalah aturan atau jadwal yang ditetapkan oleh kantor atau organisasi."},{title:"Memasukkan Verba Bentuk Masu Sebelum Pola",caseScenario:'Menggabungkan bentuk masu ke dalam pola: "tabemasu you ni shite iru".',pitfallWarning:'"野菜【やさい】を 食【た】べます ように しています。"',rightSolution:'"野菜【やさい】を 食【た】べる ように しています。"',explanation:"Pola 〜ようにしている dan 〜ことにしている hanya menerima verba bentuk kamus (Jishokei) atau bentuk negatif kamus (Naikei)."}],who_and_when:{situational_context:"Saat wawancara kerja, evaluasi pembimbing magang, atau obrolan santai mengenai gaya hidup dan target belajar.",social_relations:"Ragam sopan (Teineigo) yang sangat elegan untuk berbicara kepada mentor, atasan, maupun rekan kerja.",when_not_to_use:"Jangan gunakan pada hal-hal yang terjadi di luar kendali kemauan manusia (seperti hujan atau tinggi badan)."},scenario:{title:"Komitmen Hidup Disiplin di Tokyo",setting:"Ruang istirahat staf, pukul 12.45",narrative:"Sakura memuji Budi yang tampak bugar dan disiplin membawa bekal sayur setiap hari."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Mentor Pembelajar",avatar:"👩‍🏫",jp:"ブディさん、いつも 元気【げんき】ですね。健康【けんこう】のために 何【なに】か していますか。",furigana:"ブディさん、いつも 元気ですね。健康のために 何か していますか。",romaji:"Budi-san, itsumo genki desu ne. Kenkou no tame ni nanika shite imasu ka.",idText:"Budi-san, selalu kelihatan bugar ya. Ada melakukan sesuatu untuk menjaga kesehatan?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、毎日【まいにち】野菜【やさい】を たくさん 食【た】べる ように しています。",furigana:"はい、毎日野菜を たくさん 食べる ように しています。",romaji:"Hai, mainichi yasai o takusan taberu you ni shite imasu.",idText:"Iya, setiap hari saya berupaya untuk banyak makan sayur."},{id:"d3",speaker:"Sakura",speakerRole:"Mentor Pembelajar",avatar:"👩‍🏫",jp:"素晴らしいですね！運動【うんどう】も していますか。",furigana:"素晴らしいですね！運動も していますか。",romaji:"Subarashii desu ne! Undou mo shite imasu ka.",idText:"Luar biasa sekali! Apakah kamu juga berolahraga?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、エレベーターを 使【つか】わないで、階段【かいだん】を 使【つか】う ことに しています。",furigana:"はい、エレベーターを 使わないで、階段を 使う ことに しています。",romaji:"Hai, erebe-ta- o tsukawanaide, kaidan o tsukau koto ni shite imasu.",idText:"Iya, saya membiasakan diri tidak naik lift, melainkan memakai tangga."},{id:"d5",speaker:"Sakura",speakerRole:"Mentor Pembelajar",avatar:"👩‍🏫",jp:"感心【かんしん】しました。夜【よる】遅【おそ】くの スマホは どうですか。",furigana:"感心しました。夜遅くの スマホは どうですか。",romaji:"Kanshin shimashita. Yoru osoku no sumaho wa dou desu ka.",idText:"Saya kagum. Kalau penggunaan ponsel larut malam bagaimana?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"寝【ね】る 前【まえ】は スマホを 見【み】ない ように 気【き】を つけています。",furigana:"寝る 前は スマホを 見ない ように 気を つけています。",romaji:"Neru mae wa sumaho o minai you ni ki o tsukete imasu.",idText:"Sebelum tidur saya berhati-hati berupaya tidak melihat ponsel."},{id:"d7",speaker:"Sakura",speakerRole:"Mentor Pembelajar",avatar:"👩‍🏫",jp:"しっかり 自己管理【じこかんり】が できていますね！見習【みなら】いたいです。",furigana:"しっかり 自己管理が できていますね！見習いたいです。",romaji:"Shikkari jikokanri ga dekite imasu ne! Minaraitai desu.",idText:"Kamu benar-benar mampu mengelola diri dengan baik ya! Saya ingin mencontohnya."},{id:"d8",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ありがとうございます！これからも 規則正【きそくただ】しい 生活【せいかつ】を 続【つづ】けます。",furigana:"ありがとうございます！これからも 規則正しい 生活を 続けます。",romaji:"Arigatou gozaimasu! Kore kara mo kisokutadashii seikatsu o tsuzukemasu.",idText:"Terima kasih banyak! Ke depannya pun saya akan melanjutkan pola hidup yang teratur."}],vocab_breakdown:[{id:"vg-n4-00540",word:"規則",reading:"きそく",romaji:"kisoku",meaning:"peraturan; aturan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"寮の生活規則を守ってトラブルを防ぎましょう。",furigana:"寮の生活規則を守ってトラブルを防ぎましょう。",romaji:"",idText:"Mari patuhi aturan kehidupan asrama untuk mencegah masalah."}},{id:"vg-n4-00545",word:"アルコール",reading:"アルコール",romaji:"aruko-ru",meaning:"alkohol",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"車を運転する前にはアルコールを絶対に飲んではいけません。",furigana:"車を運転する前にはアルコールを絶対に飲んではいけません。",romaji:"",idText:"Sama sekali tidak boleh meminum alkohol sebelum mengemudikan kendaraan."}},{id:"vg-n4-00546",word:"アクセサリー",reading:"アクセサリー",romaji:"akusesari-",meaning:"aksesori",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"デパートでかわいいシルバーのアクセサリーを買いました。",furigana:"デパートでかわいいシルバーのアクセサリーを買いました。",romaji:"",idText:"Saya membeli aksesori perak yang manis di toserba."}},{id:"vg-n4-00547",word:"アナウンサー",reading:"アナウンサー",romaji:"anaunsa-",meaning:"penyiar",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"テレビのアナウンサーがニュースをはっきりと読んでいます。",furigana:"テレビのアナウンサーがニュースをはっきりと読んでいます。",romaji:"",idText:"Penyiar televisi membacakan warta berita dengan suara yang sangat jelas."}},{id:"vg-n4-00558",word:"テキスト",reading:"テキスト",romaji:"tekisuto",meaning:"buku teks; teks",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"授業で使う日本語のテキストを本屋で買いました。",furigana:"授業で使う日本語のテキストを本屋で買いました。",romaji:"",idText:"Saya membeli buku teks bahasa Jepang yang dipakai di kelas di toko buku."}},{id:"vg-n4-00580",word:"消しゴム",reading:"けしごむ",romaji:"keshigomu",meaning:"penghapus",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"漢字を書き間違えたので消しゴムで消しました。",furigana:"漢字を書き間違えたので消しゴムで消しました。",romaji:"",idText:"Karena salah menulis kanji, saya menghapusnya dengan penghapus."}},{id:"vg-n4-00581",word:"鉛筆",reading:"えんぴつ",romaji:"enpitsu",meaning:"pensil",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"テストのときはシャープペンシルではなく鉛筆を使います。",furigana:"テストのときはシャープペンシルではなく鉛筆を使います。",romaji:"",idText:"Saat ujian kami memakai pensil, bukan pensil mekanik."}},{id:"vg-n4-00592",word:"ケーキ",reading:"ケーキ",romaji:"ke-ki",meaning:"kue",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"誕生日にイチゴがたくさん乗ったケーキを食べました。",furigana:"誕生日にイチゴがたくさん乗ったケーキを食べました。",romaji:"",idText:"Pada hari ulang tahun saya memakan kue yang diberi banyak buah stroberi."}},{id:"vg-n4-00610",word:"僕",reading:"ぼく",romaji:"boku",meaning:"aku (informal, maskulin)",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"僕が荷物を持ってあげるから貸してごらん。",furigana:"僕が荷物を持ってあげるから貸してごらん。",romaji:"",idText:"Sini biar aku yang bawakan barangnya, pinjamkan padaku."}},{id:"vg-n4-00636",word:"数学",reading:"すうがく",romaji:"suugaku",meaning:"matematika",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"高校生のころ数学の問題を解くのが好きでした。",furigana:"高校生のころ数学の問題を解くのが好きでした。",romaji:"",idText:"Semasa SMA saya senang memecahkan soal-soal matematika."}}],explanations:[{id:"exp-1",grammarId:"gn4-00090",title:"Pola: 〜ことにしている",formula:"Vる / Vない + ことにしている",meaning:"sudah menjadi kebiasaan untuk ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ことにしている",idText:"sudah menjadi kebiasaan untuk ..."}],examples:[{jp:"毎朝6時に起きることにしています。",romaji:"",idText:"Saya sudah membiasakan diri bangun jam 6 setiap pagi."},{jp:"お酒は飲まないことにしている。",romaji:"",idText:"Saya sudah membiasakan diri untuk tidak minum alkohol."}]},{id:"exp-2",grammarId:"gn4-00041",title:"Pola: Vようにする",formula:"Vる/Vない + ようにする",meaning:"berusaha agar ... / mengupayakan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vようにする",idText:"berusaha agar ... / mengupayakan ..."}],examples:[{jp:"毎日運動するようにしています。",romaji:"",idText:"Saya berusaha berolahraga setiap hari."},{jp:"夜更かしをしないようにしてください。",romaji:"",idText:"Tolong berusaha untuk tidak begadang."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah padanan makna yang paling tepat untuk istilah "自己管理 (じこかんり)".',sentencePrompt:'Istilah "自己管理" dalam dunia kerja dan kesehatan berarti:',options:["Manajemen kedisiplinan diri sendiri","Laporan keuangan bulanan","Pemberitahuan cuti kerja","Pengaturan jadwal atasan"],correctAnswer:"Manajemen kedisiplinan diri sendiri",explanation:'"自己管理 (じこかんり)" tersusun dari 自己 (diri sendiri) + 管理 (pengelolaan/manajemen).',diagnosticFeedback:{"Laporan keuangan bulanan":"Salah: Laporan keuangan adalah 会計報告 (kaikei houkoku) atau 経理 (keiri).","Pemberitahuan cuti kerja":"Salah: Cuti kerja adalah 休暇届 (kyuukadoke).","Pengaturan jadwal atasan":"Salah: Pengaturan jadwal atasan adalah スケジュール管理 (sukejuuru kanri)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Tepat): Lengkapilah rumpang kalimat berikut dengan bentuk verba yang tepat sebelum "ことにしています".',sentencePrompt:"私【わたし】は 毎朝【まいあさ】ジョギングを _____ ことに しています。",options:["する","します","して","した"],correctAnswer:"する",explanation:"Pola 〜ことにしている mensyaratkan kata kerja bentuk kamus (Jishokei). Kata kerja kelompok 3 suru menjadi する.",diagnosticFeedback:{します:"Salah: Bentuk masu pantang digunakan tepat sebelum partikel nominalisator こと.",して:"Salah: Bentuk te digunakan untuk urutan atau sambungan, bukan sebelum ことにしている.",した:"Salah: Bentuk ta menunjukkan lampau; untuk kebiasaan rutin gunakan bentuk kamus sekarang."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Susunlah potongan kalimat berikut untuk menyatakan upaya sadar tidak makan makanan manis.",sentencePrompt:"Susunan kalimat yang tepat:",options:["甘【あま】い 物【もの】を 食【た】べない ように しています","食【た】べない 甘【あま】い 物【もの】を ように しています","ように しています 甘【あま】い 物【もの】を 食【た】べない","甘【あま】い 食【た】べない 物【もの】を ように しています"],correctAnswer:"甘【あま】い 物【もの】を 食【た】べない ように しています",explanation:"Objek (甘い物を) + Verba Naikei (食べない) + ように しています.",diagnosticFeedback:{"食【た】べない 甘【あま】い 物【もの】を ように しています":"Salah: Predikat kerja tidak boleh ditaruh di awal klausa.","ように しています 甘【あま】い 物【もの】を 食【た】べない":"Salah: Pola you ni shite imasu harus selalu berada di ujung kalimat.","甘【あま】い 食【た】べない 物【もの】を ように しています":"Salah: Kata sifat 甘い harus menerangkan kata benda 物, bukan diselipi kata kerja."},tokens:["甘【あま】い","物【もの】を","食【た】べない","ように","しています"],correctOrder:["0","1","2","3","4"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan Nuansa): Manakah kalimat yang paling tepat untuk menyatakan tekad pribadi membiasakan membaca buku sebelum tidur?",sentencePrompt:"Pilihlah kalimat yang mencerminkan komitmen inisiatif pribadi:",options:["寝【ね】る 前【まえ】に 本【ほん】を 読【よ】む ことに しています。","寝【ね】る 前【まえ】に 本【ほん】を 読【よ】む ことに なっています。","寝【ね】る 前【まえ】に 本【ほん】を 読【よ】みます ことに しています。","寝【ね】る 前【まえ】に 本【ほん】を 読【よ】んだ ことに しています。"],correctAnswer:"寝【ね】る 前【まえ】に 本【ほん】を 読【よ】む ことに しています。",explanation:"〜ことにしている dengan bentuk kamus (読む) menyatakan aturan yang kamu putuskan sendiri atas disiplin pribadi.",diagnosticFeedback:{"寝【ね】る 前【まえ】に 本【ほん】を 読【よ】む ことに なっています。":"Jebakan: 〜ことになっている berarti itu aturan atau kesepakatan luar dari kantor/sekolah, bukan tekad diri.","寝【ね】る 前【まえ】に 本【ほん】を 読【よ】みます ことに しています。":"Jebakan Gramatikal: Bentuk masu (読みます) salah disambung ke こと.","寝【ね】る 前【まえ】に 本【ほん】を 読【よ】んだ ことに しています。":'Jebakan: Bentuk lampau (読んだ) berarti "berpura-pura menganggap sudah membaca".'}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Rekan kerjamu bertanya "風邪【かぜ】を ひかないように、何【なに】か 気【き】を つけていますか". Jawaban paling tepat:',sentencePrompt:"Pilihlah tanggapan yang menyatakan upaya sadar menjaga kesehatan:",options:["外【そと】から 帰【かえ】ったら、手【て】を 洗【あら】う ように しています。","手【て】を 洗【あら】った ほうが いいですよ。","手【て】を 洗【あら】う つもりでした。","風邪【かぜ】を ひく ことに しました。"],correctAnswer:"外【そと】から 帰【かえ】ったら、手【て】を 洗【あら】う ように しています。",explanation:"Menyatakan upaya kebiasaan sadar yang rutin dilakukan diri sendiri (cuci tangan saat pulang dari luar) menggunakan 〜ようにしている.",diagnosticFeedback:{"手【て】を 洗【あら】った ほうが いいですよ。":"Salah: Ini memberi nasihat kepada penanya, padahal penanya menanyakan kebiasaanmu.","手【て】を 洗【あら】う つもりでした。":"Salah: 〜つもりでした berarti berniat di masa lalu tetapi tidak terealisasi.","風邪【かぜ】を ひく ことに しました。":'Konyol/Salah: Ini berarti "saya memutuskan untuk masuk angin".'}}],can_do_challenge:{statement:"Bisa menceritakan komitmen kedisiplinan dan rutinitas belajar mandiri di Jepang.",situation:"Ditanya oleh mentor kerja mengenai rutinitas belajar bahasa Jepang di asrama.",promptTask:"Katakan bahwa kamu membiasakan diri menghafal 5 kanji setiap malam!",modelAnswer:"毎晩【まいばん】漢字【かんじ】を 五【いつ】つ 覚【おぼ】える ことに しています。",modelAnswerId:"Setiap malam saya membiasakan diri menghafal 5 buah kanji.",culturalEtiquette:"Tunjukkan kesungguhan tekad belajar dengan intonasi mantap dan santun.",skillUnlocked:["Mampu menyatakan komitmen disiplin pribadi dengan 〜ことにしている","Mampu membedakan tekad internal vs aturan eksternal"]},pocket_summary:{keyFormula:"[V-Kamus / V-Nai] ことに している (disiplin) / ように している (upaya)",coreWords:["きそく","けんこう","じこかんり","つづける"],coreWarning:"Gunakan bentuk kamus atau nai sebelum koto ni shite iru; jangan gunakan bentuk masu.",quickDialogue:"A: 何か気をつけていますか。 → B: 野菜を食べるようにしています。"}}},n={"les-n4-u02-01":{pedagogical_framework:{what:{summary:"Memberikan saran atau rekomendasi kuat (〜ほうがいい) dan saran alternatif santun (〜たらどうですか).",canDo:"Bisa menasihati rekan kerja yang menghadapi masalah atau kelelahan secara empatik dan tepat tata krama.",targetPatterns:["[Verba Bentuk-Ta] ほう が いい (lebih baik melakukan)","[Verba Bentuk-Nai] ほう が いい (lebih baik jangan)","[Verba Bentuk-Tara] どうですか (bagaimana kalau)"],coreVocabSample:["くすり","びょういん","ねつ","むり","やすむ","そうだん","しんぱい"]},sensei_context:{sceneIntro:"Di area kerja kantor atau pabrik. Kenji melihat Budi batuk dan pucat saat jam istirahat. Kenji memberikan saran ramah agar Budi segera berobat atau istirahat.",dailyMission:"Mampu menyusun kalimat saran afirmatif (V-ta hou ga ii) dan preventif (V-nai hou ga ii), serta mengajak konsultasi santun (tara dou desu ka).",whyOrder:"Setelah bisa menyatakan komitmen diri di Unit 1, Unit 2 melatih empati sosial: merekomendasikan tindakan terbaik kepada orang lain."},cultural_notes:{title:"Etika Memberi Nasihat di Jepang: Jangan Terkesan Menggurui",etiquette:"Pola 〜ほうがいい memiliki nuansa nasihat yang cukup tegas. Kepada atasan, jangan gunakan 〜ほうがいい karena terdengar seperti mendikte atasan. Gunakan 〜てはいかがでしょうか atau pertanyaan halus.",taboos:'Hindari mengatakan "〜しなければならない" (harus) saat memberi saran kasual; kalimat tersebut terlalu kaku dan mengintimidasi.'},pronunciation_tips:{title:'Pelafalan Frasa "Hou ga ii"',moraNote:'"Hou" (ほう) adalah vokal panjang 2 mora (ho-o). "Ii" (いい) adalah 2 mora (i-i). Jaga ketukan stabil.',soundTip:'Akhiri kalimat nasihat dengan partikel lembut "yo" atau "ne" (〜ほうがいいですよ) agar terdengar peduli dan hangat.'},common_pitfalls:[{title:'Memakai Bentuk Kamus Sebelum "Hou ga ii" Afirmatif',caseScenario:'Refleks menggunakan bentuk kamus "iku hou ga ii" untuk saran pergi ke dokter.',pitfallWarning:'"病院【びょういん】へ 行【い】く ほう が いいです。" (Kurang baku)',rightSolution:'"病院【びょういん】へ 行【い】った ほう が いいです。" (Baku & Alami)',explanation:"Dalam bahasa Jepang standar, saran afirmatif (melakukan sesuatu) wajib menggunakan verba bentuk lampau (Bentuk-Ta) sebelum ほうがいい."},{title:"Salah Bentuk pada Kalimat Saran Negatif (Jangan Melakukan)",caseScenario:'Menggunakan bentuk lampau negatif "nakatta hou ga ii" padahal saran untuk masa depan.',pitfallWarning:'"無理【むり】を しなかった ほう が いいですよ。" (Bermakna penyesalan masa lalu)',rightSolution:'"無理【むり】を しない ほう が いいですよ。" (Saran untuk sekarang/depan)',explanation:"Untuk saran melarang (lebih baik jangan), gunakan bentuk masa kini negatif (Naikei) + ほうがいい."}],who_and_when:{situational_context:"Saat melihat rekan kerja sakit, kelelahan, atau bingung menentukan keputusan.",social_relations:"Sangat cocok untuk rekan sejawat, bawahan, atau sesama teman pembelajar. Kepada atasan gunakan bentuk usulan keigo.",when_not_to_use:"Jangan gunakan bentuk 〜ほうがいい kepada direktur atau manajer perusahaan secara langsung."},scenario:{title:"Saran Empatik Saat Rekan Kerja Demam",setting:"Ruang loker karyawan, pukul 16.30",narrative:"Kenji menyadari Budi bersin-bersin dan badannya hangat menjelang akhir jam kerja."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"ブディ、顔色【かおいろ】が 悪【わる】いよ。熱【ねつ】が あるんじゃない？",furigana:"ブディ、顔色が 悪いよ。熱が あるんじゃない？",romaji:"Budi, kaoiro ga warui yo. Netsu ga arun janai?",idText:"Budi, wajahmu pucat lho. Jangan-jangan kamu demam?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ちょっと 頭【あたま】が 痛【いた】くて、寒気【さむけ】が します。",furigana:"ちょっと 頭が 痛くて、寒気が します。",romaji:"Chotto atama ga itakute, samuke ga shimasu.",idText:"Agak sakit kepala dan merasa menggigil."},{id:"d3",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"それは 大変【たいへん】だ。今日【きょう】は 残業【ざんぎょう】しないで、早【はや】く 帰【かえ】った ほう が いいよ。",furigana:"それは 大変だ。今日は 残業しないで、早く 帰った ほう が いいよ。",romaji:"Sore wa taihen da. Kyou wa zangyou shinaide, hayaku kaetta hou ga ii yo.",idText:"Wah gawat tuh. Hari ini lebih baik tidak lembur dan pulang lebih awal."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"でも、まだ 明日【あした】の 準備【じゅんび】が 残【のこ】っています。",furigana:"でも、まだ 明日の 準備が 残っています。",romaji:"Demo, mada ashita no junbi ga nokotte imasu.",idText:"Tapi, masih tersisa persiapan untuk besok."},{id:"d5",speaker:"Sakura",speakerRole:"Mentor Pembelajar",avatar:"👩‍🏫",jp:"準備【じゅんび】は 私【わたし】たちが やるから、無理【むり】を しない ほう が いいですよ。",furigana:"準備は 私たちが やるから、無理を しない ほう が いいですよ。",romaji:"Junbi wa watashitachi ga yaru kara, muri o shinai hou ga ii desu yo.",idText:"Persiapan biar kami yang kerjakan, jadi lebih baik jangan memaksakan diri ya."},{id:"d6",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"田中【たなか】リーダーに 相談【そうだん】して、病院【びょういん】へ 行【い】ったら どう？",furigana:"田中リーダーに 相談して、病院へ 行ったら どう？",romaji:"Tanaka-ri-da- ni soudan shite, byouin e ittara dou?",idText:"Bagaimana kalau konsultasi ke Leader Tanaka, lalu pergi ke klinik?"},{id:"d7",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"お言葉【ことば】に 甘【あま】えて、そうします。ご心配【しんぱい】を かけました。",furigana:"お言葉に 甘えて、そうします。ご心配を かけました。",romaji:"Okotoba ni amaete, sou shimasu. Goshinpai o kakemashita.",idText:"Atas kebaikan kalian, saya akan ikuti saran itu. Maaf sudah membuat khawatir."},{id:"d8",speaker:"Sakura",speakerRole:"Mentor Pembelajar",avatar:"👩‍🏫",jp:"お大事【だいじ】に！温【あたた】かくして ゆっくり 休【やす】んでくださいね。",furigana:"お大事に！温かくして ゆっくり 休んでくださいね。",romaji:"Odaiji ni! Atatakaku shite yukkuri yasunde kudasai ne.",idText:"Semoga lekas sembuh! Hangatkan tubuh dan istirahatlah dengan tenang ya."}],vocab_breakdown:[{id:"vg-n4-00180",word:"合計",reading:"ごうけい",romaji:"goukei",meaning:"jumlah total",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"レジで計算すると買い物の合計は五千円でした。",furigana:"レジで計算すると買い物の合計は五千円でした。",romaji:"",idText:"Saat dihitung di kasir, jumlah total belanjanya adalah 5000 yen."}},{id:"vg-n4-00423",word:"触る",reading:"さわる",romaji:"sawaru",meaning:"menyentuh",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"展示されている貴重な美術品には触らないでください。",furigana:"展示されている貴重な美術品には触らないでください。",romaji:"",idText:"Jangan menyentuh benda karya seni berharga yang tengah dipamerkan."}},{id:"vg-n4-00648",word:"支度",reading:"したく",romaji:"shitaku",meaning:"persiapan; bersiap-siap",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"もうすぐ時間ですから早く出かける支度をしてください。",furigana:"もうすぐ時間ですから早く出かける支度をしてください。",romaji:"",idText:"Waktunya kian mepet, bergegaslah menyiapkan perlengkapan bertolak."}},{id:"vg-n4-00658",word:"参加する",reading:"さんかする",romaji:"sankasuru",meaning:"berpartisipasi, ikut serta",pos:"verb-suru",nuance:"参加する = berpartisipasi. 参加者 = peserta. 参加を申し込む = mendaftar ikut.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"来週のイベントに参加する予定です。",furigana:"来週のイベントに参加する予定です。",romaji:"",idText:"Saya berencana ikut event minggu depan."}},{id:"vg-n4-00665",word:"準備する",reading:"じゅんびする",romaji:"junbisuru",meaning:"mempersiapkan, bersiap-siap",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"明日のパーティーのためにみんなで部屋を準備しました。",furigana:"明日のパーティーのためにみんなで部屋を準備しました。",romaji:"",idText:"Kami bergotong-royong menata rapi bilik ruangan demi menyambut pesta esok."}},{id:"vg-n4-00666",word:"出発する",reading:"しゅっぱつする",romaji:"shuppatsusuru",meaning:"berangkat",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"朝八時にみんなで車に乗ってキャンプ場へ出発しました。",furigana:"朝八時にみんなで車に乗ってキャンプ場へ出発しました。",romaji:"",idText:"Pukul delapan pagi kami berangkat mengendarai mobil ke arena perkemahan."}},{id:"vg-n4-00668",word:"連絡する",reading:"れんらくする",romaji:"renrakusuru",meaning:"menghubungi",pos:"verb-suru",nuance:"連絡する = menghubungi (aktif). 後で連絡します = saya akan hubungi nanti.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"到着したら連絡してください。",furigana:"到着したら連絡してください。",romaji:"",idText:"Tolong hubungi saya kalau sudah sampai."}},{id:"vg-n4-00925",word:"役に立つ",reading:"やくにたつ",romaji:"yaku ni tatsu",meaning:"berguna, bermanfaat, berfaedah",pos:"verb-u",nuance:"Frasa kata kerja gabungan godan (役 + に + 立つ). Bermakna memberikan kegunaan atau manfaat nyata yang membantu meringankan aktivitas orang. Sering dipakai dalam bentuk '役に立ちます' atau kebalikannya '役に立たない' (tidak berguna/sia-sia).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"スマートフォンに入れた地図アプリは海外旅行で大変役に立ちました。",furigana:"スマートフォンに入れた地図アプリは海外旅行で大変役に立ちました。",romaji:"",idText:"Aplikasi peta yang dipasang di ponsel pintar sangat berguna sewaktu berwisata ke luar negeri."}},{id:"vg-n4-01153",word:"例えば",reading:"たとえば",romaji:"tatoeba",meaning:"misalnya",pos:"adverb",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"例えば、ロンドンは今は朝７時です。",furigana:"例えば、ロンドンは今は朝７時です。",romaji:"",idText:"Contohnya, di London sekarang jam 7 pagi."}},{id:"vg-n4-01155",word:"たまに",reading:"たまに",romaji:"tamani",meaning:"sesekali",pos:"adverb",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"たまには会いに来て下さい。",furigana:"たまには会いに来て下さい。",romaji:"",idText:"Sesekali datanglah dan temuilah saya."}}],explanations:[{id:"exp-1",grammarId:"gn4-00038",title:"Pola: 〜といい / 〜たらいい / 〜ばいい",formula:"Vる/Vた/Vば + といい/たらいい/ばいい",meaning:"sebaiknya ... / alangkah baiknya ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜といい / 〜たらいい / 〜ばいい",idText:"sebaiknya ... / alangkah baiknya ..."}],examples:[{jp:"早く良くなるといいですね。",romaji:"",idText:"Semoga cepat sembuh ya."},{jp:"先生に相談したらいいですよ。",romaji:"",idText:"Sebaiknya konsultasi ke guru."}]},{id:"exp-2",grammarId:"gn4-00039",title:"Pola: 〜たらどうですか / 〜いかがですか",formula:"Vた + らどうですか",meaning:"bagaimana kalau ... ? / kenapa tidak ...?",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜たらどうですか / 〜いかがですか",idText:"bagaimana kalau ... ? / kenapa tidak ...?"}],examples:[{jp:"医者に行ったらどうですか。",romaji:"",idText:"Bagaimana kalau pergi ke dokter?"},{jp:"少し休んだらいかがですか。",romaji:"",idText:"Bagaimana kalau istirahat sebentar?"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah ungkapan empati yang diucapkan kepada orang yang sedang sakit.",sentencePrompt:"Saat mendengar rekan kerja sakit atau izin berobat, ucapan santun standar bahasa Jepang adalah:",options:["お大事【だいじ】に (Semoga lekas sembuh)","ごちそうさまでした (Terima kasih atas hidangannya)","お邪魔【じゃま】します (Permisi mengganggu)","遠慮【えんりょ】しないで (Jangan sungkan)"],correctAnswer:"お大事【だいじ】に (Semoga lekas sembuh)",explanation:'"お大事に (odaiji ni)" adalah singkatan santun dari "どうぞお体を大事になさってください" (jaga diri baik-baik / semoga lekas sembuh).',diagnosticFeedback:{"ごちそうさまでした (Terima kasih atas hidangannya)":"Salah: Diucapkan setelah selesai makan.","お邪魔【じゃま】します (Permisi mengganggu)":"Salah: Diucapkan saat bertamu ke rumah orang.","遠慮【えんりょ】しないで (Jangan sungkan)":"Salah: Diucapkan saat menawarkan makanan atau bantuan."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Bentuk Verba): Pilihlah bentuk verba yang tepat untuk saran afirmatif "lebih baik minum obat ini".',sentencePrompt:"この 薬【くすり】を _____ ほう が いいですよ。",options:["飲【の】んだ","飲【の】む","飲【の】みます","飲【の】んで"],correctAnswer:"飲【の】んだ",explanation:"Saran tindakan afirmatif memerlukan bentuk lampau kasual (Bentuk-Ta) sebelum ほうがいい: 飲んだ ほうがいい.",diagnosticFeedback:{"飲【の】む":"Salah: Bentuk kamus kurang tepat untuk rekomendasi saran kuat bahasa Jepang standar.","飲【の】みます":"Salah: Bentuk masu tidak boleh diletakkan di depan kata benda/frasa ほう.","飲【の】んで":"Salah: Bentuk te digunakan sebelum kudasai, bukan ほうがいい."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Susun potongan kalimat berikut untuk menyarankan tidak memaksakan diri bekerja malam ini.",sentencePrompt:"Susunan saran negatif yang tepat:",options:["今夜【こんや】は 無理【むり】を しない ほう が いいです","無理【むり】を 今夜【こんや】は ほう が いいです しない","しない ほう が いいです 今夜【こんや】は 無理【むり】を","今夜【こんや】は ほう が いいです 無理【むり】を しない"],correctAnswer:"今夜【こんや】は 無理【むり】を しない ほう が いいです",explanation:"Keterangan waktu (今夜は) + Objek (無理を) + Verba Naikei (しない) + ほうがいいです.",diagnosticFeedback:{"無理【むり】を 今夜【こんや】は ほう が いいです しない":"Salah: Kata kerja しない terpisah di ujung setelah predikat.","しない ほう が いいです 今夜【こんや】は 無理【むり】を":"Salah: Predikat saran ditaruh di awal kalimat.","今夜【こんや】は ほう が いいです 無理【むり】を しない":"Salah: Frasa ほうがいい ditaruh sebelum kata kerja yang diterangkan."},tokens:["今夜【こんや】は","無理【むり】を","しない","ほう","が","いいです"],correctOrder:["0","1","2","3","4","5"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Rekomendasi Santun): Manakah kalimat saran yang paling halus dan mengajak dengan pola 〜たらどうですか?",sentencePrompt:"Pilihlah bentuk ajakan saran yang paling tepat:",options:["少【すこ】し 横【よこ】に なったら どうですか。","少【すこ】し 横【よこ】に なれば どうですか。","少【すこ】し 横【よこ】に なると どうですか。","少【すこ】し 横【よこ】に なるなら どうですか。"],correctAnswer:"少【すこ】し 横【よこ】に なったら どうですか。",explanation:"Pola usulan alternatif menggunakan bentuk Tara-kei: 〜たら どうですか (bagaimana kalau berbaring sebentar).",diagnosticFeedback:{"少【すこ】し 横【よこ】に なれば どうですか。":"Salah: Bentuk ba-kei tidak berpasangan dengan どうですか untuk membuat usulan saran.","少【すこ】し 横【よこ】に なると どうですか。":"Salah: Bentuk to (pengandaian pasti/alamiah) tidak bisa dipasangkan dengan dou desu ka.","少【すこ】し 横【よこ】に なるなら どうですか。":"Salah: Bentuk nara memerlukan topik syarat kontekstual lawan bicara."}},{id:"drill-5",type:"response",instruction:"Langkah 5 (Respons Situasional): Rekan kerjamu tampak tersesat mencari stasiun kereta. Saran terbaikmu:",sentencePrompt:"Pilihlah kalimat rekomendasi yang paling tepat:",options:["交番【こうばん】で 道【みち】を 聞【き】いた ほう が いいですよ。","交番【こうばん】で 道【みち】を 聞【き】かない ほう が いいですよ。","道【みち】を 迷【まよ】う ことに しました。","道【みち】を 聞【き】く つもりでした。"],correctAnswer:"交番【こうばん】で 道【みち】を 聞【き】いた ほう が いいですよ。",explanation:"Menyarankan tindakan positif yang solutif (lebih baik bertanya jalan di pos polisi) menggunakan Bentuk-Ta + ほうがいいですよ.",diagnosticFeedback:{"交番【こうばん】で 道【みち】を 聞【き】かない ほう が いいですよ。":'Salah/Konyol: Berarti "lebih baik jangan bertanya jalan di pos polisi".',"道【みち】を 迷【まよ】う ことに しました。":'Salah: Berarti "saya memutuskan untuk tersesat di jalan".',"道【みち】を 聞【き】く つもりでした。":"Salah: Menyatakan niat lampau pembicara, bukan saran untuk teman."}}],can_do_challenge:{statement:"Bisa menasihati rekan kerja yang menghadapi masalah secara empatik.",situation:"Melihat rekan magang tidak enak badan saat bekerja.",promptTask:"Sarankan agar dia segera minum air hangat dan pulang istirahat!",modelAnswer:"温【あたた】かい 水【みず】を 飲【の】んで、早【はや】く 帰【かえ】った ほう が いいですよ。",modelAnswerId:"Lebih baik minum air hangat lalu pulang lebih awal lho.",culturalEtiquette:"Gunakan nada suara hangat dengan akhiran sopan desu yo.",skillUnlocked:["Menguasai pemberian saran afirmatif (V-ta hou ga ii)","Menguasai usulan santun (V-tara dou desu ka)"]},pocket_summary:{keyFormula:"Saran Lakukan: [V-Ta] ほう が いい / Saran Jangan: [V-Nai] ほう が いい",coreWords:["くすり","ねつ","むり","そうだん","おだいじに"],coreWarning:"Ingat rumus: V-ta untuk saran positif, V-nai untuk saran larangan.",quickDialogue:"A: 熱があります。 → B: 早く病院へ行ったほうがいいですよ。"}},"les-n4-u02-02":{pedagogical_framework:{what:{summary:"Menyatakan tindakan melampaui batas kewajaran (〜すぎる), serta membedakan tujuan tindakan berorientasi kehendak (〜ために) vs target kondisi kemampuan (〜ように).",canDo:"Bisa menjelaskan tindakan korektif saat bekerja terlalu lelah, serta mengungkapkan target tujuan belajar dan bekerja.",targetPatterns:["[Masu-Stem / Kata Sifat] すぎる (terlalu berlebihan)","[Kata Benda] の ために / [Verba Kamus Volisional] ために (demi / untuk tujuan)","[Verba Potensial / Non-Volisional] ように (agar / supaya menjadi)"],coreVocabSample:["はたらく","つかれる","ごうかく","めざす","しっぱい","ちゅうい","ねむい"]},sensei_context:{sceneIntro:"Di ruang evaluasi kerja mingguan. Tanaka-senpai memperhatikan Budi bekerja sangat keras hingga lembur berlebihan, lalu memberikan arahan mengenai efisiensi dan tujuan karier.",dailyMission:"Mampu menggunakan pola 〜すぎる untuk memperingatkan batas kelelahan, dan membedakan penggunaan 〜ために vs 〜ように secara akurat.",whyOrder:"Setelah bisa memberikan saran di Lesson 1, pembelajar harus mampu menganalisis alasan di balik kelelahan (terlalu banyak) dan tujuan perbaikan (agar bisa lulus ujian)."},cultural_notes:{title:"Bahaya Karoushi (過労死) dan Gerakan Work-Life Balance di Jepang Modern",etiquette:'Dahulu lembur dipandang sebagai bukti loyalitas, namun perusahaan Jepang modern sangat ketat melarang jam kerja berlebih demi mencegah kelelahan fatal. Melaporkan bahwa pekerjaan "terlalu berat" (haitatsu ga oosugiru) adalah tindakan preventif yang bertanggung jawab.',taboos:"Jangan memakai 〜ために untuk kata kerja kemampuan atau kata kerja negatif (seperti goukaku dekiru tame ni / wasurenai tame ni); situasi tersebut wajib memakai 〜ように."},pronunciation_tips:{title:'Penekanan Aksentuasi pada Pola "Sugiru"',moraNote:'Kata "sugiru" bergabung langsung dengan akar kata: Hatara-ki-su-gi-ru (6 mora). Tidak ada jeda spasi.',soundTip:"Pada kata sifat-i: buang [i], lalu sambung: Takai -> Taka-sugiru, Samui -> Samu-sugiru."},common_pitfalls:[{title:"Tertukar Antara 〜ために (Volisional) vs 〜ように (Kondisi/Potensial)",caseScenario:'Mengatakan "Demi bisa membeli mobil" menggunakan tame ni.',pitfallWarning:'"車【くるま】が 買【か】える ために、貯金【ちょきん】します。" (Salah)',rightSolution:'"車【くるま】が 買【か】える ように、貯金【ちょきん】します。" (Benar)',explanation:"Verba potensial (買える) menunjukkan kondisi kemampuan, bukan tindakan kemauan langsung. Kata kerja kemampuan selalu dipasangkan dengan 〜ように."},{title:"Lupa Menghilangkan Akhiran [I] pada Kata Sifat Sebelum Sugiru",caseScenario:'Menggabungkan bentuk utuh takai ke sugiru: "takaisugiru".',pitfallWarning:'"この 荷物【にもつ】は 重【おも】いすぎます。"',rightSolution:'"この 荷物【にもつ】は 重【おも】すぎます。"',explanation:"Pada kata sifat-i, huruf [i] terakhir wajib dibuang sebelum disambung dengan 〜すぎる (Omoi -> Omosugiru)."}],who_and_when:{situational_context:"Saat briefing evaluasi beban kerja, konsultasi kesehatan, atau menyusun target rencana studi magang.",social_relations:"Ragam sopan (Teineigo) yang tepat dalam diskusi formal dengan atasan dan mentor.",when_not_to_use:"Jangan gunakan 〜すぎる sebagai pujian murni kepada atasan, karena kata ini berkonotasi melampaui batas wajar/bermasalah."},scenario:{title:"Evaluasi Beban Kerja & Target Ujian JLPT",setting:"Ruang rapat departemen, pukul 17.30",narrative:"Tanaka-senpai mengingatkan Budi agar tidak bekerja terlalu larut demi menjaga stamina ujian."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ブディさん、最近【さいきん】残業【ざんぎょう】が 多【おお】すぎますよ。大丈夫【だいじょうぶ】ですか。",furigana:"ブディさん、最近残業が 多すぎますよ。大丈夫ですか。",romaji:"Budi-san, saikin zangyou ga oosugimasu yo. Daijoubu desu ka.",idText:"Budi-san, akhir-akhir ini lemburnya terlalu banyak lho. Apakah kamu baik-baik saja?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"田中【たなか】さん、すみません。仕事【しごと】を 覚【おぼ】える ために、頑張【がんば】りすぎてしまいました。",furigana:"田中さん、すみません。仕事を 覚える ために、頑張りすぎてしまいました。",romaji:"Tanaka-san, sumimasen. Shigoto o oboeru tame ni, gambarisugite shimaimashita.",idText:"Tanaka-san, mohon maaf. Demi menguasai pekerjaan, saya jadi terlalu memaksakan diri berusaha."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"熱心【ねっしん】なのは いいですが、働【はたら】きすぎると 集中力【しゅうちゅうりょく】が 落【お】ちて ミスが 増【ふ】えます。",furigana:"熱心なのは いいですが、働きすぎると 集中力が 落ちて ミスが 増えます。",romaji:"Nesshin na no wa ii desu ga, hatarakisugiru to shuuchuuryoku ga ochite misu ga fuemasu.",idText:"Bersemangat itu bagus, tapi kalau bekerja terlalu keras konsentrasi akan turun dan kesalahan meningkat."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、昨日【きのう】も 眠【ねむ】すぎて レポートの 数字【すうじ】を 間違【まちが】えてしまいました。",furigana:"はい、昨日も 眠すぎて レポートの 数字を 間違えてしまいました。",romaji:"Hai, kinou mo nemusugite repo-to no suuji o machigaete shimaimashita.",idText:"Iya, kemarin pun karena terlalu mengantuk saya sempat salah mengisi angka laporan."},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"失敗【しっぱい】を 防【ふせ】ぐ ように、確認【かくにん】チェックリストを 作【つく】りましょう。",furigana:"失敗を 防ぐ ように、確認チェックリストを 作りましょう。",romaji:"Shippai o fusegu you ni, kakunin chekkurisuto o tsukurimashou.",idText:"Agar bisa mencegah kesalahan, mari kita buat daftar periksa konfirmasi."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ありがとうございます！試験【しけん】に 合格【ごうかく】できる ように、体調【たいちょう】も 整【ととの】えます。",furigana:"ありがとうございます！試験に 合格できる ように、体調も 整えます。",romaji:"Arigatou gozaimasu! Shiken ni goukaku dekiru you ni, taichou mo totonoemasu.",idText:"Terima kasih banyak! Agar bisa lulus ujian, saya juga akan mengatur kondisi fisik."},{id:"d7",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"その 心意気【こころいき】です！夢【ゆめ】の ために、まずは 体【からだ】を 大切【たいせつ】にしてください。",furigana:"その 心意気です！夢の ために、まずは 体を 大切にしてください。",romaji:"Sono kokoroiki desu! Yume no tame ni, mazu wa karada o taisetsu ni shite kudasai.",idText:"Itu baru semangat yang tepat! Demi impianmu, pertama-tama jagalah tubuhmu baik-baik."}],vocab_breakdown:[{id:"vg-n4-00498",word:"大体",reading:"だいたい",romaji:"daitai",meaning:"umumnya; kira-kira",pos:"adverb",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"試験の準備は大体終わったので安心しました。",furigana:"試験の準備は大体終わったので安心しました。",romaji:"",idText:"Persiapan untuk ujian kira-kira sudah selesai sehingga saya merasa tenang."}},{id:"vg-n4-00499",word:"大分",reading:"だいぶ",romaji:"daibu",meaning:"cukup banyak; jauh lebih",pos:"adverb",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"毎朝走るようになってから、体が大分軽くなりました。",furigana:"毎朝走るようになってから、体が大分軽くなりました。",romaji:"",idText:"Sejak mulai berlari setiap pagi, tubuh saya terasa jauh lebih ringan."}},{id:"vg-n4-00038",word:"台風",reading:"たいふう",romaji:"taifuu",meaning:"topan, taifun",pos:"noun",nuance:"台風 = topan/taifun. 台風が来る. Fenomena alam khas Jepang musim panas-gugur.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"台風のため、学校が休みになりました。",furigana:"台風のため、学校が休みになりました。",romaji:"",idText:"Karena topan, sekolah diliburkan."}},{id:"vg-n4-00042",word:"海",reading:"うみ",romaji:"umi",meaning:"laut",pos:"noun",nuance:"海 (うみ) = laut/pantai. 海に行く = pergi ke pantai. Lawan: 山 (やま).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"夏は海で泳ぎたいです。",furigana:"夏は海で泳ぎたいです。",romaji:"",idText:"Di musim panas saya ingin berenang di laut."}},{id:"vg-n4-00060",word:"送料",reading:"そうりょう",romaji:"souryou",meaning:"biaya pengiriman",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"本を３冊注文したら送料が無料になりました。",furigana:"本を３冊注文したら送料が無料になりました。",romaji:"",idText:"Ketika memesan tiga buku, ongkos kirimnya menjadi gratis."}},{id:"vg-n4-00088",word:"部分",reading:"ぶぶん",romaji:"bubun",meaning:"bagian",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"文章の難しい部分に辞書で印をつけました。",furigana:"文章の難しい部分に辞書で印をつけました。",romaji:"",idText:"Saya menandai bagian kalimat yang sulit dengan kamus."}},{id:"vg-n4-00089",word:"全部",reading:"ぜんぶ",romaji:"zenbu",meaning:"semua, seluruhnya",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"宿題を全部終わらせてから遊びに行きました。",furigana:"宿題を全部終わらせてから遊びに行きました。",romaji:"",idText:"Setelah menyelesaikan semua PR, saya pergi bermain."}},{id:"vg-n4-00122",word:"図書館",reading:"としょかん",romaji:"toshokan",meaning:"perpustakaan",pos:"noun",nuance:"図書館 = perpustakaan. 本を借りる. 図書館は静かなので勉強しやすい。",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"図書館で日本語の本を借りました。",furigana:"図書館で日本語の本を借りました。",romaji:"",idText:"Saya meminjam buku bahasa Jepang di perpustakaan."}},{id:"vg-n4-00148",word:"参考",reading:"さんこう",romaji:"sankou",meaning:"referensi",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"先輩のアドバイスを参考にして計画を立てました。",furigana:"先輩のアドバイスを参考にして計画を立てました。",romaji:"",idText:"Saya menyusun rencana dengan menjadikan saran senior sebagai referensi."}},{id:"vg-n4-00149",word:"知識",reading:"ちしき",romaji:"chishiki",meaning:"pengetahuan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"本をたくさん読んで広い知識を身につけたいです。",furigana:"本をたくさん読んで広い知識を身につけたいです。",romaji:"",idText:"Saya ingin membaca banyak buku untuk memperoleh pengetahuan yang luas."}}],explanations:[{id:"exp-1",grammarId:"gn4-00068",title:"Pola: 〜すぎる",formula:"V-ます語幹 / Adj-i語幹 / Adj-na + すぎる",meaning:"terlalu ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜すぎる",idText:"terlalu ..."}],examples:[{jp:"このカレーは辛すぎます。",romaji:"",idText:"Kari ini terlalu pedas."},{jp:"昨日飲みすぎた。",romaji:"",idText:"Kemarin terlalu banyak minum."}]},{id:"exp-2",grammarId:"gn4-00042",title:"Pola: Nのために / Vるために",formula:"N + のために / Vる + ために",meaning:"untuk ... / demi ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Nのために / Vるために",idText:"untuk ... / demi ..."}],examples:[{jp:"日本語を学ぶために、毎日練習しています。",romaji:"",idText:"Untuk belajar bahasa Jepang, saya berlatih setiap hari."},{jp:"家族のために、一生懸命働きます。",romaji:"",idText:"Saya bekerja keras demi keluarga."}]},{id:"exp-3",grammarId:"gn4-00071",title:"Pola: こんな / そんな / あんな / どんな + N",formula:"こんな/そんな/あんな/どんな + N",meaning:"seperti ini / seperti itu / seperti apa (modifikasi nominal)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"こんな / そんな / あんな / どんな + N",idText:"seperti ini / seperti itu / seperti apa (modifikasi nominal)"}],examples:[{jp:"こんな問題は難しいですね。",romaji:"",idText:"Soal seperti ini memang susah ya."},{jp:"どんな音楽が好きですか。",romaji:"",idText:"Kamu suka musik seperti apa?"}]},{id:"exp-4",grammarId:"gn4-00072",title:"Pola: こう / そう / ああ / どう + V",formula:"こう/そう/ああ/どう + V",meaning:"dengan cara ini / seperti itu / bagaimana (cara/metode)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"こう / そう / ああ / どう + V",idText:"dengan cara ini / seperti itu / bagaimana (cara/metode)"}],examples:[{jp:"こうすればいいですよ。",romaji:"",idText:"Lakukan seperti ini saja."},{jp:"この問題はどう解きますか。",romaji:"",idText:"Bagaimana cara mengerjakan soal ini?"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah makna kata sifat "眠い (ねむい)" saat digabungkan menjadi "眠すぎる".',sentencePrompt:'Frasa "眠すぎる (ねむすぎる)" artinya:',options:["Terlalu mengantuk","Terlalu malas","Terlalu lapar","Terlalu dingin"],correctAnswer:"Terlalu mengantuk",explanation:"Nemui (mengantuk) dibuang [i] + sugiru -> Nemusugiru (terlalu mengantuk).",diagnosticFeedback:{"Terlalu malas":"Salah: Malas adalah めんどくさい atau 怠惰 (taida).","Terlalu lapar":"Salah: Lapar adalah お腹が空きすぎる (onaka ga skisugiru).","Terlalu dingin":"Salah: Dingin adalah 寒すぎる (samusugiru)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Pembedaan Pola): Lengkapi rumpang kalimat berikut dengan penghubung tujuan yang tepat untuk verba potensial "話せる (bisa berbicara)".',sentencePrompt:"日本語【にほんご】が 上手【じょうず】に 話【はな】せる _____、毎日【まいにち】練習【れんしゅう】しています。",options:["ように","ために","ので","から"],correctAnswer:"ように",explanation:"Kata kerja bentuk potensial (話せる = bisa berbicara) menunjukkan kondisi kemampuan, sehingga wajib berpasangan dengan ように, bukan ために.",diagnosticFeedback:{ために:"Salah: ために hanya dipasangkan dengan kata kerja volisional/kehendak tindakan langsung, bukan potensial.",ので:"Salah: ので menyatakan sebab-akibat alasan masa lalu/sekarang, bukan tujuan ke depan.",から:"Salah: から menyatakan alasan, bukan target maksud perbuatan."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Susunlah potongan kalimat untuk menyatakan makan terlalu banyak saat pesta makan malam.",sentencePrompt:"Susunan kalimat yang tepat:",options:["晩【ばん】ごはんを 食【た】べすぎて お腹【なか】が 痛【いた】いです","お腹【なか】が 食【た】べすぎて 晩【ばん】ごはんを 痛【いた】いです","食【た】べすぎて 痛【いた】いです 晩【ばん】ごはんを お腹【なか】が","晩【ばん】ごはんを 痛【いた】いです お腹【なか】が 食【た】べすぎて"],correctAnswer:"晩【ばん】ごはんを 食【た】べすぎて お腹【なか】が 痛【いた】いです",explanation:"Objek (晩ごはんを) + Verba-Te Sugite (食べすぎて) + Akibat (お腹が痛いです).",diagnosticFeedback:{"お腹【なか】が 食【た】べすぎて 晩【ばん】ごはんを 痛【いた】いです":"Salah: Urutan klausa terbalik sehingga makna rancu.","食【た】べすぎて 痛【いた】いです 晩【ばん】ごはんを お腹【なか】が":"Salah: Predikat rasa sakit ditaruh sebelum objek kalimat.","晩【ばん】ごはんを 痛【いた】いです お腹【なか】が 食【た】べすぎて":"Salah: Pola sebab-akibat berantakan."},tokens:["晩【ばん】ごはんを","食【た】べすぎて","お腹【なか】が","痛【いた】いです"],correctOrder:["0","1","2","3"]},{id:"drill-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Jebakan Kata Sifat): Manakah penggabungan kata sifat-na "簡単 (かんたん)" dengan pola "すぎる" yang benar?',sentencePrompt:"Pilihlah bentuk yang tepat:",options:["この 問題【もんだい】は 簡単【かんたん】すぎます。","この 問題【もんだい】は 簡単【かんたん】なすぎます。","この 問題【もんだい】は 簡単【かんたん】だすぎます。","この 問題【もんだい】は 簡単【かんたん】にすぎます。"],correctAnswer:"この 問題【もんだい】は 簡単【かんたん】すぎます。",explanation:"Pada kata sifat-na, buang akhiran な/だ dan langsung tempelkan すぎる: 簡単 + すぎます = 簡単すぎます.",diagnosticFeedback:{"この 問題【もんだい】は 簡単【かんたん】なすぎます。":"Jebakan: Huruf な tidak boleh dipertahankan sebelum すぎる.","この 問題【もんだい】は 簡単【かんたん】だすぎます。":"Jebakan: Kopula だ tidak boleh disisipkan sebelum すぎる.","この 問題【もんだい】は 簡単【かんたん】にすぎます。":'Jebakan: に すぎます memiliki arti lain sama sekali ("hanya/sekadar").'}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Atasan melihat tumpukan dokumen di mejamu dan bertanya "書類【しょるい】の 量【りょう】は どうですか". Jawaban jika kamu kewalahan:',sentencePrompt:"Pilihlah tanggapan yang sopan dan jelas:",options:["一人【ひとり】では 多【おお】すぎますので、手伝【てつだ】って いただけますか。","一人【ひとり】では 少【すく】なすぎますので、もっと ください。","書類【しょるい】を 覚【おぼ】える ために、食【た】べすぎました。","書類【しょるい】の ために、病院【びょういん】へ 行【い】った ほう が いいです。"],correctAnswer:"一人【ひとり】では 多【おお】すぎますので、手伝【てつだ】って いただけますか。",explanation:"Menyatakan bahwa jumlahnya terlalu banyak (oosugimasu) dan memohon bantuan secara sopan.",diagnosticFeedback:{"一人【ひとり】では 少【すく】なすぎますので、もっと ください。":'Salah: Ini berarti "terlalu sedikit, tolong beri lagi".',"書類【しょるい】を 覚【おぼ】える ために、食【た】べすぎました。":'Konyol/Salah: "Demi mengingat dokumen, saya terlalu banyak makan".',"書類【しょるい】の ために、病院【びょういん】へ 行【い】った ほう が いいです。":"Salah: Konteks tidak nyambung."}}],can_do_challenge:{statement:"Bisa menjelaskan tindakan korektif saat bekerja terlalu lelah.",situation:"Melaporkan kepada supervisor bahwa beban kerja hari ini melebihi kapasitas.",promptTask:"Katakan bahwa barangnya terlalu berat sehingga kamu butuh bantuan!",modelAnswer:"この 荷物【にもつ】は 重【おも】すぎますので、手伝【てつだ】ってください。",modelAnswerId:"Barang ini terlalu berat, jadi tolong bantu saya.",culturalEtiquette:"Ucapkan dengan sopan tanpa terkesan mengeluh emosional.",skillUnlocked:["Menguasai pola berlebih 〜すぎる","Mampu membedakan tujuan 〜ために vs 〜ように"]},pocket_summary:{keyFormula:"[V-Stem / Adj] すぎる (berlebih) | [Potensial/Nai] ように (target kondisi)",coreWords:["はたらく","つかれる","しっぱい","めざす"],coreWarning:"Kata kerja potensial (bisa/mampu) selalu memakai ように, bukan ために.",quickDialogue:"A: どうして練習しますか。 → B: 上手に話せるように練習します。"}}},e={"les-n4-u03-01":{pedagogical_framework:{what:{summary:"Pola pembentukan kata kerja bentuk potensial (可能形 kanoukei) untuk menyatakan kemampuan/izin, serta membedakan persepsi indra spontan (聞こえる / 見える) vs tindakan aktif (聞く / 見る).",canDo:"Bisa menjelaskan keterampilan operasional dan melaporkan suara mesin yang terdengar aneh di tempat kerja.",targetPatterns:["[Verba Bentuk-Potensial] (bisa / dapat melakukan)","[Kata Benda] が 聞【き】こえる (terdengar secara spontan)","[Kata Benda] が 見【み】える (terlihat secara spontan)"],coreVocabSample:["はなせる","よめる","きこえる","みえる","おと","きかい","こしょう"]},sensei_context:{sceneIntro:"Di area pabrik atau bengkel kerja. Kenji dan Budi sedang mengecek mesin pemotong. Budi mendengar suara gemertak ganjil dari arah motor penggerak.",dailyMission:"Mampu mengonjugasikan kata kerja ke bentuk potensial (bisa mengoperasikan mesin) dan menggunakan partikel が bersama きこえる / みえる.",whyOrder:"Kemampuan teknis dan pelaporan anomali sensorik (suara aneh terdengar) adalah keterampilan hidup paling krusial bagi tenaga magang di industri Jepang."},cultural_notes:{title:"Pelaporan Bahaya Indra (五感による異常検知) di Pabrik Jepang",etiquette:'Ketika mendengar suara abnormal, operator Jepang pantang mendiamkannya. Mengatakan "Hen na oto ga kikoemasu" (Terdengar suara aneh) adalah tanda kepekaan K3 yang sangat dihargai.',taboos:'Partikel penanda objek pada bentuk potensial dan persepsi spontan berubah dari を menjadi が: "Nihongo GA hanaseru", "Oto GA kikoeru". Jangan memakai を!'},pronunciation_tips:{title:"Konjugasi Vokal e Panjang pada Ichidan",moraNote:'Pada verba Ichidan (Golongan 2): Taberu -> Taberareru (5 mora). Dalam percakapan santai modern sering dipersingkat menjadi "Tabereru" (Ra-nuki kotoba), namun dalam tes JLPT wajib bentuk utuh.',soundTip:"Kikoeru dilafalkan mengalir 4 mora: ki-ko-e-ru. Jangan ditekan pada akhiran ru."},common_pitfalls:[{title:"Memakai Partikel を untuk Objek Bentuk Potensial & Kikoeru/Mieru",caseScenario:'Refleks mentransfer objek "o" ke kalimat kemampuan: "Nihongo o hanasemasu".',pitfallWarning:'"私【わたし】は 日本語【にほんご】を 話【はな】せます。" (Kurang alami)',rightSolution:'"私【わたし】は 日本語【にほんご】が 話【はな】せます。" (Alami & Baku)',explanation:"Bentuk potensial dan verba persepsi spontan (kikoeru, mieru) menuntut partikel penanda subjek kemampuan が."},{title:"Tertukar Antara 見える (Spontan) vs 見られる (Kemampuan/Peluang)",caseScenario:'Ingin mengatakan "Dari sini kita bisa menonton film" menggunakan mieru.',pitfallWarning:'"ここから 映画【えいが】が 見【み】えます。" (Salah konteks)',rightSolution:'"ここから 映画【えいが】が 見【み】られます。" (Bisa menonton)',explanation:"見える berarti objek masuk ke pandangan mata secara alami tanpa usaha (seperti gunung terlihat). Menonton film adalah aktivitas berkesadaran, maka gunakan 見られる."}],who_and_when:{situational_context:"Pemeriksaan operasional mesin di pabrik, percakapan kemampuan bahasa, atau pelaporan anomali lingkungan.",social_relations:"Ragam sopan standar (Teineigo) yang penting saat berkoordinasi dengan mekanik atau pimpinan tim.",when_not_to_use:'Jangan memakai kata potensial "dekimasu" secara berlebihan tanpa menyebutkan keterampilan spesifiknya.'},scenario:{title:"Deteksi Suara Aneh pada Mesin Produksi",setting:"Lantai produksi pabrik komponen otomotif, pukul 10.15",narrative:"Budi mendengar suara berisik dari mesin nomor 3 dan langsung memberi tahu Kenji."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ケンジさん、ちょっと 来【き】てください。変【へん】な 音【おと】が 聞【き】こえます。",furigana:"ケンジさん、ちょっと 来てください。変な 音が 聞こえます。",romaji:"Kenji-san, chotto kite kudasai. Hen na oto ga kikoemasu.",idText:"Kenji-san, tolong ke sini sebentar. Terdengar suara aneh."},{id:"d2",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"えっ、本当【ほんとう】？どこから 聞【き】こえる？",furigana:"えっ、本当？どこから 聞こえる？",romaji:"E, hontou? Doko kara kikoeru?",idText:"Eh, sungguhan? Terdengar dari mana?"},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"３号機【さんごうき】の モーターの あたりから カタカタと 聞【き】こえます。",furigana:"３号機の モーターの あたりから カタカタと 聞こえます。",romaji:"Sangouki no mo-ta- no atari kara katakata to kikoemasu.",idText:"Dari sekitar motor mesin nomor 3 terdengar bunyi gemertak."},{id:"d4",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"危【あぶ】ないね。すぐに 非常停止【ひじょうていし】ボタンが 押【お】せる？",furigana:"危ないね。すぐに 非常停止ボタンが 押せる？",romaji:"Abunai ne. Sugu ni hijou teishi botan ga oseru?",idText:"Bahaya itu ya. Apakah kamu bisa segera menekan tombol henti darurat?"},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、押【お】せます！すぐ 止【と】めました。",furigana:"はい、押せます！すぐ 止めました。",romaji:"Hai, osemasu! Sugu tomemashita.",idText:"Ya, saya bisa menekan! Sudah langsung saya matikan."},{id:"d6",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"よく 気【き】がつきましたね！早【はや】く 発見【はっけん】できたので 事故【じこ】が 防【ふせ】げました。",furigana:"よく 気がつきましたね！早く 発見できたので 事故が 防げました。",romaji:"Yoku ki ga tsukimashita ne! Hayaku hakken dekita node jiko ga fusegemashita.",idText:"Bagus sekali kamu menyadarinya! Karena bisa cepat ditemukan, kecelakaan bisa dicegah."},{id:"d7",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"よかったです！マニュアルの 警告【けいこく】が 読【よ】める ように 勉強【べんきょう】していました。",furigana:"よかったです！マニュアルの 警告が 読める ように 勉強していました。",romaji:"Yokatta desu! Manyuaru no keikoku ga yomeru you ni benkyou shite imashita.",idText:"Syukurlah! Saya memang sudah belajar agar bisa membaca peringatan manual."}],vocab_breakdown:[{id:"vg-n4-00001",word:"動く",reading:"うごく",romaji:"ugoku",meaning:"bergerak",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"この機械はボタンを押すと動きます。",furigana:"この機械はボタンを押すと動きます。",romaji:"",idText:"Mesin ini bergerak jika tombolnya ditekan."}},{id:"vg-n4-00002",word:"動かす",reading:"うごかす",romaji:"ugokasu",meaning:"menggerakkan",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"重い荷物を一人で動かしました。",furigana:"重い荷物を一人で動かしました。",romaji:"",idText:"Saya memindahkan barang berat itu sendirian."}},{id:"vg-n4-00092",word:"引く",reading:"ひく",romaji:"hiku",meaning:"menarik",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"ドアを押さないで手前に引いて開けてください。",furigana:"ドアを押さないで手前に引いて開けてください。",romaji:"",idText:"Jangan mendorong pintu, tolong tarik ke arah Anda untuk membukanya."}},{id:"vg-n4-00112",word:"話し合う",reading:"はなしあう",romaji:"hanashiau",meaning:"berdiskusi",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"旅行の計画についてみんなで話し合いました。",furigana:"旅行の計画についてみんなで話し合いました。",romaji:"",idText:"Kami semua berdiskusi mengenai rencana perjalanan."}},{id:"vg-n4-00124",word:"建てる",reading:"たてる",romaji:"tateru",meaning:"membangun, mendirikan",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"将来田舎に静かで広い家を建てたいです。",furigana:"将来田舎に静かで広い家を建てたいです。",romaji:"",idText:"Di masa depan saya ingin membangun rumah luas dan tenang di desa."}},{id:"vg-n4-00136",word:"変わる",reading:"かわる",romaji:"kawaru",meaning:"berubah",pos:"verb-u",nuance:"変わる = berubah (intransitif). Transitif: 変える. 変わった人 = orang yang unik/aneh.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"季節が変わりました。",furigana:"季節が変わりました。",romaji:"",idText:"Musimnya sudah berganti."}},{id:"vg-n4-00137",word:"変える",reading:"かえる",romaji:"kaeru",meaning:"mengubah",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"気分を変えるために部屋の模様替えをしました。",furigana:"気分を変えるために部屋の模様替えをしました。",romaji:"",idText:"Saya menata ulang kamar untuk menyegarkan suasana hati."}},{id:"vg-n4-00139",word:"直す",reading:"なおす",romaji:"naosu",meaning:"memperbaiki",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"壊れた時計を時計屋さんに持って行って直しました。",furigana:"壊れた時計を時計屋さんに持って行って直しました。",romaji:"",idText:"Saya membawa jam yang rusak ke toko jam untuk diperbaiki."}},{id:"vg-n4-00140",word:"直る",reading:"なおる",romaji:"naoru",meaning:"diperbaiki, sembuh",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"パソコンの調子が悪かったですが、すぐに直りました。",furigana:"パソコンの調子が悪かったですが、すぐに直りました。",romaji:"",idText:"Komputer sempat bermasalah, tapi langsung normal kembali."}},{id:"vg-n4-00169",word:"渡る",reading:"わたる",romaji:"wataru",meaning:"menyeberang",pos:"verb-u",nuance:"渡る = menyeberang. 横断歩道を渡る = menyeberang di zebra cross.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"信号が青になってから渡ってください。",furigana:"信号が青になってから渡ってください。",romaji:"",idText:"Tolong seberang setelah lampu menjadi hijau."}}],explanations:[{id:"exp-1",grammarId:"gn4-00031",title:"Pola: 動詞可能形 (bentuk potensial)",formula:"V1 (godan): Vない → えない/える; V2 (ichidan): V → られる/れる (kasual)",meaning:"bisa ... / mampu ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"動詞可能形 (bentuk potensial)",idText:"bisa ... / mampu ..."}],examples:[{jp:"私は日本語が話せます。",romaji:"",idText:"Saya bisa berbicara bahasa Jepang."},{jp:"この仕事は一人でできますか。",romaji:"",idText:"Bisakah pekerjaan ini dilakukan sendiri?"}]},{id:"exp-2",grammarId:"gn4-00066",title:"Pola: 聞こえる / 見える",formula:"N + が + 聞こえる (terdengar) / 見える (terlihat)",meaning:"terdengar / terlihat (persepsi alami)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"聞こえる / 見える",idText:"terdengar / terlihat (persepsi alami)"}],examples:[{jp:"外から音楽が聞こえます。",romaji:"",idText:"Dari luar terdengar musik."},{jp:"窓から富士山が見えます。",romaji:"",idText:"Gunung Fuji terlihat dari jendela."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah arti kata "非常停止 (ひじょうていし)".',sentencePrompt:'Istilah K3 "非常停止" pada panel mesin pabrik berarti:',options:["Penghentian darurat","Pemeriksaan rutin mingguan","Penyesuaian kecepatan putar","Pengisian daya listrik"],correctAnswer:"Penghentian darurat",explanation:'"非常 (hijou = darurat)" + "停止 (teishi = henti)".',diagnosticFeedback:{"Pemeriksaan rutin mingguan":"Salah: Pemeriksaan rutin adalah 定期点検 (teiki tenken).","Penyesuaian kecepatan putar":"Salah: Penyesuaian adalah 速度調整 (sokudo chousei).","Pengisian daya listrik":"Salah: Pengisian daya adalah 充電 (juuden)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Konjugasi Potensial): Pilihlah bentuk potensial yang tepat dari kata kerja "読む (よむ = membaca)".',sentencePrompt:"私【わたし】は 漢字【かんじ】の マニュアルが _____。",options:["読【よ】めます","読【よ】られます","読【よ】せます","読【よ】きます"],correctAnswer:"読【よ】めます",explanation:"Yomu adalah verba Golongan 1 (Godan). Vokal akhir -u berubah menjadi baris -e: yomu -> yomemasu.",diagnosticFeedback:{"読【よ】られます":"Salah: Akhiran -rareru hanya untuk verba Golongan 2 (Ichidan).","読【よ】せます":"Salah: Bentuk -seru adalah pembentukan kausatif, bukan potensial.","読【よ】きます":"Salah: Salah konjugasi vokal."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Susun potongan kata berikut untuk menyatakan bisa melihat pemandangan Gunung Fuji dari jendela kantor.",sentencePrompt:"Susunan kalimat yang tepat:",options:["窓【まど】から 富士山【ふじさん】が 見【み】えます","富士山【ふじさん】が 窓【まど】から 見【み】ます","見【み】えます 窓【まど】から 富士山【ふじさん】が","窓【まど】から 見【み】ます 富士山【ふじさん】が"],correctAnswer:"窓【まど】から 富士山【ふじさん】が 見【み】えます",explanation:"Tempat asal (窓から) + Objek alami (富士山が) + Mieru (見える).",diagnosticFeedback:{"富士山【ふじさん】が 窓【まど】から 見【み】ます":"Salah: Verba 見ます adalah melihat aktif berkesadaran, bukan penampakan alami.","見【み】えます 窓【まど】から 富士山【ふじさん】が":"Salah: Verba tidak boleh ditaruh di depan subjek.","窓【まど】から 見【み】ます 富士山【ふじさん】が":"Salah: Urutan kata terbalik."},tokens:["窓【まど】から","富士山【ふじさん】が","見【み】えます"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:"Langkah 4 (Deteksi Jebakan Partikel): Manakah kalimat yang menggunakan partikel penanda objek kemampuan secara tepat?",sentencePrompt:"Pilihlah kalimat yang benar secara gramatikal:",options:["ブディさんは 日本語【にほんご】の 新聞【しんぶん】が 読【よ】めます。","ブディさんは 日本語【にほんご】の 新聞【しんぶん】を 読【よ】めます。","ブディさんは 日本語【にほんご】の 新聞【しんぶん】で 読【よ】めます。","ブディさんは 日本語【にほんご】の 新聞【しんぶん】に 読【よ】めます。"],correctAnswer:"ブディさんは 日本語【にほんご】の 新聞【しんぶん】が 読【よ】めます。",explanation:"Bentuk kemampuan (読める) secara baku berpasangan dengan partikel が untuk menandai objek yang mampu dibaca.",diagnosticFeedback:{"ブディさんは 日本語【にほんご】の 新聞【しんぶん】を 読【よ】めます。":"Jebakan: Partikel を kurang lazim dalam kalimat kemampuan standar JLPT N4.","ブディさんは 日本語【にほんご】の 新聞【しんぶん】で 読【よ】めます。":"Jebakan: Partikel で menandai alat atau sarana.","ブディさんは 日本語【にほんご】の 新聞【しんぶん】に 読【よ】めます。":"Jebakan: Partikel に menandai tujuan atau waktu."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Rekan kerjamu bertanya "隣【となり】の 部屋【へや】から 何【なに】か 音【おと】が しませんか". Respons terbaik:',sentencePrompt:"Pilihlah jawaban yang tepat untuk persepsi pendengaran spontan:",options:["はい、ピアノの 音【おと】が 聞【き】こえますね。","はい、ピアノの 音【おと】を 聞【き】きますね。","いいえ、何【なに】も 見【み】えません。","はい、ピアノを 弾【ひ】く つもりです。"],correctAnswer:"はい、ピアノの 音【おと】が 聞【き】こえますね。",explanation:"Suara yang terdengar tanpa sengaja diungkapkan dengan 音が 聞こえます.",diagnosticFeedback:{"はい、ピアノの 音【おと】を 聞【き】きますね。":"Salah: 聞きます berarti mendengarkan secara sengaja.","いいえ、何【なに】も 見【み】えません。":"Salah: Menjawab tentang penglihatan (mieru), padahal pertanyaannya suara.","はい、ピアノを 弾【ひ】く つもりです。":"Salah: Menjawab tentang niat pribadi memainkan piano."}}],can_do_challenge:{statement:"Bisa menjelaskan keterampilan operasional dan melaporkan suara mesin aneh.",situation:"Melaporkan kepada supervisor bahwa kamu sudah bisa mengoperasikan forklift pabrik.",promptTask:"Laporkan bahwa kamu sekarang sudah bisa mengemudikan forklift!",modelAnswer:"私【わたし】は フォークリフトの 運転【うんてん】が できます。",modelAnswerId:"Saya bisa mengemudikan forklift.",culturalEtiquette:"Sampaikan keterampilan dengan percaya diri dan siap diuji praktiknya.",skillUnlocked:["Menguasai bentuk potensial kata kerja (Kanoukei)","Mampu membedakan 聞こえる / 見える vs 聞く / 見る"]},pocket_summary:{keyFormula:"[Objek] が [Verba Potensial] / [Suara] が 聞こえる / [Objek] が 見える",coreWords:["はなせる","よめる","きこえる","みえる","おと"],coreWarning:"Ganti partikel を menjadi が saat kata kerja berubah ke bentuk potensial.",quickDialogue:"A: 日本語が話せますか。 → B: はい、少し話せます。"}},"les-n4-u03-02":{pedagogical_framework:{what:{summary:"Menyatakan proses perubahan bertahap dari tidak bisa menjadi bisa (〜ようになる) dan perubahan kondisi sifat (〜くなる / 〜になる).",canDo:"Bisa menceritakan peningkatan pemahaman bahasa Jepang dan adaptasi kehidupan selama magang di Jepang.",targetPatterns:["[Verba Bentuk Potensial / Kamus] ように なる (menjadi bisa / mulai terbiasa)","[Kata Sifat-i] くなる (menjadi [sifat])","[Kata Sifat-na / Kata Benda] に なる (menjadi [kondisi])"],coreVocabSample:["じょうず","わかる","なれる","へんか","せいかつ","かんじ","ぶんか"]},sensei_context:{sceneIntro:"Di meja makan malam asrama. Sakura dan Budi mengobrol santai mengenai perkembangan belajar Budi setelah 6 bulan tinggal di Tokyo.",dailyMission:"Mampu menggunakan pola 〜ようになる untuk memaparkan proses kemajuan diri dari yang awalnya tidak paham menjadi mengerti.",whyOrder:"Setelah menguasai bentuk kemampuan statis di Lesson 1 (kanoukei), Lesson 2 mengajarkan dinamika waktu: transformasi dari masa lalu ke masa kini."},cultural_notes:{title:'Konsep "Seichou" (成長 - Pertumbuhan Diri) dalam Budaya Evaluasi Jepang',etiquette:'Orang Jepang sangat menghargai proses kemajuan yang konsisten. Mampu merendah sembari mengakui kemajuan ("Dahulu tidak paham, sekarang berkat bimbingan senpai saya jadi bisa") adalah bentuk kerendahhatian (Kenjou) yang sangat disukai.',taboos:"Jangan memakai 〜ようになる untuk perubahan mendadak yang terjadi dalam sekejap; pola ini khusus untuk proses yang berangsur-angsur berkembang seiring waktu."},pronunciation_tips:{title:'Kelancaran Pelafalan "You ni narimashita"',moraNote:'Rangkaian frasa: yo-u-ni-na-ri-ma-shi-ta (8 mora). Sambungkan vokal "you" secara halus ke "ni".',soundTip:'Pada perubahan kata sifat: Yoi (bagus) menjadi "Yoku narimashita", bukan "ikunarimashita".'},common_pitfalls:[{title:'Salah Bentuk Kata Sifat "Yoi (Bagus)" Saat Diubah ke Menjadi',caseScenario:'Mengubah kata bagus ii/yoi menjadi "iinatta" atau "ikunatta".',pitfallWarning:'"日本語【にほんご】が いいになりました。" (Salah fatal)',rightSolution:'"日本語【にほんご】が よく なりました。" (Benar)',explanation:"Kata sifat いい berakar dari 良い (よい). Bentuk perubahannya wajib memakai よい: 良く なりました."},{title:"Memasukkan Kata Kerja Bentuk Masu Sebelum You ni naru",caseScenario:'Menyambung bentuk masu langsung: "wakarimasu you ni narimashita".',pitfallWarning:'"漢字【かんじ】が 分【わ】かります ように なりました。"',rightSolution:'"漢字【かんじ】が 分【わ】かる ように なりました。"',explanation:"Pola 〜ようになる hanya menerima bentuk kamus biasa (Jishokei), terutama verba potensial atau verba non-volisional seperti 分かる."}],who_and_when:{situational_context:"Saat wawancara perpanjangan kontrak magang, pidato perpisahan, atau refleksi belajar bersama mentor.",social_relations:"Ragam sopan (Teineigo) yang memberikan kesan positif dan dedikasi tinggi.",when_not_to_use:"Jangan gunakan pada benda mati yang mengalami kerusakan fisik (misal mesin rusak gunakan kowaremashita)."},scenario:{title:"Refleksi Kemajuan 6 Bulan Tinggal di Tokyo",setting:"Dapur bersama asrama pembelajar internasional, pukul 19.30",narrative:"Sakura kagum melihat Budi sekarang bisa membaca kemasan bumbu masakan Jepang tanpa kamus."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Mentor Pembelajar",avatar:"👩‍🏫",jp:"ブディさん、調味料【ちょうみりょう】の 漢字【かんじ】が 読【よ】めたの？すごいですね！",furigana:"ブディさん、調味料の 漢字が 読めたの？すごいですね！",romaji:"Budi-san, choumiryou no kanji ga yometa no? Sugoi desu ne!",idText:"Budi-san, kamu bisa membaca kanji bumbu dapur tadi? Hebat sekali ya!"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ありがとうございます！最初【さいしょ】は 全然【ぜんぜん】分【わ】かりませんでしたが、最近【さいきん】少【すこ】し 分【わ】かる ように なりました。",furigana:"ありがとうございます！最初は 全然分かりませんでしたが、最近少し 分かる ように なりました。",romaji:"Arigatou gozaimasu! Saisho wa zenzen wakarimasen deshita ga, saikin sukoshi wakaru you ni narimashita.",idText:"Terima kasih banyak! Awalnya saya sama sekali tidak paham, tapi akhir-akhir ini sudah mulai mengerti."},{id:"d3",speaker:"Sakura",speakerRole:"Mentor Pembelajar",avatar:"👩‍🏫",jp:"日本【にほん】の 生活【せいかつ】にも だいぶ 慣【な】れましたね。",furigana:"日本の 生活にも だいぶ 慣れましたね。",romaji:"Nihon no seikatsu ni mo daibu naremashita ne.",idText:"Kamu juga sudah banyak terbiasa dengan kehidupan di Jepang ya."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、電車【でんしゃ】の 乗【の】り換【か】えも 一人【ひとり】で スムーズに できる ように なりました。",furigana:"はい、電車の 乗り換えも 一人で スムーズに できる ように なりました。",romaji:"Hai, densha no norikae mo hitori de sumu-zu ni dekiru you ni narimashita.",idText:"Iya, transit pindah kereta pun sekarang sudah bisa saya lakukan sendirian dengan lancar."},{id:"d5",speaker:"Sakura",speakerRole:"Mentor Pembelajar",avatar:"👩‍🏫",jp:"発音【はつおん】も とても 自然【しぜん】に なりましたよ。毎日【まいにち】の 努力【どりょく】の おかげですね。",furigana:"発音も とても 自然に なりましたよ。毎日の 努力の おかげですね。",romaji:"Hatsuon mo totemo shizen ni narimashita yo. Mainichi no doryoku no okage desu ne.",idText:"Pelafalanmu juga sudah menjadi sangat alami lho. Ini semua berkat kerja keras harianmu ya."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"さくらさんが いつも 親切【しんせつ】に 教【おし】えてくださる おかげです。もっと 上手【じょうず】に なりたいです！",furigana:"さくらさんが いつも 親切に 教えてくださる おかげです。もっと 上手に なりたいです！",romaji:"Sakura-san ga itsumo shinsetsu ni oshiete kudasaru okage desu. Motto jouzu ni naritai desu!",idText:"Ini berkat Sakura-san yang selalu mengajari saya dengan ramah. Saya ingin menjadi lebih mahir lagi!"}],vocab_breakdown:[{id:"vg-n4-00849",word:"折れる",reading:"おれる",romaji:"oreru",meaning:"patah, terlipat, membelok",pos:"verb-ru",nuance:"Kata kerja intransitif (ichidan) yang menunjukkan benda panjang atau kaku patah menjadi dua bagian (seperti ranting pohon, pensil, tulang) atau berbelok arah. Berbeda dengan 割れる (wareru) yang dipakai khusus untuk benda datar atau kaca yang pecah berantakan.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"強い台風の風で庭の木の枝が折れてしまいました。",furigana:"強い台風の風で庭の木の枝が折れてしまいました。",romaji:"",idText:"Dahan pohon di halaman patah akibat kencangnya tiupan angin topan."}},{id:"vg-n4-00871",word:"～おわる",reading:"～おわる",romaji:"~owaru",meaning:"selesai (melakukan sesuatu)",pos:"verb-u",nuance:"Pola bentukan kata kerja majemuk (akar bentuk masu + 終わる) yang menunjukkan tuntasnya pelaksanaan suatu pekerjaan atau kegiatan hingga akhir. Lawan katanya adalah ～始める (mulai melakukan sesuatu).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"宿題を全部やり終わったら、大好きなテレビ番組を見てもいいですよ。",furigana:"宿題を全部やり終わったら、大好きなテレビ番組を見てもいいですよ。",romaji:"",idText:"Kalau sudah selesai mengerjakan semua PR, boleh menonton acara televisi favorit lho."}},{id:"vg-n4-00883",word:"空く",reading:"すく",romaji:"suku",meaning:"menjadi sepi, lengang, menjadi lapar (perut)",pos:"verb-u",nuance:"Kata kerja intransitif (godan) yang menunjukkan situasi tempat berkurang kepadatannya (seperti 道が空いている = jalanan lancar/lengang). Sering pula dipakai untuk kondisi perut lapar (お腹が空いた). Berbeda dengan bacaan 'あく' (aku) yang berarti kursi atau wadah kosong tak terisi.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"昼休みが過ぎたので、店内の席がだいぶ空いてきました。",furigana:"昼休みが過ぎたので、店内の席がだいぶ空いてきました。",romaji:"",idText:"Karena jam makan siang telah lewat, kursi di dalam toko mulai cukup lengang."}},{id:"vg-n4-00921",word:"汚れる",reading:"よごれる",romaji:"yogoreru",meaning:"menjadi kotor; ternoda",pos:"verb-ru",nuance:"Kata kerja intransitif ichidan. Menunjukkan pakaian, badan, atau perabot rumah terkena noda, debu, atau lumpur sehingga tidak bersih lagi. Pasangan transitifnya adalah 汚す (yogosu, mengotori).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"泥だらけの道で遊んだので靴やズボンがひどく汚れました。",furigana:"泥だらけの道で遊んだので靴やズボンがひどく汚れました。",romaji:"",idText:"Karena bermain di jalanan berlumpur, sepatu dan celana saya menjadi sangat kotor."}},{id:"vg-n4-00993",word:"下りる",reading:"おりる",romaji:"oriru",meaning:"turun (kendaraan)",pos:"verb-ru",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"一行は、歩いてその山を下りた。",furigana:"一行は、歩いてその山を下りた。",romaji:"",idText:"Rombongan itu berjalan menuruni gunung."}},{id:"vg-n4-01066",word:"下げる",reading:"さげる",romaji:"sageru",meaning:"menggantung",pos:"verb-ru",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"ラジオの音を下げてくれませんか。",furigana:"ラジオの音を下げてくれませんか。",romaji:"",idText:"Could you turn down the radio?"}},{id:"vg-n4-01069",word:"触る",reading:"さわる",romaji:"sawaru",meaning:"sentuh",pos:"verb-u",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"触らずそのままにしておきなさい。",furigana:"触らずそのままにしておきなさい。",romaji:"",idText:"Don't touch it. Leave it as it is."}},{id:"vg-n4-01120",word:"生活",reading:"せいかつ",romaji:"seikatsu",meaning:"tinggal / hidup",pos:"verb-suru",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"どのようにして生活していきますか。",furigana:"どのようにして生活していきますか。",romaji:"",idText:"How are you getting along?"}},{id:"vg-n4-01121",word:"生産",reading:"せいさん",romaji:"seisan",meaning:"menghasilkan",pos:"verb-suru",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"この工場はＣＤプレーヤーを生産している。",furigana:"この工場はＣＤプレーヤーを生産している。",romaji:"",idText:"This factory produces CD players."}},{id:"vg-n4-01143",word:"大体",reading:"だいたい",romaji:"daitai",meaning:"secara umum",pos:"adverb",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"それらはだいたい同じくらいの大きさだ。",furigana:"それらはだいたい同じくらいの大きさだ。",romaji:"",idText:"Mereka more or less the same size."}}],explanations:[{id:"exp-1",grammarId:"gn4-00040",title:"Pola: Vようになる",formula:"Vる/Vない + ようになる",meaning:"menjadi bisa ... / mulai bisa ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vようになる",idText:"menjadi bisa ... / mulai bisa ..."}],examples:[{jp:"練習したら、泳げるようになりました。",romaji:"",idText:"Setelah berlatih, saya jadi bisa berenang."},{jp:"日本に来てから、早起きするようになりました。",romaji:"",idText:"Sejak datang ke Jepang, saya mulai terbiasa bangun pagi."}]},{id:"exp-2",grammarId:"gn4-00043",title:"Pola: 〜くする / 〜にする",formula:"Adj-i語幹 + くする / Adj-na/N + にする",meaning:"membuat menjadi ... / menjadikan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜くする / 〜にする",idText:"membuat menjadi ... / menjadikan ..."}],examples:[{jp:"音を大きくしてください。",romaji:"",idText:"Tolong keraskan volumenya."},{jp:"部屋をきれいにしました。",romaji:"",idText:"Saya membereskan kamar."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah padanan makna kata "慣れる (なれる)".',sentencePrompt:'Kata "慣れる" dalam konteks adaptasi lingkungan baru berarti:',options:["Terbiasa / Menyesuaikan diri","Merasa lelah","Lupa ingatan","Berubah pikiran"],correctAnswer:"Terbiasa / Menyesuaikan diri",explanation:'"慣れる (nareru)" berarti menjadi terbiasa setelah melalui pembiasaan waktu.',diagnosticFeedback:{"Merasa lelah":"Salah: Merasa lelah adalah 疲れる (tsukareru).","Lupa ingatan":"Salah: Lupa adalah 忘れる (wasureru).","Berubah pikiran":"Salah: Berubah pikiran adalah 気が変わる (ki ga kawaru)."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Isian Tepat): Lengkapi rumpang kalimat untuk menyatakan perubahan kata sifat "上手 (mahir/pandai)" menjadi mahir.',sentencePrompt:"毎日【まいにち】練習【れんしゅう】して、日本語【にほんご】が _____ なりました。",options:["上手【じょうず】に","上手【じょうず】く","上手【じょうず】な","上手【じょうず】で"],correctAnswer:"上手【じょうず】に",explanation:"Jouzu adalah kata sifat-na. Perubahannya berpasangan dengan に: 上手に なりました.",diagnosticFeedback:{"上手【じょうず】く":"Salah: Akhiran -ku hanya untuk kata sifat-i (seperti hayaku, takaku).","上手【じょうず】な":"Salah: Bentuk -na dipakai untuk menerangkan kata benda di depannya.","上手【じょうず】で":"Salah: Bentuk -de dipakai untuk menyambung kalimat."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Susun potongan kata berikut untuk menyatakan bahwa sekarang sudah bisa makan makanan pedas.",sentencePrompt:"Susunan kalimat perubahan kemampuan yang tepat:",options:["辛【から】い 物【もの】が 食【た】べられる ように なりました","食【た】べられる 辛【から】い 物【もの】が ように なりました","ように なりました 辛【から】い 物【もの】が 食【た】べられる","辛【から】い 食【た】べられる 物【もの】が ように なりました"],correctAnswer:"辛【から】い 物【もの】が 食【た】べられる ように なりました",explanation:"Objek (辛い物が) + Verba Potensial (食べられる) + ように なりました.",diagnosticFeedback:{"食【た】べられる 辛【から】い 物【もの】が ように なりました":"Salah: Verba potensial salah posisi di depan objek.","ように なりました 辛【から】い 物【もの】が 食【た】べられる":"Salah: Predikat utama diletakkan di awal kalimat.","辛【から】い 食【た】べられる 物【もの】が ように なりました":"Salah: Frasa kata sifat dan kata kerja tumpang tindih."},tokens:["辛【から】い","物【もの】が","食【た】べられる","ように","なりました"],correctOrder:["0","1","2","3","4"]},{id:"drill-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Bentuk Sifat-i): Manakah perubahan kata sifat "早い (cepat)" menjadi lebih cepat yang benar?',sentencePrompt:"Pilihlah bentuk yang tepat:",options:["朝【あさ】早【はや】く 起【お】きられる ように なりました。","朝【あさ】早【はや】いに 起【お】きられる ように なりました。","朝【あさ】早【はや】いな 起【お】きられる ように なりました。","朝【あさ】早【はや】いで 起【お】きられる ように なりました。"],correctAnswer:"朝【あさ】早【はや】く 起【お】きられる ように なりました。",explanation:"Kata sifat-i Hayai diubah menjadi adverbia bentuk -ku (早くなる / 早く起きる).",diagnosticFeedback:{"朝【あさ】早【はや】いに 起【お】きられる ように なりました。":"Jebakan: Kata sifat-i tidak boleh diberi partikel に.","朝【あさ】早【はや】いな 起【お】きられる ように なりました。":"Jebakan: Akhiran な hanya untuk kata sifat-na.","朝【あさ】早【はや】いで 起【お】きられる ように なりました。":"Jebakan: Salah bentuk sambung."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Rekan kerjamu bertanya "刺身【さしみ】は 食【た】べられますか". Jawaban jika dulu tidak bisa tetapi sekarang sudah bisa makan:',sentencePrompt:"Pilihlah tanggapan yang menyatakan proses perubahan kemampuan:",options:["前【まえ】は だめでしたが、今【いま】は 食【た】べられる ように なりました。","刺身【さしみ】を 食【た】べた ほう が いいですよ。","刺身【さしみ】を 食【た】べる つもりです。","刺身【さしみ】が 食【た】べたい すぎます。"],correctAnswer:"前【まえ】は だめでしたが、今【いま】は 食【た】べられる ように なりました。",explanation:"Menyatakan kontras dari dulu tidak bisa menjadi bisa sekarang menggunakan 〜ようになりました.",diagnosticFeedback:{"刺身【さしみ】を 食【た】べた ほう が いいですよ。":"Salah: Ini malah memberi saran kepada orang lain.","刺身【さしみ】を 食【た】べる つもりです。":"Salah: Hanya menyatakan niat, bukan kemampuan.","刺身【さしみ】が 食【た】べたい すぎます。":"Salah: Tata bahasa rusak."}}],can_do_challenge:{statement:"Bisa menceritakan peningkatan pemahaman bahasa Jepang selama magang.",situation:"Wawancara evaluasi progres bersama mentor di akhir bulan keenam.",promptTask:"Laporkan bahwa sekarang kamu sudah mulai bisa memahami percakapan berita radio!",modelAnswer:"ラジオの ニュースが 聞【き】き取【と】れる ように なりました。",modelAnswerId:"Sekarang saya sudah mulai bisa menangkap pendengaran berita radio.",culturalEtiquette:"Tersenyum ramah dan ucapkan terima kasih atas bimbingan mentor.",skillUnlocked:["Menguasai transformasi kemampuan 〜ようになる","Menguasai perubahan kata sifat 〜くなる / 〜になる"]},pocket_summary:{keyFormula:"[V-Potensial] ように なる (menjadi bisa) | [Adj-i] くなる / [Adj-na] になる",coreWords:["じょうず","わかる","なれる","せいかつ"],coreWarning:"Kata sifat いい berubah menjadi よく なりました, bukan いくなりました.",quickDialogue:"A: 日本語はどうですか。 → B: 前より話せるようになりました。"}}},i={"les-n4-u04-01":{pedagogical_framework:{what:{summary:"Menyatakan tingkat kemudahan suatu tindakan (〜やすい) dan kesulitan operasional (〜にくい), serta membagikan atau mengalokasikan kuantitas secara proporsional per satuan (〜ずつ).",canDo:"Bisa menilai manual operasional alat yang mudah dipahami dan membagikan komponen per orang atau per mesin.",targetPatterns:["[Masu-Stem] やすい (mudah dilakukan / gampang terjadi)","[Masu-Stem] にくい (sulit dilakukan / sukar terjadi)","[Kuantitas / Angka] ずつ (masing-masing ... / sedikit demi sedikit)"],coreVocabSample:["つかいやすい","わかりにくい","すこしずつ","マニュアル","ボタン","くばる","ぶひん"]},sensei_context:{sceneIntro:"Di stasiun perakitan bengkel kerja. Budi dan Kenji sedang mempelajari panduan pengoperasian mesin baru. Kenji meminta masukan mengenai kejelasan tombol dan pembagian suku cadang.",dailyMission:"Mampu menggunakan akhiran 〜やすい dan 〜にくい untuk menilai perangkat kerja, serta memakai partikel kuantitas 〜ずつ saat mendistribusikan material.",whyOrder:"Setelah bisa mengoperasikan alat di Unit 3, Unit 4 melatih pembelajar memberikan evaluasi kualitas operasional alat (user-friendliness) dan efisiensi logistik perakitan."},cultural_notes:{title:"Prinsip Kaizen (改善) & Desain Ergonomis Alat Kerja Jepang",etiquette:'Di pabrik Jepang, masukan dari operator lapangan mengenai alat yang "sulit dipakai" (tsukainikui) sangat dihargai sebagai bahan Kaizen (perbaikan berkelanjutan). Berikan masukan secara spesifik dan konstruktif.',taboos:'Akhiran 〜やすい dan 〜にくい mengubah kata kerja menjadi berkarakter KATA SIFAT-I! Bentuk negatifnya adalah "yasukunai" / "nikukunai", BUKAN "yasuku arimasen".'},pronunciation_tips:{title:"Peleburan Masu-Stem dengan Yasui/Nikui",moraNote:"Tsukaimasu -> buang [masu] -> Tsukai-yasui (5 mora). Wakarimasu -> Wakari-nikui (6 mora).",soundTip:'Ucapkan "zutsu" dengan dua mora jelas: zu-tsu, jangan disingkat menjadi desu.'},common_pitfalls:[{title:"Memasukkan Bentuk Kamus Sebelum Yasui / Nikui",caseScenario:'Menggabungkan bentuk kamus utuh: "tsukau yasui".',pitfallWarning:'"この パソコンは 使【つか】う やすいです。" (Salah)',rightSolution:'"この パソコンは 使【つか】い やすいです。" (Benar)',explanation:"Pola ini hanya menempel pada akar kata kerja bentuk Masu (Masu-Stem), yaitu 使います tanpa ます -> 使いやすい."},{title:'Salah Menempatkan Kata "Zutsu"',caseScenario:'Menaruh zutsu sebelum angka: "zutsu hitotsu".',pitfallWarning:'"ずつ 一【ひと】つ 取【と】ってください。"',rightSolution:'"一【ひと】つ ずつ 取【と】ってください。"',explanation:"Kata ずつ selalu diletakkan LANGSUNG SETELAH kata bilangan kuantitas: 1つずつ (satu per satu), 少しずつ (sedikit demi sedikit)."}],who_and_when:{situational_context:"Saat pengujian alat baru, penyusunan instruksi kerja, atau pembagian materi briefing kepada anggota tim.",social_relations:"Ragam sopan (Teineigo) yang sangat profesional saat berdiskusi dengan sesama rekan teknisi.",when_not_to_use:"Jangan gunakan 〜にくい untuk menolak perintah atasan secara frontal; gunakan alasan objektif."},scenario:{title:"Evaluasi Manual Alat Baru di Stasiun Perakitan",setting:"Meja kerja tim manufaktur lantai 1, pukul 14.00",narrative:"Budi dan Kenji membandingkan manual lama dengan manual digital baru di layar tablet."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"ブディ、新【あたら】しい 機械【きかい】の タブレットはどう？使【つか】いやすい？",furigana:"ブディ、新しい 機械の タブレットはどう？使いやすい？",romaji:"Budi, atarashii kikai no taburetto wa dou? Tsukaiyasui?",idText:"Budi, tablet mesin yang baru bagaimana? Mudah digunakan?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！画面【がめん】が 大【おお】きくて、とても 使【つか】いやすいです。",furigana:"はい！画面が 大きくて、とても 使いやすいです。",romaji:"Hai! Gamen ga ookikute, totemo tsukaiyasui desu.",idText:"Ya! Layarnya besar dan sangat mudah digunakan."},{id:"d3",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"前【まえ】の 紙【かみ】の マニュアルは 字【じ】が 小【ちい】さくて 読【よ】みにくかったもんね。",furigana:"前の 紙の マニュアルは 字が 小さくて 読みにくかったもんね。",romaji:"Mae no kami no manyuaru wa ji ga chiisakute yominikukatta mon ne.",idText:"Manual kertas yang dulu kan hurufnya kecil dan susah dibaca ya."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"そうですね。写真【しゃしん】も あるので、作業【さぎょう】の 手順【てじゅん】が 分【わ】かりやすいです。",furigana:"そうですね。写真も あるので、作業の 手順が 分かりやすいです。",romaji:"Sou desu ne. Shashin mo aru node, sagyou no tejun ga wakariyasui desu.",idText:"Benar sekali. Karena ada fotonya juga, urutan langkah kerjanya mudah dipahami."},{id:"d5",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"じゃあ、今日【きょう】の 組【く】み立【た】て 部品【ぶひん】を 各班【かくはん】に ２個【にこ】ずつ 配【くば】ってくれる？",furigana:"じゃあ、今日の 組み立て 部品を 各班に ２個ずつ 配ってくれる？",romaji:"Jaa, kyou no kumitate buhin o kakuhan ni niko zutsu kubatte kureru?",idText:"Kalau begitu, bisakah tolong bagikan komponen perakitan hari ini masing-masing 2 buah ke tiap regu?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】しました。落【お】とさないように、少【すこ】しずつ 運【はこ】びます。",furigana:"承知しました。落とさないように、少しずつ 運びます。",romaji:"Shouchi shimashita. Otosanai you ni, sukoshizutsu hakobimasu.",idText:"Saya pahami. Agar tidak jatuh, saya akan membawanya sedikit demi sedikit."}],vocab_breakdown:[{id:"vg-n4-00155",word:"数える",reading:"かぞえる",romaji:"kazoeru",meaning:"menghitung",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"箱の中にリンゴが何個あるか数えてください。",furigana:"箱の中にリンゴが何個あるか数えてください。",romaji:"",idText:"Tolong hitung ada berapa apel di dalam kotak."}},{id:"vg-n4-00947",word:"ああ",reading:"ああ",romaji:"aa",meaning:"seperti itu",pos:"adverb",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"ある人はこうだと言い、またある人はああだと言う。",furigana:"ある人はこうだと言い、またある人はああだと言う。",romaji:"",idText:"Satu orang berkata begini, yang lain berkata begitu."}},{id:"vg-n4-01222",word:"はっきり",reading:"はっきり",romaji:"hakkiri",meaning:"dengan jelas",pos:"adverb",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"私はまだはっきりとは知らない。",furigana:"私はまだはっきりとは知らない。",romaji:"",idText:"I don't know for certain yet."}},{id:"vg-n4-01255",word:"まず",reading:"まず",romaji:"mazu",meaning:"pertama-tama",pos:"adverb",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"バリウムをまず一口飲んでください。",furigana:"バリウムをまず一口飲んでください。",romaji:"",idText:"First, swallow one dose of barium."}},{id:"vg-n4-00832",word:"～やすい",reading:"～やすい",romaji:"-yasui",meaning:"mudah di-...; gampang ...; rentan ...",pos:"i-adj",nuance:"Sufiks kata sifat-i yang dilekatkan pada masu-stem verba. Memiliki dua fungsi: 1) mudah dilakukan secara fisik/mental (misal: 分かりやすい = mudah dipahami, 使いやすい = mudah dipakai); 2) memiliki kecenderungan/rentan terhadap hal negatif (misal: 壊れやすい = mudah rusak, 風邪をひきやすい = mudah kena flu). Lawan katanya adalah ～にくい (-nikui).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"この教科書はイラストが多くて、文法がとても分かりやすいです。",furigana:"この教科書はイラストが多くて、文法がとても分かりやすいです。",romaji:"",idText:"Buku pelajaran ini memuat banyak ilustrasi sehingga tata bahasanya sangat mudah dipahami."}},{id:"vg-n4-00885",word:"最も",reading:"もっとも",romaji:"mottomo",meaning:"paling, ter- (tingkat superlatif)",pos:"adverb",nuance:"Adverbia superlatif penunjuk derajat tertinggi. Bernuansa lebih formal dan resmi dalam bahasa tulisan atau pidato bila dibandingkan dengan kata 一番 (ichiban) yang lebih lazim dalam percakapan santai sehari-hari.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"富士山は日本で最も高い美しい山として世界的に有名です。",furigana:"富士山は日本で最も高い美しい山として世界的に有名です。",romaji:"",idText:"Gunung Fuji terkenal secara mendunia sebagai gunung paling tinggi dan indah di Jepang."}},{id:"vg-n4-00911",word:"程",reading:"ほど",romaji:"hodo",meaning:"kira-kira, sekitar; derajat, tingkat",pos:"adverb",nuance:"Dipakai untuk menyatakan perkiraan takaran jumlah atau batasan derajat. Berbeda dengan くらい (kurai) yang bernuansa sangat santai, 程 (hodo) sedikit lebih formal dan sering digunakan dalam pola perbandingan negatif (～ほど…ない) atau korelasi (～ば～ほど).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"駅から私の自宅まで歩いて十分程かかります。",furigana:"駅から私の自宅まで歩いて十分程かかります。",romaji:"",idText:"Dari stasiun ke rumah kediaman saya memakan waktu jalan kaki sekitar sepuluh menit."}},{id:"vg-n4-00057",word:"会議",reading:"かいぎ",romaji:"kaigi",meaning:"rapat, konferensi",pos:"noun",nuance:"会議 = rapat resmi. 会議がある = ada rapat. 会議室 = ruang rapat.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"午後から大切な会議があります。",furigana:"午後から大切な会議があります。",romaji:"",idText:"Ada rapat penting mulai sore."}},{id:"vg-n4-00058",word:"社会",reading:"しゃかい",romaji:"shakai",meaning:"masyarakat, sosial",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"大学を卒業したあと社会に出て働きます。",furigana:"大学を卒業したあと社会に出て働きます。",romaji:"",idText:"Setelah lulus kuliah, saya akan terjun ke masyarakat dan bekerja."}},{id:"vg-n4-00154",word:"数",reading:"かず",romaji:"kazu",meaning:"angka, jumlah",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"クラスの生徒の数を数えてください。",furigana:"クラスの生徒の数を数えてください。",romaji:"",idText:"Tolong hitung jumlah siswa di kelas."}}],explanations:[{id:"exp-1",grammarId:"gn4-00044",title:"Pola: Vやすい",formula:"V-ます語幹 + やすい",meaning:"mudah untuk ... / gampang ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vやすい",idText:"mudah untuk ... / gampang ..."}],examples:[{jp:"この辞書は使いやすいです。",romaji:"",idText:"Kamus ini mudah digunakan."},{jp:"彼女の説明は分かりやすかった。",romaji:"",idText:"Penjelasannya mudah dipahami."}]},{id:"exp-2",grammarId:"gn4-00045",title:"Pola: Vにくい",formula:"V-ます語幹 + にくい",meaning:"sulit untuk ... / susah ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vにくい",idText:"sulit untuk ... / susah ..."}],examples:[{jp:"この漢字は書きにくいです。",romaji:"",idText:"Kanji ini sulit ditulis."},{jp:"狭くて住みにくいアパートです。",romaji:"",idText:"Ini apartemen yang sempit dan susah untuk ditinggali."}]},{id:"exp-3",grammarId:"gn4-00002",title:"Pola: 〜ずつ",formula:"N (jumlah) + ずつ",meaning:"masing-masing ... / ... per ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ずつ",idText:"masing-masing ... / ... per ..."}],examples:[{jp:"このプリントを1枚ずつ配ってください。",romaji:"",idText:"Tolong bagikan cetakan ini masing-masing satu lembar."},{jp:"少しずつ日本語が上手になっています。",romaji:"",idText:"Bahasa Jepang saya pelan-pelan semakin bagus."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah lawan kata dari "使いやすい (mudah dipakai)".',sentencePrompt:'Lawan kata dari "使いやすい" adalah:',options:["使【つか】いにくい (sulit dipakai)","食【た】べやすい (mudah dimakan)","飲【の】みにくい (sulit diminum)","見【み】やすい (mudah dilihat)"],correctAnswer:"使【つか】いにくい (sulit dipakai)",explanation:"Pola -yasui berlawanan dengan -nikui pada akar kata kerja yang sama (tsukaiyasui vs tsukainikui).",diagnosticFeedback:{"食【た】べやすい (mudah dimakan)":"Salah: Beda kata kerja dasar (makan).","飲【の】みにくい (sulit diminum)":"Salah: Beda kata kerja dasar (minum).","見【み】やすい (mudah dilihat)":"Salah: Beda kata kerja dasar (melihat)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Penggabungan Masu-Stem): Pilihlah bentuk yang tepat untuk menyatakan obat yang mudah ditelan/diminum.",sentencePrompt:"この 薬【くすり】は 小【ちい】さくて _____ です。",options:["飲【の】みやすい","飲【の】むやすい","飲【の】んでやすい","飲【の】まないやすい"],correctAnswer:"飲【の】みやすい",explanation:"Kata kerja 飲みます buang ます -> 飲み + やすい = 飲みやすい.",diagnosticFeedback:{"飲【の】むやすい":"Salah: Bentuk kamus tidak boleh digabungkan langsung dengan やすい.","飲【の】んでやすい":"Salah: Bentuk te tidak boleh digabungkan dengan やすい.","飲【の】まないやすい":"Salah: Bentuk negatif tidak boleh disambung ke やすい."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Susun potongan kata berikut untuk menginstruksikan pembagian formulir 1 lembar per orang.",sentencePrompt:"Susunan instruksi alokasi yang tepat:",options:["皆【みな】さんに １枚【いちまい】ずつ 配【くば】ってください","１枚【いちまい】ずつ 配【くば】ってください 皆【みな】さんに","配【くば】ってください １枚【いちまい】ずつ 皆【みな】さんに","皆【みな】さんに 配【くば】ってください １枚【いちまい】ずつ"],correctAnswer:"皆【みな】さんに １枚【いちまい】ずつ 配【くば】ってください",explanation:"Penerima (皆さんに) + Kuantitas-Zutsu (1枚ずつ) + Verba Instruksi (配ってください).",diagnosticFeedback:{"１枚【いちまい】ずつ 配【くば】ってください 皆【みな】さんに":"Kurang lazim: Penerima bantuan diletakkan di akhir.","配【くば】ってください １枚【いちまい】ずつ 皆【みな】さんに":"Salah: Kata kerja ditaruh di awal.","皆【みな】さんに 配【くば】ってください １枚【いちまい】ずつ":"Salah: Kuantitas ditaruh setelah perintah kerja."},tokens:["皆【みな】さんに","１枚【いちまい】ずつ","配【くば】ってください"],correctOrder:["0","1","2"]},{id:"drill-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Karakter Sifat-i): Manakah bentuk lampau negatif yang benar dari "わかりやすい"?',sentencePrompt:'Pilihlah bentuk konjugasi yang tepat untuk "dahulu tidak mudah dipahami":',options:["分【わ】かりやすくなかったです。","分【わ】かりやすいではありませんでした。","分【わ】かりやすかったです。","分【わ】かりやすいじゃなかったです。"],correctAnswer:"分【わ】かりやすくなかったです。",explanation:"Karena -yasui berkonjugasi persis seperti kata sifat-i, maka bentuk lampau negatifnya adalah -yasukunakatta desu.",diagnosticFeedback:{"分【わ】かりやすいではありませんでした。":"Jebakan: Pola dewa arimasen deshita adalah konjugasi kata sifat-na/benda, bukan kata sifat-i.","分【わ】かりやすかったです。":'Salah: Ini adalah bentuk positif lampau ("dulu mudah dipahami").',"分【わ】かりやすいじゃなかったです。":"Jebakan: Pola ja nakatta adalah untuk sifat-na/benda."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Supervisor menanyakan pendapatmu tentang sepatu safety baru "新【あたら】しい 安全靴【あんぜんぐつ】の 履【は】き心地【ごこち】はどうですか". Respons terbaik:',sentencePrompt:"Pilihlah evaluasi yang tepat:",options:["軽【かる】くて、とても 歩【ある】きやすいです。","軽【かる】くて、とても 歩【ある】くやすいです。","歩【ある】く ことに しています。","歩【ある】いた ほう が いいですよ。"],correctAnswer:"軽【かる】くて、とても 歩【ある】きやすいです。",explanation:"Menilai bahwa sepatunya ringan dan sangat mudah/nyaman untuk berjalan (Aruki-yasui).",diagnosticFeedback:{"軽【かる】くて、とても 歩【ある】くやすいです。":"Salah bentuk: Aruku yasui salah, seharusnya arukiyasui.","歩【ある】く ことに しています。":'Salah konteks: "Saya membiasakan diri berjalan".',"歩【ある】いた ほう が いいですよ。":"Salah konteks: Malah menasihati atasan."}}],can_do_challenge:{statement:"Bisa menilai manual operasional alat yang mudah dipahami.",situation:"Memberikan umpan balik kepada perancang panduan kerja pabrik.",promptTask:"Katakan bahwa manual ini mudah dipahami karena fotonya jelas!",modelAnswer:"写真【しゃしん】が はっきりしていて、とても 分【わ】かりやすいです。",modelAnswerId:"Fotonya jelas dan sangat mudah dipahami.",culturalEtiquette:"Berikan apresiasi positif terlebih dahulu sebelum poin teknis.",skillUnlocked:["Menguasai sufiks evaluatif 〜やすい dan 〜にくい","Menguasai partikel distribusi proporsional 〜ずつ"]},pocket_summary:{keyFormula:"[Masu-Stem] やすい (mudah) / にくい (sulit) | [Jumlah] ずつ (per satuan)",coreWords:["つかいやすい","わかりにくい","すこしずつ","くばる"],coreWarning:"Akhiran yasui dan nikui berstatus kata sifat-i; negatifnya adalah yasukunai.",quickDialogue:"A: この道具はどう？ → B: 軽くてとても使いやすいです。"}},"les-n4-u04-02":{pedagogical_framework:{what:{summary:"Nominalisasi kata sifat menjadi besaran kuantitatif objektif dengan akhiran 〜さ (ukuran sifat), serta menyatakan interval kejadian berkala (〜おきに = berselang jeda vs 〜ごとに = setiap kali siklus).",canDo:"Bisa melaporkan berat beban paket logistik dan mengecek suhu mesin setiap interval 30 menit secara teratur.",targetPatterns:["[Kata Sifat-i buang i / Kata Sifat-na] さ (tingkat / bobot / derajat nominal)","[Satuan Angka / Waktu] おき に (berselang interval)","[Satuan Waktu / Kategori] ごと に (setiap / tiap-tiap siklus)"],coreVocabSample:["おもさ","たかさ","ながさ","あつさ","おきに","ごとに","はかる","てんけん"]},sensei_context:{sceneIntro:"Di gudang pengiriman kargo pabrik. Tanaka-senpai mengawasi Budi menimbang berat paket karton dan mengatur alarm pengecekan suhu mesin penyimpanan.",dailyMission:'Mampu mengubah kata sifat dimensi (omoi, takai, nagai) menjadi kata benda besaran (omosa, takasa, nagasa), serta menggunakan "goto ni" untuk interval SOP kerja.',whyOrder:'Dalam dunia industri modern di Jepang, penilaian subjektif ("ini berat") harus dikonversi menjadi data objektif ("beratnya 15 kg") dan dijalankan sesuai interval waktu presisi.'},cultural_notes:{title:"Standarisasi Data Kuantitatif (定量的管理 - Teiryou-teki Kanri)",etiquette:'Laporan kerja di Jepang mengutamakan angka numerik pasti. Daripada berkata "Kono hako wa totemo omoi desu" (Kotak ini sangat berat), pimpinan lebih menghargai "Omosa o hakattara 15kg deshita" (Setelah diukur beratnya 15 kg).',taboos:'Perhatikan perbedaan: "1-jikan oki ni" berarti berselang selang 1 jam penuh (setiap 2 jam sekali). Jika ingin mengatakan "setiap 1 jam sekali", gunakan "1-jikan goto ni"!'},pronunciation_tips:{title:"Penekanan Suku Kata pada Sufiks -Sa",moraNote:"Omoi -> O-mo-sa (3 mora). Takai -> Ta-ka-sa (3 mora). Nagai -> Na-ga-sa (3 mora).",soundTip:'Ucapkan "goto ni" dengan nada mengalir datar, jangan menekan kata "go" terlalu keras.'},common_pitfalls:[{title:"Tertukar Antara 〜おきに (Berselang Jeda Antara) vs 〜ごとに (Tiap-Tiap Siklus)",caseScenario:'Ingin mengatakan "tiap 30 menit sekali mesin diperiksa" tetapi menggunakan okini.',pitfallWarning:'"３０分【さんじゅっぷん】おき に 点検【てんけん】します。" (Bermakna ada jeda kosong 30 menit)',rightSolution:'"３０分【さんじゅっぷん】ごと に 点検【てんけん】します。" (Setiap siklus 30 menit)',explanation:"〜ごとに berarti setiap interval tanpa jeda terlewat. 〜おきに berarti diselingi jeda satu interval."},{title:"Menempelkan Akhiran -Sa pada Kata Sifat Tanpa Membuang [i]",caseScenario:'Menyusun kalimat: "omoi-sa o hakaru".',pitfallWarning:'"重【おも】いさ を 測【はか】ります。"',rightSolution:'"重【おも】さ を 測【はか】ります。"',explanation:"Huruf [i] terakhir pada kata sifat wajib dihilangkan sebelum diganti dengan 〜さ (Omoi -> Omosa)."}],who_and_when:{situational_context:"Pemeriksaan logistik kargo, pengukuran dimensi fisik produk, atau pengaturan alarm jadwal patroli pabrik.",social_relations:"Ragam sopan (Teineigo) yang penting saat mengisi formulir inspeksi mutu (QC).",when_not_to_use:"Jangan gunakan -sa untuk kata sifat yang tidak memiliki parameter besaran ukur fisik atau psikologis terukur."},scenario:{title:"Inspeksi Berat Paket & Patroli Rutin Mesin",setting:"Gudang logistik dan ruang kontrol mesin pendingin, pukul 15.00",narrative:"Tanaka-senpai membimbing Budi menimbang berat paket sebelum dimuat ke truk kargo."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"ブディさん、出荷【しゅっか】する 前【まえ】に ダンボールの 重【おも】さを 測【はか】ってください。",furigana:"ブディさん、出荷する 前に ダンボールの 重さを 測ってください。",romaji:"Budi-san, shukka suru mae ni danbo-ru no omosa o hakatte kudasai.",idText:"Budi-san, sebelum dikirim tolong timbang berat kardusnya ya."},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、測【はか】りました。１箱【ひとはこ】の 重【おも】さは ちょうど １２キロです。",furigana:"はい、測りました。１箱の 重さは ちょうど １２キロです。",romaji:"Hai, hakarimashita. Hitohako no omosa wa choudo juunikiro desu.",idText:"Baik, sudah saya timbang. Berat satu kotaknya pas 12 kilogram."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"規定【きてい】の 範囲内【はんいない】ですね。高【たか】さは どうですか。",furigana:"規定の 範囲内ですね。高さは どうですか。",romaji:"Kitei no han'inai desu ne. Takasa wa dou desu ka.",idText:"Masuk dalam batas regulasi ya. Ketinggiannya bagaimana?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"高【たか】さは ５０センチです。トラックの 荷台【にだい】に しっかり 収【おさ】まります。",furigana:"高さは ５０センチです。トラックの 荷台に しっかり 収まります。",romaji:"Takasa wa gojuusenti desu. Torakku no nidai ni shikkari osamarimasu.",idText:"Tingginya 50 sentimeter. Muat pas di bak truk."},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor Kerja",avatar:"🧑‍💼",jp:"よし。あと 冷凍庫【れいとうこ】の 温度【おんど】は １時間【いちじかん】ごとに チェックしてくださいね。",furigana:"よし。あと 冷凍庫の 温度は １時間ごとに チェックしてくださいね。",romaji:"Yoshi. Ato reitouko no ondo wa ichijikan goto ni chekku shite kudasai ne.",idText:"Bagus. Lalu suhu ruang pembeku tolong dicek setiap 1 jam sekali ya."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】しました！１時間【いちじかん】ごとに 記録表【きろくひょう】に 記入【きにゅう】します。",furigana:"承知しました！１時間ごとに 記録表に 記入します。",romaji:"Shouchi shimashita! Ichijikan goto ni kirokuhyou ni kinyuu shimasu.",idText:"Saya pahami! Setiap 1 jam akan saya catat di tabel laporan."}],vocab_breakdown:[{id:"vg-n4-00749",word:"建て",reading:"～だて",romaji:"~date",meaning:"bertingkat ~, bangunan tipe ~ (akhiran arsitektur)",pos:"noun",nuance:"Digunakan sebagai akhiran penjelas bangunan, terutama jumlah lantai seperti 二階建て (nikai-date / berlantai dua) atau jenis kepemilikan hunian tapak mandiri seperti 一戸建て (ikkodate / rumah tapak mandiri, berbeda dengan kondominium atau apartemen bersusun).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"駅のすぐ近くに新しく三階建てのアパートが建ちました。",furigana:"駅のすぐ近くに新しく三階建てのアパートが建ちました。",romaji:"",idText:"Apartemen bertingkat tiga yang baru telah dibangun persis di dekat stasiun."}},{id:"vg-n4-00790",word:"以下",reading:"いか",romaji:"ika",meaning:"ke bawah, kurang dari atau sama dengan, berikut ini",pos:"noun",nuance:"Secara acuan angka, kata ini menyertakan angka patokannya (contoh: 10以下 berarti nilai 10 dan angka di bawahnya). Berbeda dengan 未満 (miman) yang murni di bawah angka patokan tanpa mengikutsertakan angka tersebut. Juga dapat bermakna penjelasan di bawah ini (以下参照).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"小学生以下の小さな子供はバスや電車の運賃が無料になります。",furigana:"小学生以下の小さな子供はバスや電車の運賃が無料になります。",romaji:"",idText:"Anak-anak kecil usia sekolah dasar ke bawah ongkos bus dan keretanya menjadi gratis."}},{id:"vg-n4-00807",word:"はず",reading:"はず",romaji:"hazu",meaning:"seharusnya; mestinya; sewajarnya",pos:"noun",nuance:"Kata benda formal (keishiki meishi) yang berfungsi menyatakan dugaan atau keyakinan kuat pembicara berdasarkan logika, fakta, atau jadwal tertentu ('seharusnya begitu'). Bentuk negatifnya adalah ～はずがない (mustahil/tidak mungkin).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"田中さんは昨日薬を飲んで寝たので、今日は元気になっているはずです。",furigana:"田中さんは昨日薬を飲んで寝たので、今日は元気になっているはずです。",romaji:"",idText:"Karena Tanaka-san kemarin sudah minum obat dan beristirahat tidur, hari ini dia seharusnya sudah sehat."}},{id:"vg-n4-00842",word:"以外",reading:"いがい",romaji:"igai",meaning:"selain ...; di luar ...; kecuali ...",pos:"noun",nuance:"Dilekatkan setelah kata benda untuk menyatakan pengecualian hal tertentu ('selain hal tersebut'). Sangat lazim digunakan dalam pola negatif ～以外にない (tidak ada selain...) atau penegasan ～以外は全て (semuanya kecuali...). Hati-hati jangan tertukar bunyinya dengan 意外 (igai / tak terduga).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日曜日以外は毎日朝早くから夕方までアルバイトをしています。",furigana:"日曜日以外は毎日朝早くから夕方までアルバイトをしています。",romaji:"",idText:"Kecuali hari Minggu, saya bekerja paruh waktu setiap hari dari pagi buta hingga sore."}},{id:"vg-n4-00853",word:"以上",reading:"いじょう",romaji:"ijou",meaning:"lebih dari, ke atas, sekian (penutup)",pos:"noun",nuance:"Sebagai penunjuk jumlah batas, 以上 mencakup angka yang disebutkan (artinya angka tersebut atau lebih). Berbeda dengan 超える (koeru) yang berarti melampaui angka tersebut. Di akhir presentasi atau laporan, dipakai sebagai kata penutup yang berarti 'sekian'.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"この映画館は十八歳以上の大人しか入ることができません。",furigana:"この映画館は十八歳以上の大人しか入ることができません。",romaji:"",idText:"Bioskop ini hanya boleh dimasuki oleh orang dewasa berusia 18 tahun ke atas."}},{id:"vg-n4-00863",word:"指輪",reading:"ゆびわ",romaji:"yubiwa",meaning:"cincin",pos:"noun",nuance:"Perhiasan berbentuk lingkaran yang disematkan pada jari tangan (指 - jari + 輪 - lingkaran). Dipakai untuk mempercantik diri atau sebagai lambang ikatan perkawinan (結婚指輪 - kekkon yubiwa).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"誕生日に恋人からとても素敵な銀の指輪をもらいました。",furigana:"誕生日に恋人からとても素敵な銀の指輪をもらいました。",romaji:"",idText:"Pada hari ulang tahun, saya mendapat hadiah cincin perak yang sangat indah dari kekasih."}},{id:"vg-n4-00877",word:"会場",reading:"かいじょう",romaji:"kaijou",meaning:"tempat pertemuan, gedung acara, lokasi perhelatan",pos:"noun",nuance:"Lokasi ruangan atau gedung khusus tempat diselenggarakannya suatu perhelatan resmi, pertandingan, konser, atau ujian (seperti 試験会場). Berbeda dengan 場所 (basho) yang bermakna tempat secara umum.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日本語能力試験の会場は駅から歩いて十分ほどの大学です。",furigana:"日本語能力試験の会場は駅から歩いて十分ほどの大学です。",romaji:"",idText:"Tempat penyelenggaraan ujian kemampuan bahasa Jepang adalah universitas yang berjarak sepuluh menit jalan kaki dari stasiun."}},{id:"vg-n4-00889",word:"カーテン",reading:"カーテン",romaji:"kaaten",meaning:"tirai, gorden jendela",pos:"noun",nuance:"Kain penutup jendela untuk menghalau sinar matahari atau menjaga ruang privasi kamar. Biasa dipadukan dengan kata kerja カーテンを開ける (membuka tirai) atau カーテンを閉める (menutup tirai).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"部屋の中が少し暗かったので、窓のカーテンを大きく開けました。",furigana:"部屋の中が少し暗かったので、窓のカーテンを大きく開けました。",romaji:"",idText:"Karena di dalam kamar agak gelap, saya membuka tirai jendela lebar-lebar."}},{id:"vg-n4-00938",word:"～目",reading:"～め",romaji:"~me",meaning:"ke-~ (urutan bilangan ke-)",pos:"noun",nuance:"Sufiks penanda urutan ordinal yang dilekatkan setelah angka dan kata bantu bilangan (counter + 目). Digunakan secara khusus untuk mengubah kuantitas jumlah cacahan menjadi nomor urutan kejadian atau letak posisi, seperti 一つ目 (yang pertama), 二回目 (kali kedua), 三日目 (hari ketiga). Berbeda dengan angka bilangan biasa tanpa 目.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"二つ目の大きな交差点を右に曲がると郵便局が見えます。",furigana:"二つ目の大きな交差点を右に曲がると郵便局が見えます。",romaji:"",idText:"Jika Anda berbelok ke kanan di persimpangan besar yang kedua, kantor pos akan terlihat."}},{id:"vg-n4-00951",word:"あかちゃん",reading:"あかちゃん",romaji:"akachan",meaning:"bayi",pos:"noun",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"その赤ちゃんは歯が生えはじめている。",furigana:"その赤ちゃんは歯が生えはじめている。",romaji:"",idText:"Gigi bayi itu mulai tumbuh."}}],explanations:[{id:"exp-1",grammarId:"gn4-00070",title:"Pola: 形容詞 + さ",formula:"Adj-i語幹 + さ / Adj-na + さ",meaning:"tingkat ... / derajat ... (nominalisasi adjektif)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"形容詞 + さ",idText:"tingkat ... / derajat ... (nominalisasi adjektif)"}],examples:[{jp:"この山の高さは3000メートルです。",romaji:"",idText:"Ketinggian gunung ini adalah 3000 meter."},{jp:"彼の優しさに感動しました。",romaji:"",idText:"Saya terkesan dengan kebaikannya."}]},{id:"exp-2",grammarId:"gn4-00069",title:"Pola: 〜がる / 〜がっている",formula:"Adj-i語幹 + がる / Adj-i語幹 + がっている",meaning:"tampak merasa ... / menunjukkan tanda-tanda ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜がる / 〜がっている",idText:"tampak merasa ... / menunjukkan tanda-tanda ..."}],examples:[{jp:"子どもはプレゼントを欲しがっています。",romaji:"",idText:"Anak itu sepertinya menginginkan hadiah."},{jp:"彼はその話を怖がっていた。",romaji:"",idText:"Dia tampak ketakutan dengan cerita itu."}]},{id:"exp-3",grammarId:"gn4-00005",title:"Pola: 〜ごとに",formula:"N (waktu/interval) + ごとに / V-る + ごとに",meaning:"setiap ... / setiap kali ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ごとに",idText:"setiap ... / setiap kali ..."}],examples:[{jp:"2時間ごとに薬を飲んでください。",romaji:"",idText:"Tolong minum obat setiap 2 jam."},{jp:"駅に着くごとにメッセージを送ります。",romaji:"",idText:"Setiap kali tiba di stasiun, saya kirim pesan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah kata nominal dimensi yang berarti "panjangnya suatu benda".',sentencePrompt:'Kata yang berarti "panjangnya" yang dibentuk dari kata sifat "長い (ながい)" adalah:',options:["長【なが】さ","長【なが】いさ","長【なが】み","長【なが】くて"],correctAnswer:"長【なが】さ",explanation:"Nagai buang [i] + さ = 長さ (panjangnya / dimensi panjang).",diagnosticFeedback:{"長【なが】いさ":"Salah: Huruf [i] tidak boleh dipertahankan sebelum -sa.","長【なが】み":"Salah: Akhiran -mi menyatakan kedalaman rasa/nuansa abstrak, bukan dimensi panjang fisik.","長【なが】くて":"Salah: Ini adalah bentuk te penyambung kata sifat."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Pembedaan Interval): Lengkapi rumpang kalimat untuk SOP kerja "memeriksa suhu setiap 30 menit".',sentencePrompt:"３０分【さんじゅっぷん】_____ 温度【おんど】を 測定【そくてい】してください。",options:["ごと に","おき に","までに","あいだ"],correctAnswer:"ごと に",explanation:"Untuk jadwal rutin yang dieksekusi setiap siklus satuan waktu (tiap 30 menit sekali), gunakan ごとに.",diagnosticFeedback:{"おき に":"Kurang tepat: おきに berarti diselingi jeda 30 menit kosong di antaranya.",までに:"Salah: までに menandai batas tenggat waktu akhir (deadline).",あいだ:"Salah: あいだ menandai durasi rentang waktu keberlangsungan."}},{id:"drill-3",type:"reorder",instruction:"Langkah 3 (Susun Kalimat): Susun potongan kata berikut untuk menyatakan pengukuran berat kardus dengan timbangan.",sentencePrompt:"Susunan kalimat pengukuran yang tepat:",options:["はかりで 荷物【にもつ】の 重【おも】さを 測【はか】ります","重【おも】さを はかりで 荷物【にもつ】の 測【はか】ります","荷物【にもつ】の 測【はか】ります はかりで 重【おも】さを","測【はか】ります はかりで 荷物【にもつ】の 重【おも】さを"],correctAnswer:"はかりで 荷物【にもつ】の 重【おも】さを 測【はか】ります",explanation:"Alat (はかりで) + Objek Kepemilikan (荷物の重さを) + Verba Mengukur (測ります).",diagnosticFeedback:{"重【おも】さを はかりで 荷物【にもつ】の 測【はか】ります":"Salah: Frasa 荷物の terpisah dari kata yang diterangkan (重さ).","荷物【にもつ】の 測【はか】ります はかりで 重【おも】さを":"Salah: Kata kerja ditaruh di tengah sebelum objek.","測【はか】ります はかりで 荷物【にもつ】の 重【おも】さを":"Salah: Predikat utama diletakkan di awal kalimat."},tokens:["はかりで","荷物【にもつ】の","重【おも】さを","測【はか】ります"],correctOrder:["0","1","2","3"]},{id:"drill-4",type:"trap_detect",instruction:'Langkah 4 (Deteksi Sufiks Nominalisasi): Manakah kata benda besaran yang terbentuk dari kata sifat "高い (tinggi/mahal)"?',sentencePrompt:'Pilihlah bentuk nominal yang tepat untuk "tingginya":',options:["この ビルの 高【たか】さは １００メートルです。","この ビルの 高【たか】いさは １００メートルです。","この ビルの 高【たか】みは １００メートルです。","この ビルの 高【たか】くては １００メートルです。"],correctAnswer:"この ビルの 高【たか】さは １００メートルです。",explanation:"Takai buang [i] + さ -> 高さを表す名詞: 高さ (tingginya).",diagnosticFeedback:{"この ビルの 高【たか】いさは １００メートルです。":"Jebakan: Huruf [i] salah dipertahankan.","この ビルの 高【たか】みは １００メートルです。":"Jebakan: Takami bermakna tempat tinggi secara puitis/abstrak, bukan ketinggian numerik.","この ビルの 高【たか】くては １００メートルです。":"Salah: Bentuk te-wa tidak berfungsi sebagai kata benda subjek."}},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional): Rekan kerjamu bertanya "この バスは どれくらいで 来【き】ますか". Jawaban bahwa bus datang setiap 10 menit sekali:',sentencePrompt:"Pilihlah informasi jadwal yang tepat:",options:["１０分【じゅっぷん】ごと に 来【き】ますよ。","１０分【じゅっぷん】までに 来【き】ますよ。","１０分【じゅっぷん】やすい ですよ。","１０分【じゅっぷん】に しますよ。"],correctAnswer:"１０分【じゅっぷん】ごと に 来【き】ますよ。",explanation:"Frekuensi siklus interval transportasi diungkapkan dengan 10分ごとに (setiap 10 menit).",diagnosticFeedback:{"１０分【じゅっぷん】までに 来【き】ますよ。":"Salah: までに berarti paling lambat sebelum 10 menit.","１０分【じゅっぷん】やすい ですよ。":"Salah: Tata bahasa rusak.","１０分【じゅっぷん】に しますよ。":"Salah: Menyatakan keputusan waktu janji."}}],can_do_challenge:{statement:"Bisa melaporkan berat beban paket dan mengecek mesin berkala.",situation:"Melaporkan hasil penimbangan kargo dan komitmen patroli suhu ke supervisor.",promptTask:"Laporkan bahwa berat kardus 10 kg dan kamu akan mengeceknya tiap 1 jam!",modelAnswer:"ダンボールの 重【おも】さは １０キロです。１時間【いちじかん】ごと に 点検【てんけん】します。",modelAnswerId:"Berat kardusnya 10 kg. Saya akan memeriksa setiap 1 jam sekali.",culturalEtiquette:"Sebutkan angka satuan ukur (kg, jam) secara tegas dan jelas.",skillUnlocked:["Menguasai nominalisasi ukuran besaran dengan akhiran 〜さ","Menguasai ekspresi interval berkala 〜ごとに"]},pocket_summary:{keyFormula:"[Kata Sifat buang i] さ (besaran sifat) | [Waktu/Satuan] ごと に (setiap siklus)",coreWords:["おもさ","たかさ","ながさ","ごとに","はかる"],coreWarning:"Omosa (berat), Takasa (tinggi), Nagasa (panjang) — selalu buang akhiran i.",quickDialogue:"A: 重さはどれくらい？ → B: ちょうど10キロです。"}}},t={"les-n4-u05-01":{pedagogical_framework:{what:{summary:"Membedakan batas waktu mutlak (~made ni) vs rentang durasi terus-menerus (~made), kejadian dalam jeda waktu (~aida ni), dan partikel frekuensi (~ni).",canDo:"Bisa menyepakati deadline pengumpulan laporan kerja shift dan jadwal pengecekan mesin.",targetPatterns:["[Waktu / Verba Kamus] までに (paling lambat sebelum)","[Waktu / Verba Kamus] まで (sampai / hingga durasi berakhir)","[Kata Benda] の 間に / [V-te iru] 間に (selagi / sementara)","[Periode] に [Frekuensi] 回 (frekuensi per periode)"],coreVocabSample:["きげん","しめきり","ほうこくしょ","ていしゅつ","てんけん","まにあう"]},sensei_context:{sceneIntro:"Di ruang operasional pabrik. Tanaka-senpai menjelaskan jadwal pengumpulan laporan harian (nippou) dan frekuensi pengecekan suhu mesin kepada Budi.",dailyMission:"Gunakan 〜までに untuk menyatakan tenggat waktu tegas dan 〜間に untuk aksi yang diselesaikan di sela waktu kerja.",whyOrder:"Setelah menyusun rencana hidup di Unit 1-4, di tempat kerja Jepang disiplin deadline (kigen) adalah aturan nomor satu yang tidak boleh ditawar."},cultural_notes:{title:"Ketaatan Terhadap Tenggat Waktu (納期・期限の厳守 - Nouki Genshu)",etiquette:"Di dunia industri Jepang, 〜までに berarti pekerjaan sudah harus rampung di meja atasan sebelum jam yang ditentukan, bukan baru mulai dikirim pada menit terakhir.",taboos:"Jangan pernah tertukar antara まで (durasi kontinu sampai jam X) dan までに (batas akhir aksi selesai sebelum jam X). Kesalahan ini fatal dalam penjadwalan."},pronunciation_tips:{title:'Ketukan Partikel Sambung "Made ni" vs "Aida ni"',moraNote:'Kata "made ni" memiliki 3 mora (ma-de-ni) dengan aksen datar merata.',soundTip:'Pada frasa "aida ni", sambungkan vokal a-i secara halus tanpa jeda tersendat.'},common_pitfalls:[{title:"Tertukar Antara 〜まで (Durasi Berkelanjutan) vs 〜までに (Batas Akhir Selesai)",caseScenario:'Ingin mengatakan "kumpulkan laporan sebelum jam 5", tetapi malah memakai まで.',pitfallWarning:'"５時【ごじ】まで レポートを 出【だ】してください。"',rightSolution:'"５時【ごじ】までに レポートを 出【だ】してください。"',explanation:"〜まで berarti aktivitas dilakukan terus-menerus hingga jam 5 (misal: belajar sampai jam 5). Untuk aksi tunggal yang harus selesai sebelum jam 5, wajib memakai 〜までに."},{title:"Tertukar Antara 間に (Aksi Selesai di Tengah Jeda) vs 間 (Sepanjang Seluruh Jeda)",caseScenario:'Mengatakan "Tolong jaga kantor selagi saya rapat".',pitfallWarning:'"会議【かいぎ】の 間に 留守番【るすばん】を してください。"',rightSolution:'"会議【かいぎ】の 間【あいだ】、留守番【るすばん】を してください。"',explanation:"Jika aksinya berlangsung sepanjang durasi jeda secara terus-menerus, gunakan 間 (tanpa に). Jika aksinya terjadi sekali di tengah rentang jeda, gunakan 間に."}],who_and_when:{situational_context:"Instruksi shift kerja, perjanjian serah terima pesanan, janji temu dokter, atau pengumpulan tugas kursus.",social_relations:"Digunakan oleh atasan saat memberikan instruksi, atau oleh staf saat memastikan komitmen batas waktu.",when_not_to_use:"Jangan memakai 〜までに jika maksud kalimatnya adalah melakukan kegiatan santai sepanjang sore tanpa batas target."},scenario:{title:"Kesepakatan Batas Waktu Laporan Harian",setting:"Ruang kendali pabrik, pukul 14.00",narrative:"Tanaka mengingatkan Budi bahwa laporan shift harus selesai sebelum pukul 17.00 dan meminta mesin dicek dua kali per shift."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、今日【きょう】の 日報【にっぽう】は 何時【なんじ】までに 出【だ】せますか。",furigana:"ブディさん、今日の 日報は 何時までに 出せますか。",romaji:"Budi-san, kyou no nippou wa nanji made ni dasemasu ka.",idText:"Budi-san, laporan harian hari ini paling lambat jam berapa bisa kamu serahkan?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"５時【ごじ】までに 作成【さくせい】して 提出【ていしゅつ】します。",furigana:"５時までに 作成して 提出します。",romaji:"Goji made ni sakusei shite teishutsu shimasu.",idText:"Paling lambat jam 5 sore saya akan menyusun dan menyerahkannya."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"頼【たの】みますね。それから、先輩【せんぱい】が 休憩【きゅうけい】している 間【あいだ】に、メーターを 確認【かくにん】してください。",furigana:"頼みますね。それから、先輩が 休憩している 間に、メーターを 確認してください。",romaji:"Tanomimasu ne. Sorekara, senpai ga kyuukei shite iru aida ni, me-ta- o kakunin shite kudasai.",idText:"Tolong ya. Lalu, selagi senior sedang istirahat, tolong periksa meteran indikator."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】しました。点検【てんけん】は １日【いちにち】に 何回【なんかい】 行【おこな】いますか。",furigana:"承知しました。点検は １日に 何回 行いますか。",romaji:"Shouchi shimashita. Tenken wa ichinichi ni nankai okonaimasu ka.",idText:"Saya pahami. Pemeriksaan dilakukan berapa kali dalam sehari?"},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"１シフトに ２回【にかい】 チェックすれば 十分【じゅうぶん】ですよ。",furigana:"１シフトに ２回 チェックすれば 十分ですよ。",romaji:"Ichi-shifuto ni nikai chekku sureba juubun desu yo.",idText:"Cukup kamu cek 2 kali per satu shift kerja kok."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"分【わ】かりました！ 時間【じかん】に 間【ま】に 合【あ】うように しっかり 進【すす】めます。",furigana:"分かりました！ 時間に 間に 合うように しっかり 進めます。",romaji:"Wakarimashita! Jikan ni ma ni au you ni shikkari susumemasu.",idText:"Baik saya mengerti! Saya akan jalankan dengan baik agar tepat waktu."}],vocab_breakdown:[{id:"vg-n4-00105",word:"始める",reading:"はじめる",romaji:"hajimeru",meaning:"memulai",pos:"verb-ru",nuance:"始める (はじめる) = memulai (transitif, ada objek). Lawan: 終える. Intransitif: 始まる.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"さあ、仕事を始めましょう。",furigana:"さあ、仕事を始めましょう。",romaji:"",idText:"Ayo, mari kita mulai bekerja."}},{id:"vg-n4-00107",word:"終える",reading:"おえる",romaji:"oeru",meaning:"menyelesaikan",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"今日の仕事をすべて終えてから帰宅しました。",furigana:"今日の仕事をすべて終えてから帰宅しました。",romaji:"",idText:"Saya pulang ke rumah setelah menyelesaikan seluruh pekerjaan hari ini."}},{id:"vg-n4-00109",word:"続く",reading:"つづく",romaji:"tsuduku",meaning:"berlanjut, terus berlangsung",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"今週はずっと雨の日が続いています。",furigana:"今週はずっと雨の日が続いています。",romaji:"",idText:"Minggu ini cuaca hujan terus berlanjut."}},{id:"vg-n4-00110",word:"続ける",reading:"つづける",romaji:"tsudukeru",meaning:"melanjutkan",pos:"verb-ru",nuance:"続ける = melanjutkan/meneruskan. Lawan: やめる. 続けて頑張る = terus berusaha.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"諦めないで練習を続けてください。",furigana:"諦めないで練習を続けてください。",romaji:"",idText:"Jangan menyerah, teruskan latihan."}},{id:"vg-n4-00166",word:"返す",reading:"かえす",romaji:"kaesu",meaning:"mengembalikan",pos:"verb-u",nuance:"返す = mengembalikan (barang/uang). 借りたものを返す。Jangan keliru: 返事する = membalas.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"借りた本を図書館に返しました。",furigana:"借りた本を図書館に返しました。",romaji:"",idText:"Saya mengembalikan buku pinjaman ke perpustakaan."}},{id:"vg-n4-00176",word:"予定",reading:"よてい",romaji:"yotei",meaning:"rencana, jadwal",pos:"verb-suru",nuance:"予定 = rencana/jadwal yang sudah ditetapkan. 予定がある = ada rencana. 予定通り = sesuai jadwal.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"来週、大阪に行く予定です。",furigana:"来週、大阪に行く予定です。",romaji:"",idText:"Minggu depan saya berencana pergi ke Osaka."}},{id:"vg-n4-00224",word:"やる",reading:"やる",romaji:"yaru",meaning:"memberi (ke yang lebih muda/hewan/tanaman)",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"毎朝庭の花に水をやるのが私の日課です。",furigana:"毎朝庭の花に水をやるのが私の日課です。",romaji:"",idText:"Menyiram air ke bunga di halaman adalah rutinitas saya setiap pagi."}},{id:"vg-n4-00430",word:"訪ねる",reading:"たずねる",romaji:"tazuneru",meaning:"mengunjungi (seseorang)",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"週末に久しぶりに田舎の祖父母の家を訪ねました。",furigana:"週末に久しぶりに田舎の祖父母の家を訪ねました。",romaji:"",idText:"Saya menjenguk tempat tinggal kakek-nenek di pedesaan saat akhir pekan."}},{id:"vg-n4-00442",word:"通る",reading:"とおる",romaji:"tooru",meaning:"melewati",pos:"verb-u",nuance:"通る = melewati (tempat) / lulus (ujian). 道を通る = melewati jalan.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"この道を通って駅まで行けます。",furigana:"この道を通って駅まで行けます。",romaji:"",idText:"Lewat jalan ini bisa sampai ke stasiun."}},{id:"vg-n4-00731",word:"過ぎる",reading:"すぎる",romaji:"sugiru",meaning:"berlalu, lewat; melampaui, terlalu (berlebihan)",pos:"verb-ru",nuance:"Kata kerja ichidan (一段動詞). Memiliki dua penggunaan mendasar: (1) sebagai kata kerja independen yang berarti waktu/tempat berlalu atau melampaui batas (contoh: 約束の時間を過ぎる / melewati waktu janji), dan (2) sebagai kata kerja bantu setelah akar kata kerja masu / kata sifat untuk menyatakan kadar berlebihan (contoh: 食べすぎる / makan berlebihan, 高すぎる / terlalu mahal).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"約束の時間を三十分も過ぎてから友達が来ました。",furigana:"約束の時間を三十分も過ぎてから友達が来ました。",romaji:"",idText:"Teman saya datang setelah lewat tiga puluh menit dari waktu janjian."}}],explanations:[{id:"exp-1",grammarId:"gn4-00011",title:"Pola: 〜までに",formula:"N (waktu) / Vる + までに",meaning:"paling lambat ... / sebelum ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜までに",idText:"paling lambat ... / sebelum ..."}],examples:[{jp:"レポートは15日までに出してください。",romaji:"",idText:"Tolong kumpulkan laporan paling lambat tanggal 15."},{jp:"9時までに来てください。",romaji:"",idText:"Tolong datang sebelum jam 9."}]},{id:"exp-2",grammarId:"gn4-00092",title:"Pola: V-るまで、〜",formula:"V(dictionary form) + まで + clause",meaning:"sampai V / hingga V",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"V-るまで、〜",idText:"sampai V / hingga V"}],examples:[{jp:"電車が来るまでここで待ってください。",romaji:"",idText:"Tolong tunggu di sini sampai kereta datang."},{jp:"試験が終わるまで帰れません。",romaji:"",idText:"Saya tidak bisa pulang sampai ujian selesai."},{jp:"準備ができるまで少し待ってください。",romaji:"",idText:"Tolong tunggu sebentar sampai persiapan selesai."}]},{id:"exp-3",grammarId:"gn4-00012",title:"Pola: 〜間に (あいだに)",formula:"N + の + 間に / Vている + 間に",meaning:"selagi ... / sementara ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜間に (あいだに)",idText:"selagi ... / sementara ..."}],examples:[{jp:"夏休みの間に旅行する予定です。",romaji:"",idText:"Saya berencana berwisata selama liburan musim panas."},{jp:"買い物に行っている間に、友だちが来ました。",romaji:"",idText:"Selagi saya pergi belanja, teman datang."}]},{id:"exp-4",grammarId:"gn4-00001",title:"Pola: 〜に (frekuensi)",formula:"N (periode waktu) + に + N (frekuensi)",meaning:"partikel frekuensi (per ...)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜に (frekuensi)",idText:"partikel frekuensi (per ...)"}],examples:[{jp:"1週間に2回、ジムに通っています。",romaji:"",idText:"Saya pergi ke gym 2 kali seminggu."},{jp:"1か月に一度、家族に電話します。",romaji:"",idText:"Satu kali sebulan saya menelepon keluarga."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah istilah yang tepat untuk batas waktu mutlak pengumpulan laporan.",sentencePrompt:"Istilah batas waktu atau tenggat waktu dalam dunia kerja adalah:",options:["締切【しめきり】 (Batas tenggat waktu)","休憩【きゅうけい】 (Istirahat sejenak)","点検【てんけん】 (Pemeriksaan mesin)","日報【にっぽう】 (Laporan harian)"],correctAnswer:"締切【しめきり】 (Batas tenggat waktu)",explanation:"締切 (shimekiri) atau 期限 (kigen) adalah istilah untuk batas akhir penyerahan berkas atau tugas.",diagnosticFeedback:{"休憩【きゅうけい】 (Istirahat sejenak)":"Salah: 休憩 (kyuukei) berarti waktu jeda atau rehat.","点検【てんけん】 (Pemeriksaan mesin)":"Salah: 点検 (tenken) berarti inspeksi atau pemeriksaan teknis.","日報【にっぽう】 (Laporan harian)":"Salah: 日報 (nippou) adalah objek laporannya, bukan batas waktunya."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Seleksi Pola Deadline): Lengkapi kalimat tenggat pengumpulan tugas.",sentencePrompt:"明日【あした】の 朝【あさ】９時【くじ】（　　）、この 書類【しょるい】を 提出【ていしゅつ】してください。",options:["までに","まで","あいだ","から"],correctAnswer:"までに",explanation:"Pengumpulan dokumen adalah aksi tunggal yang memiliki batas waktu mutlak, sehingga harus menggunakan までに.",diagnosticFeedback:{まで:"Salah: まで menyatakan durasi terus-menerus (misal: bekerja sampai jam 9), bukan batas akhir aksi.",あいだ:"Salah: あいだ menyatakan rentang waktu (selama/selagi), bukan batas waktu jam tertentu.",から:"Salah: から menyatakan titik awal permulaan (sejak jam 9)."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Partikel Frekuensi & Rentang): Pilihlah partikel yang tepat untuk menyatakan aksi di sela waktu.",sentencePrompt:"田中【たなか】さんが 戻【もど】って くる（　　）に、机【つくえ】の 上【うえ】を 片付【かたづ】けます。",options:["間【あいだ】","時【とき】","前【まえ】","後【あと】"],correctAnswer:"間【あいだ】",explanation:'Frasa 〜ている間に berarti "selagi / di tengah-tengah rentang waktu seseorang melakukan sesuatu".',diagnosticFeedback:{"時【とき】":"Salah: 時に kurang lazim berpasangan dengan bentuk ている untuk makna di sela waktu.","前【まえ】":"Salah: 前 berpasangan dengan verba bentuk kamus (戻る前に), bukan bentuk te-kuru.","後【あと】":"Salah: 後 berpasangan dengan bentuk lampau (戻った後に)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai potongan kata menjadi kalimat frekuensi minum obat yang benar.",sentencePrompt:'Susunlah kata-kata berikut agar bermakna: "Minum obat ini 3 kali dalam 1 hari".',options:["この 薬【くすり】を １日【いちにち】に ３回【さんかい】 飲【の】んでください。","この 薬【くすり】を ３回【さんかい】 １日【いちにち】に 飲【の】んでください。","１日【いちにち】に 飲【の】んでください この 薬【くすり】を ３回【さんかい】。","３回【さんかい】 飲【の】んでください １日【いちにち】に この 薬【くすり】を。"],correctAnswer:"この 薬【くすり】を １日【いちにち】に ３回【さんかい】 飲【の】んでください。",explanation:"Pola frekuensi waktu adalah [Periode] に [Frekuensi] 回 + [Verba]: 1日 に 3回 飲みます.",diagnosticFeedback:{"この 薬【くすり】を ３回【さんかい】 １日【いちにち】に 飲【の】んでください。":"Kurang tepat: Satuan periode waktu (1日 に) didahulukan sebelum frekuensi (3回).","１日【いちにち】に 飲【の】んでください この 薬【くすり】を ３回【さんかい】。":"Salah susun: Verba penutup kalimat diletakkan di akhir.","３回【さんかい】 飲【の】んでください １日【いちにち】に この 薬【くすり】を。":"Salah susun: Predikat wajib berada di ujung kalimat."},tokens:["この 薬【くすり】を","１日【いちにち】に","飲【の】んでください","３回【さんかい】"],correctOrder:["0","1","3","2"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Analisis Nuansa): Analisislah perbedaan implikasi kalimat kerja.",sentencePrompt:"Manakah kalimat yang menyatakan bahwa tugas tersebut WAJIB sudah selesai sebelum jam 17.00?",options:["１７時【じゅうななじ】までに 仕事【しごと】を 終【お】わらせます。","１７時【じゅうななじ】まで 仕事【しごと】を 続【つづ】けます。","１７時【じゅうななじ】から 仕事【しごと】を 始【はじ】めます。","１７時【じゅうななじ】の 間に 仕事【しごと】を 休【やす】みます。"],correctAnswer:"１７時【じゅうななじ】までに 仕事【しごと】を 終【お】わらせます。",explanation:"Partikel までに menegaskan target penyelesaian paling lambat sebelum jam yang ditentukan.",diagnosticFeedback:{"１７時【じゅうななじ】まで 仕事【しごと】を 続【つづ】けます。":"Salah: Ini berarti terus bekerja tanpa henti hingga jam 17.00.","１７時【じゅうななじ】から 仕事【しごと】を 始【はじ】めます。":"Salah: Ini menyatakan permulaan jam kerja pukul 17.00.","１７時【じゅうななじ】の 間に 仕事【しごと】を 休【やす】みます。":"Salah struktur tata bahasa partikel."}}],can_do_challenge:{statement:"Bisa menyepakati deadline pengumpulan laporan kerja shift.",situation:"Ditanya oleh atasan kapan kamu bisa menyerahkan laporan inspeksi barang.",promptTask:"Katakan bahwa kamu akan menyerahkannya paling lambat pukul 4 sore!",modelAnswer:"夕方【ゆうがた】４時【よじ】までに 提出【ていしゅつ】します。",modelAnswerId:"Saya akan menyerahkannya paling lambat pukul 4 sore.",culturalEtiquette:"Ucapkan dengan kontak mata fokus dan anggukan tegas tanda komitmen.",skillUnlocked:["Menguasai ketepatan pemakaian 〜までに untuk deadline","Mampu berkoordinasi jadwal kerja tanpa miskomunikasi"]},pocket_summary:{keyFormula:"[Waktu] までに (paling lambat sebelum) vs [Waktu] まで (sampai terus-menerus)",coreWords:["きげん","しめきり","ていしゅつ","てんけん"],coreWarning:"Gunakan までに untuk deadline penyerahan tugas; jangan gunakan まで yang bermakna durasi berulang.",quickDialogue:"A: 何時までに？ → B: ５時までに提出します。"}},"les-n4-u05-02":{pedagogical_framework:{what:{summary:"Menyatakan fase presisi momen aksi: tepat akan mulai (V-ru tokoro), sedang berlangsung saat ini (V-te iru tokoro), dan baru saja selesai (V-ta tokoro).",canDo:"Bisa mengabarkan progres tugas seketika melalui radio kerja, telepon, atau laporan lisan.",targetPatterns:["[Verba Kamus] ところです (tepat akan mulai)","[Verba-te] いる ところです (sedang tepat berlangsung)","[Verba-ta] ところです (baru saja selesai rampung)"],coreVocabSample:["これから","いま","たったいま","かくにん","れんらく","おわる"]},sensei_context:{sceneIntro:"Di area gudang logistik. Sakura menghubungi Budi melalui interkom untuk menanyakan apakah pengemasan kardus sudah beres.",dailyMission:'Gunakan tiga variasi bentuk "tokoro da" untuk mengabarkan status riil pekerjaan detik ini juga.',whyOrder:'Dalam budaya kerja Hou-Ren-So (Lapor-Kabar-Konsultasi), atasan sering menanyakan status terkini: "Ima dou natte iru?". Pola tokoro da memberikan ketepatan waktu absolut.'},cultural_notes:{title:"Komunikasi Progres Kerja Spontan (進捗報告 - Shinchoku Houkoku)",etiquette:'Ketika atasan menanyakan perkembangan tugas, menjawab "Sedang saya kerjakan tepat sekarang" (ima yatte iru tokoro desu) jauh lebih informatif daripada sekadar menjawab "hai".',taboos:"Hindari mengatakan V-ta tokoro desu jika aksi tersebut sudah selesai berjam-jam yang lalu. Pola ini hanya untuk hal yang baru tuntas beberapa detik atau menit yang lalu."},pronunciation_tips:{title:'Penekanan Kata Keterangan Waktu Bersama "Tokoro"',moraNote:"Pasangan alami: これから (korekara) + V-ru; 今 (ima) + V-te iru; たった今 (tatta ima) + V-ta.",soundTip:'Ucapkan "tokoro desu" dengan intonasi turun merendah di akhir kalimat.'},common_pitfalls:[{title:"Salah Memasangkan Bentuk Verba dengan Kata Keterangan Waktu",caseScenario:'Menggunakan "tatta ima" (baru saja) dengan bentuk kamus V-ru.',pitfallWarning:'"たった今【いま】 食【た】べる ところです。"',rightSolution:'"たった今【いま】 食【た】べた ところです。"',explanation:"たった今 (tatta ima = baru saja beberapa detik lalu) wajib dipasangkan dengan bentuk lampau V-ta tokoro desu."},{title:"Tertukar Antara 〜たところ (Baru Selesai Detik Ini) vs 〜たばかり (Baru Terjadi dalam Skala Relatif)",caseScenario:"Mengatakan baru masuk perusahaan bulan lalu menggunakan tokoro desu.",pitfallWarning:'"先月【せんげつ】 この 会社【かいしゃ】に 入【はい】った ところです。"',rightSolution:'"先月【せんげつ】 この 会社【かいしゃ】に 入【はい】った ばかりです。"',explanation:"V-ta tokoro terikat pada waktu fisik yang sangat baru (hitungan menit/detik). Jika sudah lewat berminggu-minggu tetapi secara psikologis terasa baru, gunakan 〜たばかり."}],who_and_when:{situational_context:"Saat menjawab panggilan telepon kantor, radio panggil HT di gudang, atau pertanyaan atasan yang lewat di depan meja kerja.",social_relations:"Sangat lazim dipakai staf kepada atasan (bentuk Teineigo) maupun antarsesama rekan kerja.",when_not_to_use:"Jangan gunakan pada keadaan pasif atau sifat alami yang tidak memiliki dinamika proses aksi."},scenario:{title:"Laporan Status Pengepakan Barang",setting:"Gudang distribusi barang, pukul 11.15",narrative:"Sakura menanyakan apakah Budi sudah mengirim kardus suku cadang. Budi menjelaskan bahwa ia baru saja selesai mengecek dan tepat akan memuatnya ke truk."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Mentor Logistik",avatar:"👩‍🏫",jp:"ブディさん、荷物【にもつ】の 梱包【こんぽう】は もう 終【お】わりましたか。",furigana:"ブディさん、荷物の 梱包は もう 終わりましたか。",romaji:"Budi-san, nimotsu no konpou wa mou owarimashita ka.",idText:"Budi-san, apakah pengepakan barangnya sudah selesai?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、たった今【いま】 確認【かくにん】が 終【お】わった ところです。",furigana:"はい、たった今 確認が 終わった ところです。",romaji:"Hai, tatta ima kakunin ga owatta tokoro desu.",idText:"Iya, baru saja saya selesai melakukan pengecekan."},{id:"d3",speaker:"Sakura",speakerRole:"Mentor Logistik",avatar:"👩‍🏫",jp:"トラックへの 積【つ】み込【こ】みは どうですか。",furigana:"トラックへの 積み込みは どうですか。",romaji:"Torakku e no tsumikomi wa dou desu ka.",idText:"Bagaimana dengan pemuatan ke dalam truk?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"これから トラックに 積【つ】み込【こ】む ところです。すぐ 運【はこ】びます。",furigana:"これから トラックに 積み込む ところです。すぐ 運びます。",romaji:"Kore kara torakku ni tsumikomu tokoro desu. Sugu hakobimasu.",idText:"Tepat sekarang saya baru mau memuatnya ke truk. Akan segera saya angkut."},{id:"d5",speaker:"Sakura",speakerRole:"Mentor Logistik",avatar:"👩‍🏫",jp:"助【たす】かります。ドライバーさんが 今【いま】 事務所【じむしょ】で 待【ま】っている ところですからね。",furigana:"助かります。ドライバーさんが 今 事務所で 待っている ところですからね。",romaji:"Tasukarimasu. Doraiba-san ga ima jimusho de matte iru tokoro desu kara ne.",idText:"Sangat membantu. Karena sopirnya tepat saat ini sedang menunggu di kantor."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】しました！ 急【いそ】いで 積【つ】み込【こ】みを 完了【かんりょう】させます。",furigana:"承知しました！ 急いで 積み込みを 完了させます。",romaji:"Shouchi shimashita! Isoide tsumikomi o kanryou sasemasu.",idText:"Saya pahami! Saya akan bergegas menuntaskan pemuatannya."}],vocab_breakdown:[{id:"vg-n4-00261",word:"しばらく",reading:"しばらく",romaji:"shibaraku",meaning:"sebentar, beberapa saat",pos:"adverb",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"会議室の前でしばらくお待ちください。",furigana:"会議室の前でしばらくお待ちください。",romaji:"",idText:"Silakan menunggu beberapa saat di depan ruang rapat."}},{id:"vg-n4-00777",word:"一度",reading:"いちど",romaji:"ichido",meaning:"sekali, satu kali, suatu saat",pos:"adverb",nuance:"Menyatakan frekuensi tunggal satu kali atau keinginan mencoba pengalaman (一度～してみたい). Jika digabung dengan partikel mo dalam bentuk negatif (一度も～ない), berarti sama sekali belum pernah. Berbeda dengan もう一度 (sekali lagi).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日本に留学している間に一度富士山に登ってみたいです。",furigana:"日本に留学している間に一度富士山に登ってみたいです。",romaji:"",idText:"Selama menempuh studi di Jepang, saya ingin mencoba mendaki Gunung Fuji satu kali."}},{id:"vg-n4-00008",word:"運動会",reading:"うんどうかい",romaji:"undoukai",meaning:"hari olahraga",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"来週の土曜日に小学校の運動会があります。",furigana:"来週の土曜日に小学校の運動会があります。",romaji:"",idText:"Sabtu depan ada hari olahraga di sekolah dasar."}},{id:"vg-n4-00083",word:"趣味",reading:"しゅみ",romaji:"shumi",meaning:"hiburan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"私の趣味は写真をとることです。",furigana:"私の趣味は写真をとることです。",romaji:"",idText:"Hobi saya adalah mengambil foto."}},{id:"vg-n4-00106",word:"開始",reading:"かいし",romaji:"kaishi",meaning:"dimulai, awal",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"午前９時に会議の開始を予定しています。",furigana:"午前９時に会議の開始を予定しています。",romaji:"",idText:"Kami merencanakan dimulainya rapat pada pukul 9 pagi."}},{id:"vg-n4-00108",word:"終電",reading:"しゅうでん",romaji:"shuuden",meaning:"kereta terakhir",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"残業で遅くなり終電に間に合いませんでした。",furigana:"残業で遅くなり終電に間に合いませんでした。",romaji:"",idText:"Karena lembur dan kemalaman, saya ketinggalan kereta terakhir."}},{id:"vg-n4-00111",word:"手続き",reading:"てつづき",romaji:"tetsuduki",meaning:"prosedur, proses administrasi",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"市役所で引っ越しの手続きをしました。",furigana:"市役所で引っ越しの手続きをしました。",romaji:"",idText:"Saya mengurus prosedur pindah rumah di kantor balai kota."}},{id:"vg-n4-00161",word:"旅館",reading:"りょかん",romaji:"ryokan",meaning:"penginapan tradisional Jepang",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"温泉がある古い旅館に泊まりました。",furigana:"温泉がある古い旅館に泊まりました。",romaji:"",idText:"Saya menginap di penginapan tradisional Jepang tua yang memiliki pemandian air panas."}},{id:"vg-n4-00178",word:"予報",reading:"よほう",romaji:"yohou",meaning:"prakiraan, ramalan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"毎朝出かける前に天気予報を確認します。",furigana:"毎朝出かける前に天気予報を確認します。",romaji:"",idText:"Setiap pagi sebelum berangkat saya memastikan prakiraan cuaca."}},{id:"vg-n4-00242",word:"さっき",reading:"さっき",romaji:"sakki",meaning:"tadi, beberapa saat lalu",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"さっき駅前で田中さんに偶然会いました。",furigana:"さっき駅前で田中さんに偶然会いました。",romaji:"",idText:"Tadi beberapa saat lalu saya kebetulan berpapasan dengan Tanaka di depan stasiun."}}],explanations:[{id:"exp-1",grammarId:"gn4-00013",title:"Pola: Vるところ",formula:"Vる + ところです",meaning:"tepat akan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vるところ",idText:"tepat akan ..."}],examples:[{jp:"今から家を出るところです。",romaji:"",idText:"Saya tepat akan keluar rumah sekarang."},{jp:"これから食事を始めるところです。",romaji:"",idText:"Saya tepat akan mulai makan."}]},{id:"exp-2",grammarId:"gn4-00014",title:"Pola: Vているところ",formula:"Vている + ところです",meaning:"tepat sedang ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vているところ",idText:"tepat sedang ..."}],examples:[{jp:"今、料理を作っているところです。",romaji:"",idText:"Sekarang saya tepat sedang memasak."},{jp:"今、会議中です。話し合っているところです。",romaji:"",idText:"Sekarang sedang rapat. Tepat sedang berdiskusi."}]},{id:"exp-3",grammarId:"gn4-00015",title:"Pola: Vたところ",formula:"Vた + ところです",meaning:"baru saja selesai ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vたところ",idText:"baru saja selesai ..."}],examples:[{jp:"今、授業が終わったところです。",romaji:"",idText:"Pelajaran baru saja selesai."},{jp:"「宿題終わった？」「今終わったところ。」",romaji:"",idText:'"PR-nya sudah selesai?" "Baru saja selesai."'}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah keterangan waktu yang bermakna "baru saja beberapa detik/menit lalu".',sentencePrompt:"Kata keterangan waktu yang paling tepat disandingkan dengan [V-ta] ところです adalah:",options:["たった今【いま】 (Baru saja detik ini)","これから (Mulai sekarang / tepat akan)","さっきから (Sejak tadi)","いつか (Suatu saat nanti)"],correctAnswer:"たった今【いま】 (Baru saja detik ini)",explanation:"たった今 menegaskan bahwa kejadian baru saja tuntas sesaat yang lalu.",diagnosticFeedback:{"これから (Mulai sekarang / tepat akan)":"Salah: これから berpasangan dengan bentuk V-ru tokoro (tepat akan mulai).","さっきから (Sejak tadi)":"Salah: さっきから menyatakan durasi kelangsungan sejak tadi.","いつか (Suatu saat nanti)":"Salah: いつか menyatakan waktu yang belum pasti di masa depan."}},{id:"drill-2",type:"cloze",instruction:'Langkah 2 (Seleksi Bentuk Momen): Pilihlah bentuk kata kerja yang tepat untuk menyatakan "tepat sedang makan siang".',sentencePrompt:"A: 今【いま】 何【なに】を していますか。 → B: お昼【ひる】ごはんを（　　）ところです。",options:["食【た】べて いる","食【た】べる","食【た】べた","食【た】べよう"],correctAnswer:"食【た】べて いる",explanation:"Untuk aksi yang sedang persis berlangsung di tengah jalan, gunakan [V-te] いる ところです.",diagnosticFeedback:{"食【た】べる":"Salah: 食べるところ berarti baru akan mulai makan.","食【た】べた":"Salah: 食べたところ berarti baru saja beres makan.","食【た】べよう":"Salah: Bentuk kehendak tidak bersambung langsung dengan tokoro desu."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Partikel & Format Tokoro): Lengkapi kalimat laporan kesiapan.",sentencePrompt:"会議【かいぎ】の 資料【しりょう】を 今【いま】から 印刷【いんさつ】する（　　）です。",options:["ところ","ばかり","とおり","はず"],correctAnswer:"ところ",explanation:"今から + V-ru + ところです = tepat baru akan memulai mencetak dokumen.",diagnosticFeedback:{ばかり:'Salah: ばかり tidak dipasangkan dengan kata "今から" untuk aksi yang belum mulai.',とおり:"Salah: とおり berarti sesuai dengan instruksi.",はず:"Salah: はず berarti seharusnya berdasarkan dugaan logis."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai potongan kata menjadi laporan bahwa kereta baru saja tiba.",sentencePrompt:'Susunlah kata-kata berikut: "Kereta baru saja tiba di peron".',options:["電車【でんしゃ】が ホームに 着【つ】いた ところです。","ホームに 電車【でんしゃ】が ところです 着【つ】いた。","着【つ】いた 電車【でんしゃ】が ホームに ところです。","ところです 電車【でんしゃ】が ホームに 着【つ】いた。"],correctAnswer:"電車【でんしゃ】が ホームに 着【つ】いた ところです。",explanation:"Urutan baku: Subjek (電車が) + Tempat (ホームに) + V-ta (着いた) + ところです.",diagnosticFeedback:{"ホームに 電車【でんしゃ】が ところです 着【つ】いた。":"Salah susun: Predikat verba terpotong di akhir.","着【つ】いた 電車【でんしゃ】が ホームに ところです。":"Salah susun partikel.","ところです 電車【でんしゃ】が ホームに 着【つ】いた。":"Salah struktur."},tokens:["電車【でんしゃ】が","ホームに","着【つ】いた","ところです"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Analisislah situasi yang tepat untuk "これから 出かける ところです".',sentencePrompt:'Kalimat "これから 出【で】かける ところです" diucapkan ketika:',options:["Sepatu sudah dipakai dan tangan sedang memegang gagang pintu untuk keluar","Baru saja pulang sampai di dalam kamar","Sedang berjalan di tengah jalan menuju stasiun","Masih tidur di tempat tidur dan belum bersiap-siap"],correctAnswer:"Sepatu sudah dipakai dan tangan sedang memegang gagang pintu untuk keluar",explanation:"これから V-ru tokoro desu menunjukkan bahwa pembicara sudah siap 100% dan tepat akan melangkah keluar detik itu.",diagnosticFeedback:{"Baru saja pulang sampai di dalam kamar":"Salah: Ini adalah situasi V-ta tokoro (baru saja kembali).","Sedang berjalan di tengah jalan menuju stasiun":"Salah: Ini situasi V-te iru tokoro (sedang di jalan).","Masih tidur di tempat tidur dan belum bersiap-siap":"Salah: Belum mencapai titik momen aksi tokoro."}}],can_do_challenge:{statement:"Bisa mengabarkan progres tugas seketika melalui radio kerja atau telepon.",situation:"Senior menelepon menanyakan apakah kamu sudah berangkat ke lokasi gudang.",promptTask:"Katakan bahwa kamu tepat saat ini baru mau berangkat dari kantor!",modelAnswer:"今【いま】から 事務所【じむしょ】を 出【で】る ところです。",modelAnswerId:"Tepat sekarang saya baru mau berangkat dari kantor.",culturalEtiquette:"Jawab dengan cepat tanpa membuat lawan bicara menunggu ketidakpastian.",skillUnlocked:["Menguasai 3 tahapan presisi momen tindakan via tokoro da","Mampu melaporkan kondisi kerja seketika secara profesional"]},pocket_summary:{keyFormula:"これから + V-ru (akan) / 今 + V-te iru (sedang) / たった今 + V-ta (baru saja) + ところです",coreWords:["これから","いま","たったいま","かくにん"],coreWarning:"Pola ini mengunci momen seketika; jangan gunakan V-ta tokoro untuk kejadian yang sudah berhari-hari lewat.",quickDialogue:"A: 今どう？ → B: たった今終わったところです。"}},"les-n4-u05-03":{pedagogical_framework:{what:{summary:"Menyatakan aksi yang baru saja tuntas dalam persepsi subjektif (~ta bakari), permulaan gradual terencana (~hajimeru), dan permulaan spontan/meledak di luar kendali (~dasu).",canDo:"Bisa menceritakan insiden mesin yang tiba-tiba berbunyi keras atau perubahan cuaca mendadak.",targetPatterns:["[Verba-ta] ばかり (baru saja dilakukan / masih segar)","[Verba Masu-stem] 始【はじ】める (mulai melakukan secara wajar/bertahap)","[Verba Masu-stem] 出【だ】す (tiba-tiba meletup / mulai secara spontan)","[Kata Benda / V-te] ばかり (hanya ... melulu / melulu melakukan)"],coreVocabSample:["きゅうに","とつぜん","ならい始める","なき出す","こしょう","おと"]},sensei_context:{sceneIntro:"Di bengkel pemeliharaan mesin. Kenji dan Budi sedang memeriksa lini konveyor saat tiba-tiba mesin mengeluarkan getaran dan bunyi derit tajam.",dailyMission:"Gunakan 〜出す untuk fenomena yang meledak tiba-tiba tanpa kendali, dan 〜始める untuk aksi permulaan biasa.",whyOrder:"Pekerja pabrik dan teknisi lapangan wajib bisa mendeskripsikan anomali operasional (kapan mesin mulai berbunyi, mendadak mogok) dengan presisi."},cultural_notes:{title:"Laporan Kerusakan & Anomali Peralatan (異常発生時の報告 - Ijou Hassei)",etiquette:"Ketika terjadi keganjilan pada mesin, sampaikan momen awal kejadiannya dengan jelas menggunakan 〜出しました (mendadak berbunyi) agar teknisi senior bisa menganalisis penyebabnya.",taboos:'Jangan memakai 〜出す untuk tindakan terencana atas kemauan sendiri (seperti "saya berniat mulai belajar besok"). Gunakan 〜始める.'},pronunciation_tips:{title:'Intonasi Spontanitas pada Sufiks "-Dasu"',moraNote:"Sufiks 出す (dasu) dilekatkan langsung ke batang verba masu: naki-dasu (menangis mendadak), furi-dasu (turun hujan tiba-tiba).",soundTip:'Ucapkan kata keterangan "kyuu ni" dengan aksen sedikit tajam untuk menekankan efek kejutan.'},common_pitfalls:[{title:"Memakai 〜出す untuk Aksi Terencana Sengaja",caseScenario:'Ingin mengatakan "Besok saya mulai belajar untuk ujian".',pitfallWarning:'"明日【あした】から 勉強【べんきょう】し 出【だ】します。"',rightSolution:'"明日【あした】から 勉強【べんきょう】し 始【はじ】めます。"',explanation:"〜出す hanya untuk fenomena spontan, mendadak, atau emosi yang meledak di luar kontrol kemauan manusia. Untuk rencana teratur, gunakan 〜始める."},{title:"Salah Bentuk Sambung Sebelum 〜始める dan 〜出す",caseScenario:"Menyambungkan verba bentuk kamus utuh sebelum hajimeru.",pitfallWarning:'"雨【あめ】が 降【ふ】る 出【だ】しました。"',rightSolution:'"雨【あめ】が 降【ふ】り 出【だ】しました。"',explanation:"Pola 〜始める dan 〜出す wajib disambung ke batang kata kerja bentuk masu (Masu-stem): 降ります -> 降り出しました."}],who_and_when:{situational_context:"Laporan insiden keselamatan kerja K3, menceritakan perubahan cuaca buruk di jalan, atau menceritakan anak kecil yang tiba-tiba menangis.",social_relations:"Ragam sopan (Hajimemashita / Dashimashita) di tempat kerja kepada atasan dan rekan kerja.",when_not_to_use:"Jangan gunakan 〜出す untuk kegiatan tenang yang diawali secara bertahap dan sistematis."},scenario:{title:"Insiden Mesin Konveyor yang Mendadak Berbunyi",setting:"Lini perakitan nomor 2, pukul 15.30",narrative:"Budi melaporkan kepada Kenji bahwa konveyor yang baru saja diganti rantainya tiba-tiba mengeluarkan bunyi aneh dan berhenti."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ケンジさん！ コンベアが 急【きゅう】に 異音【いおん】を 出【だ】し 始【はじ】めました！",furigana:"ケンジさん！ コンベアが 急に 異音を 出し 始めました！",romaji:"Kenji-san! Konbea ga kyuu ni ion o dashi hajimemashita!",idText:"Kenji-san! Konveyornya tiba-tiba mulai mengeluarkan suara bising yang aneh!"},{id:"d2",speaker:"Kenji",speakerRole:"Teknisi Senior",avatar:"🧑‍💻",jp:"えっ？ この 部品【ぶひん】は 先週【せんしゅう】 交換【こうかん】した ばかりだよ。",furigana:"えっ？ この 部品は 先週 交換した ばかりだよ。",romaji:"E? Kono buhin wa senshuu koukan shita bakari da yo.",idText:"Eh? Komponen ini baru saja diganti minggu lalu lho."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"さっき モーターが 激【はげ】しく 揺【ゆ】れ 出【だ】して、止【と】まって しまいました。",furigana:"さっき モーターが 激しく 揺れ 出して、止まって しまいました。",romaji:"Sakki mo-ta- ga hageshiku yure dashite, tomatte shimaimashita.",idText:"Tadi motornya mendadak bergetar hebat lalu berhenti berputar."},{id:"d4",speaker:"Kenji",speakerRole:"Teknisi Senior",avatar:"🧑‍💻",jp:"すぐ 非常【ひじょう】ボタンを 押【お】して 電源【でんげん】を 切【き】ろう。危険【きけん】だから 離【はな】れて！",furigana:"すぐ 非常ボタンを 押して 電源を 切ろう。危険だから 離れて！",romaji:"Sugu hijou botan o oshite dengen o kirou. Kiken dakara hanarete!",idText:"Ayo segera tekan tombol darurat dan matikan sumber listrik. Karena bahaya, menjauhlah!"},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ 電源【でんげん】を 切【き】りました。外【そと】も 雨【あめ】が 降【ふ】り 出【だ】しましたね。",furigana:"はい！ 電源を 切りました。外も 雨が 降り 出しましたね。",romaji:"Hai! Dengen o kirimashita. Soto mo ame ga furi dashimashita ne.",idText:"Baik! Daya listrik sudah dimatikan. Di luar pun hujan tiba-tiba mulai turun ya."},{id:"d6",speaker:"Kenji",speakerRole:"Teknisi Senior",avatar:"🧑‍💻",jp:"落【お】ち着【つ】いて 原因【げんいん】を 調【しら】べよう。報告【ほうこく】してくれて ありがとう。",furigana:"落ち着いて 原因を 調べよう。報告してくれて ありがとう。",romaji:"Ochitsuite gen'in o shirabeyou. Houkoku shite kurete arigatou.",idText:"Mari kita tenang dan selidiki penyebabnya. Terima kasih sudah segera melapor."}],vocab_breakdown:[{id:"vg-n4-00593",word:"お皿",reading:"おさら",romaji:"osara",meaning:"piring",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"夕食の後でお皿を洗ってきれいに拭きました。",furigana:"夕食の後でお皿を洗ってきれいに拭きました。",romaji:"",idText:"Setelah makan malam saya mencuci piring dan mengelapnya hingga bersih."}},{id:"vg-n4-00594",word:"お茶",reading:"おちゃ",romaji:"ocha",meaning:"teh; teh hijau",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"食後に温かい日本のお茶を飲んで一息つきました。",furigana:"食後に温かい日本のお茶を飲んで一息つきました。",romaji:"",idText:"Sehabis makan saya minum teh hijau Jepang yang hangat untuk melepas lelah sejenak."}},{id:"vg-n4-00601",word:"お客さん",reading:"おきゃくさん",romaji:"okyakusan",meaning:"pelanggan; tamu",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"店員が笑顔でお客さんを迎えました。",furigana:"店員が笑顔でお客さんを迎えました。",romaji:"",idText:"Pelayan toko menyambut tamu pelanggan dengan wajah tersenyum."}},{id:"vg-n4-00607",word:"おじいさん",reading:"おじいさん",romaji:"ojiisan",meaning:"kakek; orang tua laki-laki",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"近所のおじいさんが毎朝犬の散歩をしています。",furigana:"近所のおじいさんが毎朝犬の散歩をしています。",romaji:"",idText:"Kakek tetangga sekitar mengajak jalan-jalan anjingnya setiap pagi."}},{id:"vg-n4-00608",word:"おばあさん",reading:"おばあさん",romaji:"obaasan",meaning:"nenek; orang tua perempuan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"優しそうなおばあさんが道をやさしく教えてくれました。",furigana:"優しそうなおばあさんが道をやさしく教えてくれました。",romaji:"",idText:"Seorang nenek yang tampak ramah dengan baik hati menunjukkan jalan kepada saya."}},{id:"vg-n4-00618",word:"再来週",reading:"さらいしゅう",romaji:"saraishuu",meaning:"dua minggu lagi",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"再来週の月曜日に大切なプレゼンテーションがあります。",furigana:"再来週の月曜日に大切なプレゼンテーションがあります。",romaji:"",idText:"Ada presentasi penting pada hari Senin dua minggu lagi."}},{id:"vg-n4-00629",word:"このあいだ",reading:"このあいだ",romaji:"konoaida",meaning:"kemarin; beberapa hari lalu",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"このあいだ駅前のカフェで偶然高校の先輩に会いました。",furigana:"このあいだ駅前のカフェで偶然高校の先輩に会いました。",romaji:"",idText:"Beberapa hari lalu saya kebetulan bertemu senior SMA di kafe depan stasiun."}},{id:"vg-n4-00702",word:"～月",reading:"～つき",romaji:"~tsuki",meaning:"... bulan (durasi / penghitung jangka waktu bulan)",pos:"counter",nuance:"Sebagai akhiran pembilang durasi bulan dalam ekspresi tertentu seperti 一月 (hitotsuki = satu bulan), 二月 (futatsuki = dua bulan), atau 三月 (mitsuki = tiga bulan). Berbeda dengan ～月 yang dibaca ～がつ (gatsu) yang menyatakan nama bulan dalam kalender (misal 1月 / ichigatsu = bulan Januari).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日本に来てから、あっという間に三月（みつき）が経ちました。",furigana:"日本に来てから、あっという間に三月（みつき）が経ちました。",romaji:"",idText:"Sejak datang ke Jepang, tiga bulan telah berlalu dalam sekejap mata."}},{id:"vg-n4-00728",word:"日",reading:"ひ",romaji:"hi",meaning:"hari, tanggal; matahari, sinar matahari",pos:"noun",nuance:"Bila dibaca 'ひ' (hi), kata ini merujuk pada: (1) satu hari tertentu / tanggal peristiwa (contoh: 休みの日に / pada hari libur, その日に / pada hari itu), atau (2) pancaran sinar matahari (contoh: 日が当たる / terkena sinar matahari, 日が暮れる / matahari terbenam). Jika sebagai hitungan hari berpasangan dengan angka, dibaca か (ka) atau にち (nichi).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"天気のいい日には、公園を散歩するのが好きです。",furigana:"天気のいい日には、公園を散歩するのが好きです。",romaji:"",idText:"Pada hari yang cuacanya cerah, saya suka jalan-jalan santai di taman."}},{id:"vg-n4-00745",word:"パート",reading:"パート",romaji:"paato",meaning:"pekerjaan paruh waktu, kerja part-time",pos:"noun",nuance:"Singkatan dari パートタイム (part-time). Di Jepang, kata パート umumnya merujuk pada kerja paruh waktu yang dijalani ibu rumah tangga atau pekerja dewasa dengan jam kerja tetap yang lebih singkat. Berbeda dengan アルバイト (arubaito) yang cenderung diasosiasikan dengan pelajar atau mahasiswa.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"母は駅前のスーパーで毎日四時間パートをしています。",furigana:"母は駅前のスーパーで毎日四時間パートをしています。",romaji:"",idText:"Ibu bekerja paruh waktu selama empat jam setiap hari di supermarket depan stasiun."}}],explanations:[{id:"exp-1",grammarId:"gn4-00091",title:"Pola: V-たばかりです",formula:"V(plain past た-form) + ばかり",meaning:"baru saja V (baru selesai)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"V-たばかりです",idText:"baru saja V (baru selesai)"}],examples:[{jp:"日本に来たばかりなので、まだ慣れていません。",romaji:"",idText:"Saya baru saja tiba di Jepang jadi belum terbiasa."},{jp:"ご飯を食べたばかりです。",romaji:"",idText:"Saya baru saja makan."},{jp:"仕事を始めたばかりで、覚えることがたくさんあります。",romaji:"",idText:"Baru saja mulai bekerja jadi banyak hal yang perlu diingat."}]},{id:"exp-2",grammarId:"gn4-00021",title:"Pola: V始める (はじめる)",formula:"V-ます語幹 + 始める",meaning:"mulai ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"V始める (はじめる)",idText:"mulai ..."}],examples:[{jp:"雨が降り始めました。",romaji:"",idText:"Hujan mulai turun."},{jp:"6歳からピアノを習い始めました。",romaji:"",idText:"Mulai belajar piano sejak usia 6 tahun."}]},{id:"exp-3",grammarId:"gn4-00022",title:"Pola: V出す (だす)",formula:"V-ます語幹 + 出す",meaning:"tiba-tiba mulai ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"V出す (だす)",idText:"tiba-tiba mulai ..."}],examples:[{jp:"こどもが突然泣き出した。",romaji:"",idText:"Anak itu tiba-tiba menangis."},{jp:"彼は急に走り出した。",romaji:"",idText:"Dia tiba-tiba berlari."}]},{id:"exp-4",grammarId:"gn4-00010",title:"Pola: 〜ばかり",formula:"N/Vて + ばかり / Vた + ばかり",meaning:"hanya ... / melulu ... / baru saja ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ばかり",idText:"hanya ... / melulu ... / baru saja ..."}],examples:[{jp:"あの子はゲームばかりしている。",romaji:"",idText:"Anak itu hanya main game terus."},{jp:"今日東京に着いたばかりです。",romaji:"",idText:"Saya baru saja tiba di Tokyo hari ini."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah kata keterangan yang mencerminkan kejadian mendadak tanpa aba-aba.",sentencePrompt:"Kata keterangan yang paling sering menyertai pola 〜出す adalah:",options:["急【きゅう】に (Secara tiba-tiba)","だんだん (Secara bertahap)","ゆっくり (Secara perlahan)","かならず (Pasti selalu)"],correctAnswer:"急【きゅう】に (Secara tiba-tiba)",explanation:"急に (kyuu ni) atau 突然 (totsuzen) berpadu erat dengan sufiks 〜出す untuk aksi spontan.",diagnosticFeedback:{"だんだん (Secara bertahap)":"Salah: だんだん menyatakan perubahan gradual bertahap, bukan letupan mendadak.","ゆっくり (Secara perlahan)":"Salah: ゆっくり menyatakan tempo santai lambat.","かならず (Pasti selalu)":"Salah: かならず menyatakan keniscayaan mutlak."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Sufiks Permulaan): Lengkapi kalimat hujan yang mendadak turun deras di tengah jalan.",sentencePrompt:"空【そら】が 暗【くら】く なって、突然【とつぜん】 雨【あめ】が（　　）。",options:["降【ふ】り 出【だ】しました","降【ふ】り 終【お】わりました","降【ふ】る つもりです","降【ふ】り 続【つづ】けました"],correctAnswer:"降【ふ】り 出【だ】しました",explanation:"Untuk fenomena alam yang tiba-tiba terjadi tanpa kendali manusia, gunakan Masu-stem + 出す (降り出しました).",diagnosticFeedback:{"降り 終わりました":"Salah: Ini bermakna hujan selesai reda.","降る つもりです":"Salah: Alam tidak memiliki kehendak/niat (tsumori).","降り 続けました":"Salah: Ini bermakna terus-menerus turun hujan tanpa henti.","降【ふ】り 終【お】わりました":'Pilihan "降【ふ】り 終【お】わりました" keliru karena tidak selaras dengan kaidah pola gn4-00091.',"降【ふ】る つもりです":'Jebakan Partikel: Pilihan "降【ふ】る つもりです" tidak tepat untuk peran gramatikal kalimat ini.',"降【ふ】り 続【つづ】けました":'Pilihan "降【ふ】り 続【つづ】けました" keliru karena tidak selaras dengan kaidah pola gn4-00091.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Nuansa Baru Terjadi): Pilihlah pola yang tepat untuk barang yang baru saja dibeli kemarin.",sentencePrompt:"この スマホは 昨日【きのう】 買【か】った（　　）なのに、壊【こわ】れて しまいました。",options:["ばかり","ところ","とおり","ながら"],correctAnswer:"ばかり",explanation:"Pola V-ta + ばかり menyatakan kejadian yang secara subjektif masih dirasa baru saja terjadi (walau sudah kemarin).",diagnosticFeedback:{ところ:"Salah: V-ta tokoro terikat pada momen detik/menit yang baru lewat sesaat, bukan kemarin.",とおり:"Salah: とおり berarti sesuai patokan.",ながら:"Salah: ながら menyatakan dua aksi simultan."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat bayi yang mendadak menangis keras.",sentencePrompt:'Susunlah kata-kata berikut: "Bayi itu tiba-tiba menangis keras".',options:["赤【あか】ちゃんが 突然【とつぜん】 泣【な】き 出【だ】しました。","突然【とつぜん】 泣【な】き 赤【あか】ちゃんが 出【だ】しました。","泣【な】き 赤【あか】ちゃんが 突然【とつぜん】 出【だ】しました。","出【だ】しました 突然【とつぜん】 赤【あか】ちゃんが 泣【な】き。"],correctAnswer:"赤【あか】ちゃんが 突然【とつぜん】 泣【な】き 出【だ】しました。",explanation:"Urutan: Subjek (赤ちゃんが) + Keterangan (突然) + Masu-stem (泣き) + 出しました.",diagnosticFeedback:{"突然【とつぜん】 泣【な】き 赤【あか】ちゃんが 出【だ】しました。":"Salah susun partikel.","泣【な】き 赤【あか】ちゃんが 突然【とつぜん】 出【だ】しました。":"Salah susun frasa verba majemuk.","出【だ】しました 突然【とつぜん】 赤【あか】ちゃんが 泣【な】き。":"Predikat salah tempat."},tokens:["赤【あか】ちゃんが","突然【とつぜん】","泣【な】き","出【だ】しました"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Analisis Nuansa): Bedakan makna 〜始める vs 〜出す.",sentencePrompt:"Manakah kalimat yang tepat untuk menyatakan resolusi belajar secara bertahap dan teratur?",options:["来週【らいしゅう】から 日本語【にほんご】の 教室【きょうしつ】に 通【かよ】い 始【はじ】めます。","来週【らいしゅう】から 日本語【にほんご】の 教室【きょうしつ】に 通【かよ】い 出【だ】します。","昨日【きのう】から 日本語【にほんご】を 忘【わす】れ 出【だ】しました。","来週【らいしゅう】から 日本語【にほんご】を やめ 出【だ】します。"],correctAnswer:"来週【らいしゅう】から 日本語【にほんご】の 教室【きょうしつ】に 通【かよ】い 始【はじ】めます。",explanation:"Aksi yang disengaja atas tekad manusia secara teratur menggunakan 〜始める, bukan 〜出す.",diagnosticFeedback:{"来週【らいしゅう】から 日本語【にほんご】の 教室【きょうしつ】に 通【かよ】い 出【だ】します。":"Tidak alami: 〜出す tidak dipakai untuk rencana kemauan diri sendiri.","昨日【きのう】から 日本語【にほんご】を 忘【わす】れ 出【だ】しました。":"Salah pemakaian tata bahasa.","来週【らいしゅう】から 日本語【にほんご】を やめ 出【だ】します。":"Salah pemakaian pola."}}],can_do_challenge:{statement:"Bisa menceritakan insiden mesin yang tiba-tiba berbunyi keras.",situation:"Melaporkan kepada pengawas bahwa mesin pemotong tiba-tiba mengeluarkan bunyi aneh.",promptTask:"Katakan bahwa mesin tiba-tiba mulai mengeluarkan suara aneh!",modelAnswer:"機械【きかい】が 急【きゅう】に 変【へん】な 音【おと】を 出【だ】し 始【はじ】めました。",modelAnswerId:"Mesin tiba-tiba mulai mengeluarkan suara yang aneh.",culturalEtiquette:"Gunakan nada sigap dan sebutkan subjek objeknya secara terperinci.",skillUnlocked:["Mampu membedakan permulaan gradual (hajimeru) vs spontan (dasu)","Mampu melaporkan anomali peralatan kerja seketika"]},pocket_summary:{keyFormula:"Masu-stem + 始める (mulai teratur) / Masu-stem + 出す (meledak tiba-tiba) / V-ta + ばかり (baru saja)",coreWords:["きゅうに","とつぜん","こしょう","おと"],coreWarning:"Jangan gunakan 〜出す untuk rencana yang disengaja; pola ini khusus fenomena meletup tanpa kendali.",quickDialogue:"A: どうしたの？ → B: 急に雨が降り出しました。"}}},r={"les-n4-u06-01":{pedagogical_framework:{what:{summary:"Melakukan tindakan persiapan terlebih dahulu demi kemudahan di masa mendatang (~te oku) dan memahami pasangan kata kerja transitif (tadoshi + を) vs intransitif (jidoushi + が).",canDo:"Bisa menyiapkan materi rapat sebelum tamu bisnis tiba dan mengomunikasikan persiapan fasilitas.",targetPatterns:["[Verba-te] おく (melakukan persiapan terlebih dahulu)","[Kata Benda] を [Verba Transitif] (membuka pintu, mematikan lampu)","[Kata Benda] が [Verba Intransitif] (pintu terbuka, lampu mati)","[Verba-te] おいて ください (tolong siapkan/biarkan terlebih dahulu)"],coreVocabSample:["じゅんび","あける","あく","しめる","しまる","コピーする","ならべる"]},sensei_context:{sceneIntro:"Di ruang rapat kantor Tokyo. Sakura dan Budi bertugas menyiapkan ruangan sebelum rombongan klien perusahaan rekanan tiba pukul 14.00.",dailyMission:"Gunakan 〜ておく untuk mengonfirmasi persiapan kerja, dan pastikan partikel を vs が tepat sesuai jenis kata kerjanya.",whyOrder:"Persiapan matang (段取り dandori) adalah nilai luhur kerja di Jepang. Menyiapkan segala sesuatunya terlebih dahulu (〜ておく) mencerminkan profesionalisme tinggi."},cultural_notes:{title:"Etika Dandori (段取り): Budaya Persiapan Sebelum Waktu Dimulai",etiquette:'Di kantor Jepang, persiapan ruangan selesai 15 menit sebelum acara dimulai. Melaporkan "sudah saya siapkan sebelumnya" (junbi shite okimashita) memberikan ketenangan bagi atasan.',taboos:"Dalam percakapan lisan santai, 〜ておく sering disingkat menjadi 〜とく (misal: kaitoku, yattoku). Namun kepada atasan, tetap gunakan ragam sopan utuh 〜ておきます."},pronunciation_tips:{title:'Pelafalan Bentuk Singkat Santai "-Toku" vs Sopan "-Te oku"',moraNote:"Shite okimasu (6 mora) -> shitokimasu (5 mora). Jaga vokal [o] tetap jelas.",soundTip:"Jangan memisahkan sambungan antara verba bentuk-te dan oku dengan jeda napas panjang."},common_pitfalls:[{title:"Tertukar Pasangan Partikel Transitif (他動詞) vs Intransitif (自動詞)",caseScenario:'Ingin mengatakan "pintu terbuka sendiri" tetapi malah memakai partikel を.',pitfallWarning:'"ドアを 開【あ】きます。" (Ini berarti subjek sengaja membuka pintu)',rightSolution:'"ドアが 開【あ】きます。" (Pintu membuka/terbuka secara alami)',explanation:"Verba intransitif (自動詞 jidoushi) fokus pada keadaan/perubahan alami dan memakai partikel が. Verba transitif (他動詞 tadoushi) ada agen yang melakukan aksi sengaja dan memakai partikel を."},{title:'Lupa Mengubah Verba ke Bentuk Te Sebelum "Oku"',caseScenario:"Menyambungkan bentuk kamus langsung ke oku.",pitfallWarning:'"資料【しりょう】を 準備【じゅんび】する おきます。"',rightSolution:'"資料【しりょう】を 準備【じゅんび】して おきます。"',explanation:"Pola persiapan wajib menggunakan verba bentuk sambung -te: [V-te] + おく."}],who_and_when:{situational_context:"Persiapan ruang rapat, reservasi tiket dinas luar kota, merapikan perkakas pabrik sebelum pergantian shift.",social_relations:"Sangat sering diucapkan oleh staf kepada atasan saat melaporkan inisiatif persiapan mandiri.",when_not_to_use:"Jangan gunakan 〜ておく untuk aksi refleks mendadak yang tidak memiliki tujuan jangka panjang."},scenario:{title:"Persiapan Ruang Presentasi Sebelum Klien Datang",setting:"Ruang rapat lantai 3, pukul 13.30",narrative:"Sakura meminta Budi memfotokopi materi dan menyalakan pendingin ruangan agar siap saat tamu datang."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Mentor Kantor",avatar:"👩‍🏫",jp:"ブディさん、２時【にじ】に お客【きゃく】様【さま】が 来【こ】られますよ。会議室【かいぎしつ】の 準備【じゅんび】は どうですか。",furigana:"ブディさん、２時に お客様が 来られますよ。会議室の 準備は どうですか。",romaji:"Budi-san, niji ni okyaku-sama ga koraremasu yo. Kaigishitsu no junbi wa dou desu ka.",idText:"Budi-san, jam 2 tamu kita akan datang lho. Bagaimana persiapan ruang rapatnya?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"資料【しりょう】を １０部【じゅうぶ】 コピーして 机【つくえ】に 並【なら】べて おきました。",furigana:"資料を １０部 コピーして 机に 並べて おきました。",romaji:"Shiryou o juubu kopi- shite tsukue ni narabete okimashita.",idText:"Saya sudah memfotokopi materi sebanyak 10 rangkap dan menatanya di atas meja."},{id:"d3",speaker:"Sakura",speakerRole:"Mentor Kantor",avatar:"👩‍🏫",jp:"素晴らしい！ エアコンを つけて、部屋【へや】を 涼【すず】しく して おいてくれますか。",furigana:"素晴らしい！ エアコンを つけて、部屋を 涼しく して おいてくれますか。",romaji:"Subarashii! Eakon o tsukete, heya o suzushiku shite oite kuremasu ka.",idText:"Luar biasa! Bisakah tolong nyalakan AC dan buat ruangannya sejuk terlebih dahulu?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、すぐ つけて おきます。窓【まど】が 開【あ】いて いますね。閉【し】めましょうか。",furigana:"はい、すぐ つけて おきます。窓が 開いて いますね。閉めましょうか。",romaji:"Hai, sugu tsukete okimasu. Mado ga aite imasu ne. Shimemashou ka.",idText:"Baik, akan segera saya nyalakan terlebih dahulu. Jendelanya sedang terbuka ya. Mau saya tutupkan?"},{id:"d5",speaker:"Sakura",speakerRole:"Mentor Kantor",avatar:"👩‍🏫",jp:"ええ、窓【まど】を 閉【し】めて おいてください。準備【じゅんび】万端【ばんたん】ですね。",furigana:"ええ、窓を 閉めて おいてください。準備万端ですね。",romaji:"Ee, mado o shimete oite kudasai. Junbibantan desu ne.",idText:"Iya, tolong tutupkan jendelanya terlebih dahulu ya. Persiapan kita sudah mantap ya."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"お茶【ちゃ】も 用意【ようい】して おきますので、安心【あんしん】してください！",furigana:"お茶も 用意して おきますので、安心して ください！",romaji:"Ocha mo youi shite okimasu node, anshin shite kudasai!",idText:"Teh juga akan saya siapkan terlebih dahulu, jadi tenang saja!"}],vocab_breakdown:[{id:"vg-n4-00005",word:"運ぶ",reading:"はこぶ",romaji:"hakobu",meaning:"membawa, mengangkut",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"引っ越しの荷物を車で運びました。",furigana:"引っ越しの荷物を車で運びました。",romaji:"",idText:"Saya mengangkut barang pindahan dengan mobil."}},{id:"vg-n4-00020",word:"到着",reading:"とうちゃく",romaji:"touchaku",meaning:"kedatangan, tiba",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"飛行機は定刻より三十分遅れて到着しました。",furigana:"飛行機は定刻より三十分遅れて到着しました。",romaji:"",idText:"Pesawat tiba terlambat 30 menit dari jadwal semula."}},{id:"vg-n4-00054",word:"乗り換える",reading:"のりかえる",romaji:"norikaeru",meaning:"transit, ganti kendaraan",pos:"verb-ru",nuance:"乗り換える = transit/ganti kendaraan. 渋谷で乗り換える = transit di Shibuya.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"渋谷で山手線に乗り換えてください。",furigana:"渋谷で山手線に乗り換えてください。",romaji:"",idText:"Tolong ganti ke Yamanote Line di Shibuya."}},{id:"vg-n4-00094",word:"引っ越す",reading:"ひっこす",romaji:"hikkosu",meaning:"pindah rumah",pos:"verb-u",nuance:"引っ越す = pindah rumah. 引っ越しする = proses pindahan. 引っ越し業者 = jasa pindahan.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"来月、新しいアパートに引っ越します。",furigana:"来月、新しいアパートに引っ越します。",romaji:"",idText:"Bulan depan saya pindah ke apartemen baru."}},{id:"vg-n4-00113",word:"連絡",reading:"れんらく",romaji:"renraku",meaning:"kontak, menghubungi",pos:"verb-suru",nuance:"連絡 = kontak/kabar. 連絡する = menghubungi. 連絡が取れない = tidak bisa dihubungi.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"何かあれば連絡してください。",furigana:"何かあれば連絡してください。",romaji:"",idText:"Kalau ada apa-apa, tolong hubungi saya."}},{id:"vg-n4-00129",word:"関係",reading:"かんけい",romaji:"kankei",meaning:"hubungan, relasi",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"私と彼は昔からの親しい関係です。",furigana:"私と彼は昔からの親しい関係です。",romaji:"",idText:"Saya dan dia memiliki hubungan yang akrab sejak dulu."}},{id:"vg-n4-00168",word:"返却",reading:"へんきゃく",romaji:"henkyaku",meaning:"pengembalian",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"図書館で借りた本を期日までに返却しました。",furigana:"図書館で借りた本を期日までに返却しました。",romaji:"",idText:"Saya mengembalikan buku pinjaman perpustakaan sebelum batas waktu."}},{id:"vg-n4-00228",word:"〜てあげる",reading:"〜てあげる",romaji:"teageru",meaning:"melakukan sesuatu untuk orang lain",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"重い荷物を持っている友達を手伝ってあげました。",furigana:"重い荷物を持っている友達を手伝ってあげました。",romaji:"",idText:"Saya membantu teman yang sedang membawa barang berat."}},{id:"vg-n4-00425",word:"知らせる",reading:"しらせる",romaji:"shiraseru",meaning:"memberitahu",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"会議の日程が決まったらメールで知らせてください。",furigana:"会議の日程が決まったらメールで知らせてください。",romaji:"",idText:"Tolong infokan melalui email bila jadwal rapat telah ditetapkan."}},{id:"vg-n4-00435",word:"包む",reading:"つつむ",romaji:"tsutsumu",meaning:"membungkus",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"プレゼントを綺麗な包装紙で丁寧に包みました。",furigana:"プレゼントを綺麗な包装紙で丁寧に包みました。",romaji:"",idText:"Saya membungkus kado pemberian dengan kertas kado cantik dan rapi."}}],explanations:[{id:"exp-1",grammarId:"gn4-00017",title:"Pola: Vておく",formula:"Vて + おく",meaning:"melakukan ... terlebih dahulu (persiapan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vておく",idText:"melakukan ... terlebih dahulu (persiapan)"}],examples:[{jp:"旅行の前にホテルを予約しておきます。",romaji:"",idText:"Sebelum berwisata, saya pesan hotel terlebih dahulu."},{jp:"ドアを開けておいてください。",romaji:"",idText:"Tolong biarkan pintu tetap terbuka."}]},{id:"exp-2",grammarId:"gn4-00073",title:"Pola: 他動詞 / 自動詞 (transitif / intransitif)",formula:"他動詞: N + を + V (ada objek); 自動詞: N + が + V (tidak ada objek)",meaning:"verba transitif / intransitif",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"他動詞 / 自動詞 (transitif / intransitif)",idText:"verba transitif / intransitif"}],examples:[{jp:"(他) ドアを開けました。 (自) ドアが開きました。",romaji:"",idText:"(他) Saya membuka pintu. (自) Pintu terbuka."},{jp:"(他) 電気を消しました。 (自) 電気が消えました。",romaji:"",idText:"(他) Saya mematikan lampu. (自) Lampu padam."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Pasangan Verba): Pilihlah kata kerja transitif (tindakan sengaja manusia) yang tepat.",sentencePrompt:"Kalimat manakah yang merupakan tindakan menyalakan AC secara sengaja?",options:["エアコンを つけます (Menyalakan AC)","エアコンが つきます (AC menyala sendiri)","エアコンが 消【き】えます (AC padam sendiri)","エアコンが 壊【こわ】れます (AC rusak)"],correctAnswer:"エアコンを つけます (Menyalakan AC)",explanation:"他動詞 (tadoushi): objek + を + つけます = menyalakan sesuatu dengan sengaja.",diagnosticFeedback:{"エアコンが つきます (AC menyala sendiri)":"Salah: Ini adalah verba intransitif (keadaan menyala alami).","エアコンが 消【き】えます (AC padam sendiri)":"Salah: Ini intransitif (padam).","エアコンが 壊【こわ】れます (AC rusak)":"Salah: Ini intransitif (rusak)."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Persiapan): Pilihlah bentuk yang tepat untuk aksi persiapan sebelum bepergian.",sentencePrompt:"旅行【りょこう】の 前【まえ】に、ホテルを（　　）おきます。",options:["予約【よやく】して","予約【よやく】する","予約【よやく】した","予約【よやく】しながら"],correctAnswer:"予約【よやく】して",explanation:"Pola persiapan sebelumnya adalah [Verba-te] + おく (予約しておきます).",diagnosticFeedback:{"予約【よやく】する":"Salah: Bentuk kamus tidak bersambung langsung dengan okimasu.","予約【よやく】した":"Salah: Bentuk lampau tidak disambung ke okimasu.","予約【よやく】しながら":"Salah: ながら menyatakan dua aksi simultan."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Partikel Transitif vs Intransitif): Tentukan partikel yang benar untuk pintu yang tertutup rapat.",sentencePrompt:"風【かぜ】で ドア（　　）閉【し】まりました。",options:["が","を","に","で"],correctAnswer:"が",explanation:"閉まる (shimaru) adalah kata kerja intransitif (自動詞), sehingga subjek pembuat keadaannya ditandai dengan partikel が.",diagnosticFeedback:{を:"Salah: を dipakai untuk kata kerja transitif (閉める shimeru).",に:"Salah: に menandai tujuan atau titik waktu.",で:"Salah: で di depan menandai sebab angin (kaze de)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat persiapan memeriksa jadwal kereta sebelum pergi.",sentencePrompt:'Susunlah kata-kata: "Sebelum pergi, periksalah jadwal kereta terlebih dahulu".',options:["出【で】かける 前【まえ】に 電車【でんしゃ】の 時間【じかん】を 調【しら】べて おいてください。","電車【でんしゃ】の 時間【じかん】を 出【で】かける 前【まえ】に おいてください 調【しら】べて。","調【しら】べて 電車【でんしゃ】の 時間【じかん】を 出【で】かける 前【まえ】に おいてください。","おいてください 電車【でんしゃ】の 時間【じかん】を 出【で】かける 前【まえ】に 調【しら】べて。"],correctAnswer:"出【で】かける 前【まえ】に 電車【でんしゃ】の 時間【じかん】を 調【しら】べて おいてください。",explanation:"Keterangan waktu (出かける前に) + Objek (電車の時間を) + V-te oku (調べておいてください).",diagnosticFeedback:{"電車【でんしゃ】の 時間【じかん】を 出【で】かける 前【まえ】に おいてください 調【しら】べて。":"Salah struktur predikat terpisah.","調【しら】べて 電車【でんしゃ】の 時間【じかん】を 出【で】かける 前【まえ】に おいてください。":"Salah urutan.","おいてください 電車【でんしゃ】の 時間【じかん】を 出【で】かける 前【まえ】に 調【しら】べて。":"Salah susun fatal."},tokens:["出【で】かける 前【まえ】に","電車【でんしゃ】の 時間【じかん】を","調【しら】べて","おいてください"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Analisislah makna ungkapan "そのままにしておいてください".',sentencePrompt:'Ungkapan "そのままに して おいてください" memiliki arti:',options:["Biarkan saja begitu apa adanya untuk persiapan nanti","Segera bersihkan dan buang semua barangnya","Bawa barang tersebut pulang ke rumah sekarang","Ubah posisinya menjadi terbalik"],correctAnswer:"Biarkan saja begitu apa adanya untuk persiapan nanti",explanation:"〜ておく selain persiapan masa depan juga berarti mempertahankan kondisi yang ada (membiarkan seperti itu demi tujuan tertentu).",diagnosticFeedback:{"Segera bersihkan dan buang semua barangnya":"Salah: Ini adalah kata片付ける (katadzukeru).","Bawa barang tersebut pulang ke rumah sekarang":"Salah: Ini kata 持ち帰る (mochikaeru).","Ubah posisinya menjadi terbalik":"Salah: Ini bukan makna sono mama ni shite oku."}}],can_do_challenge:{statement:"Bisa menyiapkan materi rapat sebelum tamu bisnis tiba.",situation:"Mentor menanyakan apakah dokumen untuk rapat siang nanti sudah siap.",promptTask:"Katakan bahwa kamu sudah mencetak dan menyiapkan dokumennya terlebih dahulu!",modelAnswer:"はい、資料【しりょう】を 印刷【いんさつ】して 準備【じゅんび】して おきました。",modelAnswerId:"Ya, saya sudah mencetak dan menyiapkan dokumennya terlebih dahulu.",culturalEtiquette:"Tunjukkan kesiapan proaktif dengan laporan lugas dan tersenyum ramah.",skillUnlocked:["Menguasai formulasi aksi persiapan V-te oku","Memahami kontras transitif (tadoushi) dan intransitif (jidoushi)"]},pocket_summary:{keyFormula:"[V-te] + おく (persiapan sebelumnya) / を 他動詞 vs が 自動詞",coreWords:["じゅんび","あける","あく","しめる","しまる"],coreWarning:"Ingat: Objek を berpasangan dengan verba sengaja (他動詞); subjek が berpasangan dengan verba alami (自動詞).",quickDialogue:"A: 準備は？ → B: 資料をコピーしておきました。"}},"les-n4-u06-02":{pedagogical_framework:{what:{summary:"Membedakan keadaan hasil tindakan sengaja seseorang yang tertata (~te aru) vs keadaan alami hasil perubahan yang sedang berlangsung (~te iru).",canDo:"Bisa mengecek papan pengumuman kerja dan memastikan pintu darurat terkunci rapi.",targetPatterns:["[Kata Benda] が [Verba Transitif-te] ある (dalam keadaan sengaja dipersiapkan/tertata)","[Kata Benda] が [Verba Intransitif-te] いる (dalam keadaan terpasang/terbuka secara alami)","カレンダーに 予定【よてい】が 書【か】いて あります (jadwal sudah tertulis rapi)"],coreVocabSample:["はってある","かいてある","ならべてある","しまってある","かぎがかかる"]},sensei_context:{sceneIntro:"Di lorong pabrik dekat pintu darurat. Tanaka mengajak Budi melakukan inspeksi harian sebelum shift malam dimulai.",dailyMission:"Gunakan 〜てある saat menjelaskan barang yang sengaja ditaruh/ditulis oleh seseorang untuk tujuan tertentu.",whyOrder:"Setelah mempelajari persiapan aktif (〜ておく), pembelajar perlu mengenali hasil dari persiapan tersebut yang tertinggal di ruangan (〜てある)."},cultural_notes:{title:"Manajemen Visual 5S di Tempat Kerja Jepang: Seiri & Seiton",etiquette:'Di pabrik Jepang, setiap alat memiliki tempatnya. Mengatakan "Kunci sudah tergantung di papan" (kagi ga kakete arimasu) membuktikan sistem 5S berjalan tertib.',taboos:"Jangan menggunakan verba intransitif dengan 〜ある (seperti ドアが開いてある - salah!). 〜てある HANYA menerima verba transitif."},pronunciation_tips:{title:'Penekanan Partikel "Ga" pada Pola Keadaan Hasil',moraNote:'Pada kalimat "shiryou ga narabete arimasu", partikel "ga" mengikat benda sebagai fokus pandangan mata.',soundTip:'Ucapkan "te arimasu" dengan lembut tanpa intonasi bertanya.'},common_pitfalls:[{title:"Memasangkan Verba Intransitif ke Pola 〜てある",caseScenario:"Ingin mengatakan jendela dalam keadaan terbuka dengan verba aku.",pitfallWarning:'"窓【まど】が 開【あ】いて あります。"',rightSolution:'"窓【まど】が 開【あ】けて あります。" (Sengaja dibuka orang) atau "窓【まど】が 開【あ】いて います。" (Kondisi terbuka)',explanation:"〜てある HANYA bisa berpasangan dengan kata kerja transitif (他動詞: 開ける -> 開けてある). Jika memakai kata kerja intransitif (自動詞: 開く), wajib berpasangan dengan 〜ている (開いている)."},{title:"Salah Menaruh Partikel Objek を Sebelum 〜てある",caseScenario:"Memakai partikel を pada kalimat kondisi tertata.",pitfallWarning:'"壁【かべ】に ポスターを 貼【は】って あります。"',rightSolution:'"壁【かべ】に ポスターが 貼【は】って あります。"',explanation:"Dalam pola 〜てある, fokusnya adalah kondisi keberadaan benda, sehingga partikel penandanya berubah dari を menjadi が."}],who_and_when:{situational_context:"Pemeriksaan keselamatan kerja harian, mengecek ketersediaan inventaris toko, membaca pengumuman di asrama.",social_relations:"Digunakan secara profesional oleh supervisor dan teknisi dalam mendeskripsikan kondisi fasilitas.",when_not_to_use:"Jangan gunakan pada makhluk bernyawa (manusia/hewan) yang sedang berdiam diri."},scenario:{title:"Inspeksi Papan Pengumuman dan Pintu Darurat",setting:"Pintu keluar darurat pabrik, pukul 16.45",narrative:"Tanaka memeriksa apakah peta jalur evakuasi sudah tertempel di dinding dan memastikan kunci darurat tersimpan aman."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、掲示板【けいじばん】の 避難【ひなん】マップは 確認【かくにん】しましたか。",furigana:"ブディさん、掲示板の 避難マップは 確認しましたか。",romaji:"Budi-san, keijiban no hinan mappu wa kakunin shimashita ka.",idText:"Budi-san, apakah peta evakuasi di papan pengumuman sudah kamu pastikan?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、壁【かべ】に 新【あたら】しい 地図【ちず】が 貼【は】って あります。",furigana:"はい、壁に 新しい 地図が 貼って あります。",romaji:"Hai, kabe ni atarashii chizu ga hatte arimasu.",idText:"Iya, di dinding sudah tertempel peta baru (yang sengaja dipasang)."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"非常口【ひじょうぐち】の 鍵【かぎ】は どうなっていますか。",furigana:"非常口の 鍵は どうなっていますか。",romaji:"Hijouguchi no kagi wa dou natte imasu ka.",idText:"Bagaimana dengan kunci pintu daruratnya?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ケースの 中【なか】に 鍵【かぎ】が ちゃんと しまって あります。",furigana:"ケースの 中に 鍵が ちゃんと しまって あります。",romaji:"Ke-su no naka ni kagi ga chanto shimatte arimasu.",idText:"Di dalam kotak penyimpanan kuncinya sudah tersimpan dengan rapi."},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"非常扉【ひじょうとびら】の 前【まえ】に 物【もの】が 置【お】いて ありませんね。よし、安全【あんぜん】です。",furigana:"非常扉の 前に 物が 置いて ありませんね。よし、安全です。",romaji:"Hijoutobira no mae ni mono ga oite arimasen ne. Yoshi, anzen desu.",idText:"Di depan pintu darurat tidak ada barang yang sengaja ditaruh menghalangi ya. Bagus, kondisi aman."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"毎朝【まいあさ】 チェック表【ひょう】に 記号【きごう】が 書【か】いて あるか 見【み】て おきます！",furigana:"毎朝 チェック表に 記号が 書いて あるか 見て おきます！",romaji:"Maiasa chekkuhyou ni kigou ga kaite aru ka mite okimasu!",idText:"Setiap pagi saya akan pastikan apakah tanda centang di lembar cek sudah tertulis rapi!"}],vocab_breakdown:[{id:"vg-n4-00823",word:"いっぱい",reading:"いっぱい",romaji:"ippai",meaning:"penuh; banyak; sampai batas maksimal; kenyang",pos:"adverb",nuance:"Dipakai untuk menyatakan kondisi terisi penuh (seperti ruangan penuh orang, perut kenyang / お腹がいっぱい) atau jumlah yang banyak (sinonim santai dari たくさん). Jika ditulis kanji 一杯 bisa juga berarti 'satu cangkir/gelas'.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"お昼ご飯をたくさん食べて、お腹がいっぱいになりました。",furigana:"お昼ご飯をたくさん食べて、お腹がいっぱいになりました。",romaji:"",idText:"Saya makan siang banyak sekali sampai perut saya kenyang."}},{id:"vg-n4-00039",word:"風景",reading:"ふうけい",romaji:"fuukei",meaning:"pemandangan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"山の頂上からすばらしい風景が見えました。",furigana:"山の頂上からすばらしい風景が見えました。",romaji:"",idText:"Dari puncak gunung terlihat pemandangan yang sangat indah."}},{id:"vg-n4-00045",word:"池",reading:"いけ",romaji:"ike",meaning:"kolam",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"公園の池で魚が泳いでいます。",furigana:"公園の池で魚が泳いでいます。",romaji:"",idText:"Ikan-ikan sedang berenang di kolam taman."}},{id:"vg-n4-00047",word:"駅員",reading:"えきいん",romaji:"ekiin",meaning:"petugas stasiun",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"乗り換えの方法を駅員に尋ねました。",furigana:"乗り換えの方法を駅員に尋ねました。",romaji:"",idText:"Saya menanyakan cara transit kereta kepada petugas stasiun."}},{id:"vg-n4-00051",word:"道路",reading:"どうろ",romaji:"douro",meaning:"jalan raya",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"車が多いので道路を渡るときは気をつけてください。",furigana:"車が多いので道路を渡るときは気をつけてください。",romaji:"",idText:"Karena banyak mobil, harap berhati-hati saat menyeberang jalan raya."}},{id:"vg-n4-00052",word:"道具",reading:"どうぐ",romaji:"dougu",meaning:"alat, perkakas",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"棚を作るために必要な道具をそろえました。",furigana:"棚を作るために必要な道具をそろえました。",romaji:"",idText:"Saya menyiapkan perkakas yang diperlukan untuk membuat rak."}},{id:"vg-n4-00084",word:"料理",reading:"りょうり",romaji:"ryouri",meaning:"masakan, memasak",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"週末は家で日本料理を作ります。",furigana:"週末は家で日本料理を作ります。",romaji:"",idText:"Pada akhir pekan saya memasak masakan Jepang di rumah."}},{id:"vg-n4-00085",word:"料金",reading:"りょうきん",romaji:"ryoukin",meaning:"biaya, tarif",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"電車の料金を改札口で支払いました。",furigana:"電車の料金を改札口で支払いました。",romaji:"",idText:"Saya membayar tarif kereta di gerbang tiket."}},{id:"vg-n4-00347",word:"消防署",reading:"しょうぼうしょ",romaji:"shoubousho",meaning:"pemadam kebakaran",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"消防署の人が学校に来て消火器の使い方を教えてくれました。",furigana:"消防署の人が学校に来て消火器の使い方を教えてくれました。",romaji:"",idText:"Petugas pemadam kebakaran datang ke sekolah dan mengajari cara memakai alat pemadam."}},{id:"vg-n4-00446",word:"案内",reading:"あんない",romaji:"annai",meaning:"panduan; informasi",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日本から来た友達に街を案内してあげました。",furigana:"日本から来た友達に街を案内してあげました。",romaji:"",idText:"Saya memandu dan memperlihatkan kota kepada teman yang datang dari Jepang."}}],explanations:[{id:"exp-1",grammarId:"gn4-00018",title:"Pola: V(他動詞)てある",formula:"Vて (他動詞) + ある",meaning:"sudah dilakukan (keadaan hasil dari tindakan sengaja)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"V(他動詞)てある",idText:"sudah dilakukan (keadaan hasil dari tindakan sengaja)"}],examples:[{jp:"黒板に日程が書いてあります。",romaji:"",idText:"Jadwal sudah tertulis di papan tulis (oleh seseorang)."},{jp:"部屋の窓が開けてあります。",romaji:"",idText:"Jendela kamar sudah dibuka (oleh seseorang)."}]},{id:"exp-2",grammarId:"gn4-00019",title:"Pola: V(自動詞)ている (keadaan hasil)",formula:"Vて (自動詞) + いる",meaning:"dalam keadaan ... (hasil dari proses alami)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"V(自動詞)ている (keadaan hasil)",idText:"dalam keadaan ... (hasil dari proses alami)"}],examples:[{jp:"窓が開いています。",romaji:"",idText:"Jendelanya terbuka (dalam keadaan terbuka)."},{jp:"電気がついています。",romaji:"",idText:"Lampu menyala (dalam keadaan menyala)."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah istilah yang tepat untuk "sudah tertempel rapi di dinding".',sentencePrompt:"Frasa yang tepat untuk poster yang sengaja ditempel di dinding adalah:",options:["貼【は】って あります (Sudah sengaja ditempel)","貼【は】って います (Sedang menempel secara alami)","貼【は】り 始【はじ】めます (Mulai menempel)","貼【は】り 出【だ】します (Mendadak menempel)"],correctAnswer:"貼【は】って あります (Sudah sengaja ditempel)",explanation:"貼る adalah verba transitif (他動詞). Bentuk 〜てある menyatakan keadaan hasil tindakan yang sengaja dilakukan.",diagnosticFeedback:{"貼って います (Sedang menempel secara alami)":"Kurang tepat: 貼る adalah kata kerja transitif, lebih tepat dipasangkan dengan ある untuk keadaan hasil tindakan manusia.","貼り 始めます (Mulai menempel)":"Salah: Ini menyatakan permulaan aksi.","貼り 出します (Mendadak menempel)":"Salah: Tidak ada konteks letupan mendadak.","貼【は】って います (Sedang menempel secara alami)":'Jebakan Partikel: Pilihan "貼【は】って います (Sedang menempel secara alami)" tidak tepat untuk peran gramatikal kalimat ini.',"貼【は】り 始【はじ】めます (Mulai menempel)":'Jebakan Partikel: Pilihan "貼【は】り 始【はじ】めます (Mulai menempel)" tidak tepat untuk peran gramatikal kalimat ini.',"貼【は】り 出【だ】します (Mendadak menempel)":'Jebakan Partikel: Pilihan "貼【は】り 出【だ】します (Mendadak menempel)" tidak tepat untuk peran gramatikal kalimat ini.'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Seleksi Transitif vs Intransitif): Lengkapi kalimat kondisi jendela kantor.",sentencePrompt:"部屋【へや】が 暑【あつ】かったので、窓【まど】が（　　）あります。",options:["開【あ】けて","開【あ】いて","閉【し】まって","開【あ】く"],correctAnswer:"開【あ】けて",explanation:"Pola 〜てある HANYA menerima verba transitif (他動詞: 開ける -> 開けてあります). Verba 開いて adalah intransitif.",diagnosticFeedback:{開いて:"Salah: 開く adalah intransitif, pasangannya adalah 開いています bukan 開いてあります.",閉まって:"Salah: 閉まる adalah intransitif (tertutup).",開く:"Salah: Bentuk kamus tidak bisa bersambung langsung dengan arimasu.","開【あ】いて":'Pilihan "開【あ】いて" keliru karena tidak selaras dengan kaidah pola gn4-00018.',"閉【し】まって":'Pilihan "閉【し】まって" keliru karena tidak selaras dengan kaidah pola gn4-00018.',"開【あ】く":'Pilihan "開【あ】く" keliru karena tidak selaras dengan kaidah pola gn4-00018.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Partikel Penanda Keadaan): Pilihlah partikel yang tepat untuk nama yang tertulis di buku.",sentencePrompt:"教科書【きょうかしょ】の 表紙【ひょうし】に 名前【なまえ】（　　）書【か】いて あります。",options:["が","を","に","で"],correctAnswer:"が",explanation:"Dalam pola [Tempat] に [Benda] が [V-te] ある, benda yang berada dalam keadaan tersebut ditandai dengan partikel が.",diagnosticFeedback:{を:"Salah: Meskipun 書く adalah transitif, dalam pola hasil keadaan 〜てある partikelnya berubah menjadi が.",に:"Salah: に sudah dipakai untuk menandai lokasi (表紙に).",で:"Salah: で menandai sarana atau alat."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat jadwal kerja yang tertulis rapi di kalender.",sentencePrompt:'Susunlah kata-kata berikut: "Jadwal rapat sudah tertulis rapi di kalender".',options:["カレンダーに 会議【かいぎ】の 予定【よてい】が 書【か】いて あります。","会議【かいぎ】の 予定【よてい】が カレンダーに あります 書【か】いて。","書【か】いて カレンダーに 会議【かいぎ】の 予定【よてい】が あります。","あります 会議【かいぎ】の 予定【よてい】が カレンダーに 書【か】いて。"],correctAnswer:"カレンダーに 会議【かいぎ】の 予定【よてい】が 書【か】いて あります。",explanation:"Lokasi (カレンダーに) + Subjek keadaan (会議の予定が) + V-te aru (書いてあります).",diagnosticFeedback:{"会議【かいぎ】の 予定【よてい】が カレンダーに あります 書【か】いて。":"Salah susun predikat terpisah.","書【か】いて カレンダーに 会議【かいぎ】の 予定【よてい】が あります。":"Salah urutan awal kalimat.","あります 会議【かいぎ】の 予定【よてい】が カレンダーに 書【か】いて。":"Salah posisi verba bantu."},tokens:["カレンダーに","会議【かいぎ】の 予定【よてい】が","書【か】いて","あります"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Bedakan nuansa "ドアが開いている" vs "ドアが開けてある".',sentencePrompt:'Pernyataan "ドアが開けてある" mengimplikasikan bahwa:',options:["Seseorang sengaja membuka pintu tersebut demi tujuan tertentu (misal sirkulasi udara)","Pintu tersebut terbuka sendiri karena hembusan angin sepoi-sepoi","Pintu tersebut rusak engselnya sehingga tidak bisa ditutup","Pintu tersebut sedang dalam proses diganti yang baru oleh tukang kayu"],correctAnswer:"Seseorang sengaja membuka pintu tersebut demi tujuan tertentu (misal sirkulasi udara)",explanation:"〜てある selalu menyiratkan adanya niat/tujuan manusia di balik kondisi benda tersebut.",diagnosticFeedback:{"Pintu tersebut terbuka sendiri karena hembusan angin sepoi-sepoi":"Salah: Ini adalah nuansa ドアが開いている (kondisi alami).","Pintu tersebut rusak engselnya sehingga tidak bisa ditutup":"Salah: Kerusakan adalah 故障している.","Pintu tersebut sedang dalam proses diganti yang baru oleh tukang kayu":"Salah: Ini bukan makna te-aru."}}],can_do_challenge:{statement:"Bisa mengecek papan pengumuman kerja dan memastikan pintu darurat terkunci rapi.",situation:"Ditanya oleh pengawas apakah instruksi kerja sudah dipasang di papan.",promptTask:"Katakan bahwa lembar instruksi sudah tertempel rapi di papan pengumuman!",modelAnswer:"はい、掲示板【けいじばん】に 指示書【しじしょ】が 貼【は】って あります。",modelAnswerId:"Ya, lembar instruksi sudah tertempel rapi di papan pengumuman.",culturalEtiquette:"Tunjuk ke arah papan pengumuman dengan tangan terbuka santun.",skillUnlocked:["Menguasai deskripsi keadaan hasil sengaja via V-te aru","Mampu melakukan inspeksi fasilitas kerja mandiri"]},pocket_summary:{keyFormula:"[Kata Benda] が [Verba Transitif-te] ある (tertata sengaja) vs [Kata Benda] が [Verba Intransitif-te] いる (alami)",coreWords:["はってある","かいてある","ならべてある","しまってある"],coreWarning:"Ingat: Jangan pernah memasangkan verba intransitif ke 〜てある (misal: ドアが開いてある adalah SALAH).",quickDialogue:"A: 地図は？ → B: 壁に貼ってあります。"}}},u={"les-n4-u07-01":{pedagogical_framework:{what:{summary:"Menyampaikan permohonan maaf yang tulus dan santun atas kesalahan/keterlambatan (~te sumimasen / gomennasai) dan mengungkapkan rasa syukur atas hasil yang melegakan hati (~te yokatta).",canDo:"Bisa meminta maaf kepada atasan saat datang terlambat karena kendala kereta dan mengabarkan situasi dengan lega.",targetPatterns:["[Verba-te] すみません / 申【もう】し訳【わけ】ありません (maaf sudah / mohon maaf atas)","[Verba-nai -> nakute] すみません (maaf karena tidak...)","[Verba-te] よかった (syukurlah sudah...)","[Verba-nai -> nakute] よかった (syukurlah tidak...)"],coreVocabSample:["おくれる","ちこく","ちえんしょうめいしょ","じこ","あんしんする","たすかる"]},sensei_context:{sceneIntro:"Di pintu masuk kantor perusahaan. Budi datang terengah-engah terlambat 15 menit karena jalur kereta tertahan gangguan sinyal.",dailyMission:"Gunakan frasa 〜てすみません untuk meminta maaf atas ketidaknyamanan, dan sertakan surat bukti keterlambatan kereta (chien shoumeisho).",whyOrder:"Di Jepang, keterlambatan tanpa konfirmasi adalah pelanggaran etika berat. Pembelajar harus menguasai tata cara minta maaf yang profesional dan elegan."},cultural_notes:{title:"Keterlambatan Kereta & Surat Bukti Chien Shoumeisho (遅延証明書)",etiquette:'Jika kereta terlambat di Jepang, mintalah surat "Chien Shoumeisho" dari petugas stasiun atau unduh dari aplikasi kereta. Serahkan ke atasan sambil membungkuk sopan meminta maaf.',taboos:'Jangan menggunakan kata "gomen ne" kepada atasan atau senior. Gunakan ragam formal: お待たせして申し訳ありません (Omatase shite moushiwake arimasen).'},pronunciation_tips:{title:"Intonasi Permohonan Maaf Santun yang Tulus",moraNote:'Frasa "okurete sumimasen" diucapkan dengan nada merendah dan jeda lembut.',soundTip:'Pada saat mengucapkan "moushiwake arimasen", tundukkan kepala sekitar 30 derajat.'},common_pitfalls:[{title:'Memakai Alasan Sebelum "Kara" Tanpa Permohonan Maaf Berbentuk -Te',caseScenario:'Hanya mengatakan "Densha ga okureta kara" tanpa meminta maaf.',pitfallWarning:'"電車【でんしゃ】が 遅【おく】れましたから。" (Terdengar membela diri)',rightSolution:'"電車【でんしゃ】が 遅【おく】れて、遅刻【ちこく】して すみません。" (Santun dan profesional)',explanation:"Di Jepang, atasan ingin mendengar permohonan maaf atas dampaknya terlebih dahulu, baru penjelasan faktualnya melalui verba bentuk sambung -te sumimasen."},{title:"Salah Bentuk Negatif untuk Permohonan Maaf (De wa nakute)",caseScenario:"Meminta maaf karena tidak menghubungi lebih awal.",pitfallWarning:'"連絡【れんらく】しない すみません。"',rightSolution:'"連絡【れんらく】しなくて すみませんでした。"',explanation:"Bentuk sangkalan sebelum sumimasen wajib diubah menjadi bentuk [V-nakute]: renraku shinakute sumimasen."}],who_and_when:{situational_context:"Terlambat masuk kerja karena kendala transportasi, kelupaan membawa dokumen penting, atau bersyukur atas hasil tes kesehatan yang baik.",social_relations:"Wajib digunakan oleh bawahan kepada atasan, atau antarrekan kerja.",when_not_to_use:"Jangan memakai 〜てよかった saat membicarakan kemalangan atau musibah yang menimpa orang lain."},scenario:{title:"Permohonan Maaf Keterlambatan Kereta di Pagi Hari",setting:"Lobi kantor lantai 2, pukul 08.45",narrative:"Budi tiba terlambat karena gangguan kereta dan segera meminta maaf kepada Tanaka-senpai sambil menunjukkan bukti keterlambatan."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"田中【たなか】さん、遅【おく】れて 本当【ほんとう】に すみません！",furigana:"田中さん、遅れて 本当に すみません！",romaji:"Tanaka-san, okurete hontou ni sumimasen!",idText:"Tanaka-san, sungguh mohon maaf sebesar-besarnya saya datang terlambat!"},{id:"d2",speaker:"Tanaka",speakerRole:"Supervisor Kantor",avatar:"🧑‍💼",jp:"ブディさん、どうしたの？ 息【いき】が 切【き】れているよ。",furigana:"ブディさん、どうしたの？ 息が 切れているよ。",romaji:"Budi-san, dou shita no? Iki ga kirete iru yo.",idText:"Budi-san, kamu kenapa? Nafasmu sampai terengah-engah begitu."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"電車【でんしゃ】の 信号【しんごう】トラブルで ２０分【にじゅっぷん】 止【と】まって しまいました。遅延【ちえん】証明書【しょうめいしょ】です。",furigana:"電車の 信号トラブルで ２０分 止まって しまいました。遅延証明書です。",romaji:"Densha no shingou toraburu de nijuppun tomatte shimaimashita. Chien shoumeisho desu.",idText:"Karena kendala sinyal kereta, perjalanan tertahan 20 menit. Ini surat bukti keterlambatan dari stasiun."},{id:"d4",speaker:"Tanaka",speakerRole:"Supervisor Kantor",avatar:"🧑‍💼",jp:"そうだったんだね。事故【じこ】に 巻【ま】き込【こ】まれなくて よかったよ。怪我【けが】は なかった？",furigana:"そうだったんだね。事故に 巻き込まれなくて よかったよ。怪我は なかった？",romaji:"Sou datta n da ne. Jiko ni makikomarenakute yokatta yo. Kega wa nakatta?",idText:"Ternyata begitu ya. Syukurlah kamu tidak terlibat dalam kecelakaan. Tidak ada luka apa-apa kan?"},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、怪我【けが】は ありませんでした。ご心配【しんぱい】を おかけして 申【もう】し訳【わけ】ありません。",furigana:"はい、怪我は ありませんでした。ご心配を おかけして 申し訳ありません。",romaji:"Hai, kega wa arimasen deshita. Goshinpai o okake shite moushiwake arimasen.",idText:"Iya, saya tidak mengalami luka apa pun. Mohon maaf sudah membuat Anda khawatir."},{id:"d6",speaker:"Tanaka",speakerRole:"Supervisor Kantor",avatar:"🧑‍💼",jp:"無事【ぶじ】で 安心【あんしん】したよ。お茶【ちゃ】を 飲【の】んで 呼吸【こきゅう】を 整【ととの】えてから 始【はじ】めよう。",furigana:"無事で 安心したよ。お茶を 飲んで 呼吸を 整えてから 始めよう。",romaji:"Buji de anshin shita yo. Ocha o nonde kokyuu o totonoete kara hajimeyou.",idText:"Syukurlah kamu selamat, saya merasa lega. Minum teh dulu untuk menenangkan nafas, baru setelah itu kita mulai."}],vocab_breakdown:[{id:"vg-n4-00021",word:"忘れる",reading:"わすれる",romaji:"wasureru",meaning:"lupa, melupakan",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"家を出るときに傘を持っていくのを忘れました。",furigana:"家を出るときに傘を持っていくのを忘れました。",romaji:"",idText:"Saya lupa membawa payung saat keluar rumah."}},{id:"vg-n4-00023",word:"笑う",reading:"わらう",romaji:"warau",meaning:"tertawa, tersenyum",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"友だちの面白い冗談を聞いて大声で笑いました。",furigana:"友だちの面白い冗談を聞いて大声で笑いました。",romaji:"",idText:"Saya tertawa terbahak-bahak mendengar lelucon lucu teman saya."}},{id:"vg-n4-00025",word:"泣く",reading:"なく",romaji:"naku",meaning:"menangis",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"感動的な映画を見て思わず泣いてしまいました。",furigana:"感動的な映画を見て思わず泣いてしまいました。",romaji:"",idText:"Saya tanpa sadar menangis saat menonton film yang mengharukan."}},{id:"vg-n4-00027",word:"怒る",reading:"おこる",romaji:"okoru",meaning:"marah, memarahi",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"約束の時間を破って友達を怒らせてしまいました。",furigana:"約束の時間を破って友達を怒らせてしまいました。",romaji:"",idText:"Saya membuat teman marah karena melanggar janji waktu."}},{id:"vg-n4-00029",word:"困る",reading:"こまる",romaji:"komaru",meaning:"kebingungan, kesulitan",pos:"verb-u",nuance:"困る = kebingungan/tidak tahu harus apa. 困っています = saya sedang kesulitan.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"道に迷って困りました。",furigana:"道に迷って困りました。",romaji:"",idText:"Saya kesulitan karena tersesat."}},{id:"vg-n4-00032",word:"心配",reading:"しんぱい",romaji:"shinpai",meaning:"khawatir, cemas",pos:"verb-suru",nuance:"心配する = khawatir. 心配しないでください = jangan khawatir. Lawan: 安心する.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"一人で旅行して大丈夫か心配です。",furigana:"一人で旅行して大丈夫か心配です。",romaji:"",idText:"Saya khawatir apakah aman bepergian sendiri."}},{id:"vg-n4-00142",word:"喜ぶ",reading:"よろこぶ",romaji:"yorokobu",meaning:"merasa senang, bergembira",pos:"verb-u",nuance:"喜ぶ = merasa gembira (atas sesuatu). 喜んで！= Dengan senang hati!",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"合格して喜びました。",furigana:"合格して喜びました。",romaji:"",idText:"Saya gembira lulus."}},{id:"vg-n4-00145",word:"悲しむ",reading:"かなしむ",romaji:"kanashimu",meaning:"bersedih, berduka",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"ペットの犬が死んで家族全員が悲しみました。",furigana:"ペットの犬が死んで家族全員が悲しみました。",romaji:"",idText:"Seluruh keluarga bersedih karena anjing peliharaan mati."}},{id:"vg-n4-00265",word:"思い出す",reading:"おもいだす",romaji:"omoidasu",meaning:"mengingat kembali",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"写真を見て楽しかった子どものころを思い出しました。",furigana:"写真を見て楽しかった子どものころを思い出しました。",romaji:"",idText:"Melihat foto membuat saya mengingat kembali masa kecil bahagia."}},{id:"vg-n4-00266",word:"思いつく",reading:"おもいつく",romaji:"omoitsuku",meaning:"mendapat ide, terpikirkan",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"散歩をしているときに素晴らしいアイデアを思いつきました。",furigana:"散歩をしているときに素晴らしいアイデアを思いつきました。",romaji:"",idText:"Saya memikirkan ide luar biasa saat sedang jalan-jalan santai."}}],explanations:[{id:"exp-1",grammarId:"gn4-00064",title:"Pola: 〜てすみません / 〜てごめんなさい",formula:"Vて + すみません (formal) / ごめんなさい (kasual)",meaning:"maaf sudah ... / maaf telah ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てすみません / 〜てごめんなさい",idText:"maaf sudah ... / maaf telah ..."}],examples:[{jp:"遅れてすみません。",romaji:"",idText:"Maaf sudah terlambat."},{jp:"忘れてごめんなさい。",romaji:"",idText:"Maaf sudah lupa."}]},{id:"exp-2",grammarId:"gn4-00065",title:"Pola: 〜てよかった",formula:"Vて + よかった",meaning:"syukurlah sudah ... / senang karena ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てよかった",idText:"syukurlah sudah ... / senang karena ..."}],examples:[{jp:"傘を持ってきてよかった。",romaji:"",idText:"Syukurlah sudah membawa payung."},{jp:"早めに予約してよかったです。",romaji:"",idText:"Syukurlah sudah memesan lebih awal."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah dokumen resmi stasiun yang membuktikan keterlambatan jadwal kereta.",sentencePrompt:"Surat bukti resmi dari stasiun bahwa kereta mengalami keterlambatan adalah:",options:["遅延【ちえん】証明書【しょうめいしょ】","領収書【りょうしゅうしょ】 (Kwitansi bayar)","身分【みぶん】証明書【しょうめいしょ】 (KTP/ID)","健康【けんこう】保険証【ほけんしょう】 (Kartu BPJS/Asuransi)"],correctAnswer:"遅延【ちえん】証明書【しょうめいしょ】",explanation:"遅延証明書 (chien shoumeisho) adalah bukti sah bahwa keterlambatan disebabkan gangguan teknis moda transportasi publik.",diagnosticFeedback:{"領収書【りょうしゅうしょ】 (Kwitansi bayar)":"Salah: 領収書 adalah kuitansi pembayaran tanda terima uang.","身分【みぶん】証明書【しょうめいしょ】 (KTP/ID)":"Salah: 身分証明書 adalah kartu identitas pengenal diri.","健康【けんこう】保険証【ほけんしょう】 (Kartu BPJS/Asuransi)":"Salah: 健康保険証 adalah kartu asuransi kesehatan."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Formula Minta Maaf): Lengkapi ungkapan permohonan maaf karena datang terlambat.",sentencePrompt:"約束【やくそく】の 時間【じかん】に（　　）すみませんでした。",options:["遅【おく】れて","遅【おく】れる","遅【おく】れた","遅【おく】れそう"],correctAnswer:"遅【おく】れて",explanation:"Pola permohonan maaf atas aksi yang dilakukan adalah [Verba-te] + すみません (遅れてすみません).",diagnosticFeedback:{遅れる:"Salah: Bentuk kamus tidak bisa bersambung langsung ke sumimasen.",遅れた:"Salah: Bentuk lampau ta tidak bisa langsung ke sumimasen tanpa konektor.",遅れそう:"Salah: Ini bermakna kelihatannya akan terlambat.","遅【おく】れる":'Pilihan "遅【おく】れる" keliru karena tidak selaras dengan kaidah pola gn4-00064.',"遅【おく】れた":'Pilihan "遅【おく】れた" keliru karena tidak selaras dengan kaidah pola gn4-00064.',"遅【おく】れそう":'Pilihan "遅【おく】れそう" keliru karena tidak selaras dengan kaidah pola gn4-00064.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Ekspresi Syukur Melegakan): Lengkapi kalimat rasa syukur tidak turun hujan lebat saat berkemah.",sentencePrompt:"雨【あめ】が 降【ふ】ら（　　）本当【ほんとう】に よかったです。",options:["なくて","ないで","ずに","なければ"],correctAnswer:"なくて",explanation:"Untuk menyatakan syukur atas hal negatif yang TIDAK terjadi, gunakan [Verba-nai -> nakute] + よかった (降らなくてよかった).",diagnosticFeedback:{ないで:'Salah: ないで bermakna "tanpa melakukan", bukan alasan syukur.',ずに:"Salah: ずに adalah bentuk formal dari naide.",なければ:'Salah: なければ bermakna pengandaian "jika tidak".'}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat permohonan maaf karena lambat membalas pesan email.",sentencePrompt:'Susunlah kata-kata: "Mohon maaf balasan email dari saya terlambat".',options:["返信【へんしん】が 遅【おく】くなって 申【もう】し訳【わけ】 ありませんでした。","遅【おく】くなって 返信【へんしん】が ありませんでした 申【もう】し訳【わけ】。","申【もう】し訳【わけ】 返信【へんしん】が 遅【おく】くなって ありませんでした。","ありませんでした 遅【おく】くなって 返信【へんしん】が 申【もう】し訳【わけ】。"],correctAnswer:"返信【へんしん】が 遅【おく】くなって 申【もう】し訳【わけ】 ありませんでした。",explanation:"Subjek (返信が) + I-adj te-form (遅くなって) + Moushiwake arimasen deshita.",diagnosticFeedback:{"遅【おく】くなって 返信【へんしん】が ありませんでした 申【もう】し訳【わけ】。":"Salah susun frasa.","申【もう】し訳【わけ】 返信【へんしん】が 遅【おく】くなって ありませんでした。":"Salah urutan pembuka kalimat.","ありませんでした 遅【おく】くなって 返信【へんしん】が 申【もう】し訳【わけ】。":"Salah posisi verba negatif."},tokens:["返信【へんしん】が","遅【おく】くなって","申【もう】し訳【わけ】","ありませんでした"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Analisislah makna ungkapan "早く病院に行ってよかったですね".',sentencePrompt:'Ungkapan "早【はや】く 病院【びょういん】に 行【い】って よかったですね" memiliki arti:',options:["Syukurlah kamu segera pergi periksa ke rumah sakit (sehingga penyakitnya tidak parah)","Kamu sebaiknya segera pergi ke rumah sakit sekarang juga","Tidak perlu pergi ke rumah sakit karena sakitnya biasa saja","Apakah kamu sudah pernah pergi ke rumah sakit sebelumnya?"],correctAnswer:"Syukurlah kamu segera pergi periksa ke rumah sakit (sehingga penyakitnya tidak parah)",explanation:"V-te yokatta desu ne mengekspresikan rasa lega dan simpati positif bahwa tindakan masa lalu membawa dampak baik.",diagnosticFeedback:{"Kamu sebaiknya segera pergi ke rumah sakit sekarang juga":"Salah: Ini adalah saran V-ta hou ga ii desu yo.","Tidak perlu pergi ke rumah sakit karena sakitnya biasa saja":"Salah: Ini adalah ikanaide mo ii desu.","Apakah kamu sudah pernah pergi ke rumah sakit sebelumnya?":"Salah: Ini adalah pola pengalaman itta koto ga arimasu ka."}}],can_do_challenge:{statement:"Bisa meminta maaf kepada atasan saat datang terlambat karena kendala kereta.",situation:"Tiba di kantor terlambat 15 menit dan melapor kepada manajer departemen.",promptTask:"Minta maaflah dengan sopan bahwa keretanya terlambat sehingga kamu datang terlambat!",modelAnswer:"電車【でんしゃ】が 遅【おく】れて、遅刻【ちこく】してしまい 申【もう】し訳【わけ】ありませんでした。",modelAnswerId:"Kereta mengalami keterlambatan, mohon maaf sebesar-besarnya saya terlambat masuk.",culturalEtiquette:"Tundukkan badan sekitar 30 derajat sambil menyerahkan surat bukti keterlambatan.",skillUnlocked:["Menguasai etika dan formula permohonan maaf profesional V-te moushiwake arimasen","Mampu mengekspresikan rasa lega emosional positif V-te yokatta"]},pocket_summary:{keyFormula:"[V-te / V-nakute] + すみません (maaf atas) / [V-te / V-nakute] + よかった (syukurlah)",coreWords:["おくれる","ちこく","ちえんしょうめいしょ","あんしんする"],coreWarning:"Gunakan bentuk sambung -te untuk permohonan maaf; jangan hanya mengulang alasan tanpa kata maaf.",quickDialogue:"A: 遅れてすみません。 → B: 無事でよかった！"}},"les-n4-u07-02":{pedagogical_framework:{what:{summary:"Menyatakan keadaan yang dibiarkan tetap berlangsung apa adanya tanpa perubahan yang semestinya (~mama), serta mengungkapkan peristiwa yang terkadang terjadi sesekali (~koto ga aru).",canDo:"Bisa menegur rekan yang lupa mematikan sakelar AC atau lampu kerja dan menjelaskan kebiasaan harian.",targetPatterns:["[Verba-ta] まま (dibiarkan tetap dalam keadaan ...)","[Kata Benda] の まま / [I-Adj] まま (dalam kondisi aslinya)","[Verba Kamus] ことが ある (kadang-kadang / ada kalanya terjadi)","[Verba-nai] ことが ある (kadang-kadang tidak ...)"],coreVocabSample:["つけたまま","あけたまま","わすれる","しょうエネ","たまに","ときどき"]},sensei_context:{sceneIntro:"Di ruang istirahat staf kantor saat jam pulang kerja. Sakura mendapati sakelar pendingin ruangan dan lampu wastafel masih menyala padahal sudah kosong.",dailyMission:"Gunakan frasa 〜たまま untuk mengingatkan tindakan yang lupa dituntaskan, dan 〜ことがある untuk frekuensi kejadian sesekali.",whyOrder:"Penghematan energi dan kedisiplinan mematikan sakelar (shou-ene) adalah bagian penting dari budaya kerja dan asrama di Jepang."},cultural_notes:{title:"Kedisiplinan Penghematan Energi (省エネ - Shou-Ene) di Jepang",etiquette:"Sebelum pulang dari kantor atau meninggalkan kamar asrama, pastikan AC, lampu, dan keran air tidak dibiarkan menyala (tsuketa mama ni shinai). Ini adalah etika dasar hidup bersama.",taboos:"Jangan tertukar antara V-ta koto ga aru (pengalaman pernah sekali di masa lalu) vs V-ru koto ga aru (kejadian yang kadang terjadi berulang di masa sekarang)."},pronunciation_tips:{title:'Intonasi Teguran Halus "-Ta mama desu yo"',moraNote:'Frasa "tsuketa mama" memiliki 5 mora (tsu-ke-ta-ma-ma) dengan nada datar ramah.',soundTip:'Tambahkan partikel penegas empati "yo" di akhir kalimat agar teguran tidak terdengar memarahi.'},common_pitfalls:[{title:"Tertukar Antara V-ta koto ga aru (Pengalaman) vs V-ru koto ga aru (Kadang Terjadi)",caseScenario:'Ingin mengatakan "saya kadang-kadang lupa membawa payung".',pitfallWarning:'"傘【かさ】を 忘【わす】れた ことが あります。" (Artinya: Saya pernah punya pengalaman lupa payung)',rightSolution:'"たまに 傘【かさ】を 忘【わす】れる ことが あります。" (Benar: Kadang-kadang terjadi kebiasaan)',explanation:"Bentuk kamus V-ru + ことがある berarti rutinitas yang kadang terjadi sesekali. Bentuk lampau V-ta + ことがある berarti riwayat pengalaman masa lalu."},{title:'Salah Bentuk Kata Benda Sebelum "Mama"',caseScenario:"Menyambungkan kata benda ke mama tanpa partikel no.",pitfallWarning:'"昔【むかし】 ままです。"',rightSolution:'"昔【むかし】の ままです。"',explanation:"Kata benda wajib disambung dengan partikel の sebelum mama: Mukashi no mama (tetap seperti masa lampau)."}],who_and_when:{situational_context:"Pemeriksaan sakelar fasilitas kantor sebelum pulang, mengingatkan teman asrama yang lupa mencabut colokan listrik, atau obrolan santai kebiasaan tidur.",social_relations:"Sangat sering diucapkan oleh pengawas asrama, mentor kerja, maupun antarteman sekamar.",when_not_to_use:"Jangan gunakan teguran keras kepada tamu kehormatan perusahaan."},scenario:{title:"Teguran Ramah Mematikan Sakelar Lampu Kantor",setting:"Dapur kantor lantai 1, pukul 18.00",narrative:"Budi menyadari lampu pantry masih menyala dan mengingatkan Kenji bahwa lampu dibiarkan menyala begitu saja."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ケンジさん、給湯室【きゅうとうしつ】の 電気が ついた ままでしたよ。",furigana:"ケンジさん、給湯室の 電気が ついた ままでしたよ。",romaji:"Kenji-san, kyuutoushitsu no denki ga tsuita mama deshita yo.",idText:"Kenji-san, lampu ruang dapur air dibiarkan tetap menyala begitu saja lho."},{id:"d2",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"あ、いけない！ コーヒーを 入【い】れて、そのまま 戻【もど】って きちゃった。",furigana:"あ、いけない！ コーヒーを 入れて、そのまま 戻って きちゃった。",romaji:"A, ikenai! Ko-hi- o irete, sono mama modotte kichatta.",idText:"Aduh, gawat! Habis menyeduh kopi, saya langsung kembali begitu saja."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"私【わたし】が 消【け】して おきましたから、大丈夫【だいじょうぶ】ですよ。",furigana:"私が 消して おきましたから、大丈夫ですよ。",romaji:"Watashi ga keshite okimashita kara, daijoubu desu yo.",idText:"Sudah saya matikan tadi, jadi aman kok."},{id:"d4",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"ありがとう、ブディ。急【いそ】いで いると、時々【ときどき】 うっかり 忘【わす】れる ことが あるんだ。",furigana:"ありがとう、ブディ。急いで いると、時々 うっかり 忘れる ことが あるんだ。",romaji:"Arigatou, Budi. Isoide iru to, tokidoki ukkari wasureru koto ga aru n da.",idText:"Terima kasih ya Budi. Kalau sedang terburu-buru, memang kadang-kadang ada kalanya saya teledor lupa."},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"誰【だれ】でも そういう ことが ありますよね。省【しょう】エネのために 気【き】を つけましょう。",furigana:"誰でも そういう ことが ありますよね。省エネのために 気を つけましょう。",romaji:"Dare demo sou iu koto ga arimasu yo ne. Shou-ene no tame ni ki o tsukemashou.",idText:"Siapa pun kadang mengalami hal seperti itu ya. Mari kita saling jaga demi hemat energi."},{id:"d6",speaker:"Kenji",speakerRole:"Rekan Kerja",avatar:"🧑‍💻",jp:"そうだね！ 声【こえ】を かけてくれて 助【たす】かったよ。",furigana:"そうだね！ 声を かけてくれて 助かったよ。",romaji:"Sou da ne! Koe o kakete kurete tasukatta yo.",idText:"Betul sekali! Terima kasih sudah menegur dan mengingatkan saya."}],vocab_breakdown:[{id:"vg-n4-00024",word:"笑顔",reading:"えがお",romaji:"egao",meaning:"wajah tersenyum",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"先生はいつも明るい笑顔であいさつしてくれます。",furigana:"先生はいつも明るい笑顔であいさつしてくれます。",romaji:"",idText:"Guru selalu menyapa kami dengan senyuman yang ceria."}},{id:"vg-n4-00026",word:"泣き声",reading:"なきごえ",romaji:"nakigoe",meaning:"suara tangisan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"隣の部屋から赤ちゃんの泣き声が聞こえます。",furigana:"隣の部屋から赤ちゃんの泣き声が聞こえます。",romaji:"",idText:"Terdengar suara tangisan bayi dari kamar sebelah."}},{id:"vg-n4-00028",word:"怒り",reading:"いかり",romaji:"ikari",meaning:"kemarahan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"彼の言葉に怒りを感じました。",furigana:"彼の言葉に怒りを感じました。",romaji:"",idText:"Saya merasakan kemarahan mendengar kata-katanya."}},{id:"vg-n4-00030",word:"困難",reading:"こんなん",romaji:"konnan",meaning:"kesulitan, hambatan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"困難な問題もみんなで力を合わせれば解決できます。",furigana:"困難な問題もみんなで力を合わせれば解決できます。",romaji:"",idText:"Masalah yang sulit pun bisa diatasi jika kita menyatukan kekuatan bersama."}},{id:"vg-n4-00031",word:"心",reading:"こころ",romaji:"kokoro",meaning:"hati, pikiran, jiwa",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"心から感謝の気持ちを伝えたいです。",furigana:"心から感謝の気持ちを伝えたいです。",romaji:"",idText:"Saya ingin menyampaikan rasa terima kasih dari lubuk hati yang tulus."}},{id:"vg-n4-00033",word:"安心",reading:"あんしん",romaji:"anshin",meaning:"lega, tenang hati",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"家族が無事だと聞いて安心しました。",furigana:"家族が無事だと聞いて安心しました。",romaji:"",idText:"Saya merasa lega mendengar keluarga dalam keadaan selamat."}},{id:"vg-n4-00034",word:"熱心",reading:"ねっしん",romaji:"nesshin",meaning:"bersemangat, antusias",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"彼は熱心に日本語を勉強しています。",furigana:"彼は熱心に日本語を勉強しています。",romaji:"",idText:"Dia belajar bahasa Jepang dengan sangat antusias."}},{id:"vg-n4-00043",word:"海外",reading:"かいがい",romaji:"kaigai",meaning:"luar negeri",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"将来は海外で働いてみたいです。",furigana:"将来は海外で働いてみたいです。",romaji:"",idText:"Di masa depan saya ingin mencoba bekerja di luar negeri."}},{id:"vg-n4-00044",word:"海岸",reading:"かいがん",romaji:"kaigan",meaning:"pantai, pesisir",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"夕方に海岸をゆっくり歩きました。",furigana:"夕方に海岸をゆっくり歩きました。",romaji:"",idText:"Pada sore hari saya berjalan santai di pesisir pantai."}},{id:"vg-n4-00127",word:"係",reading:"かかり",romaji:"kakari",meaning:"penanggung jawab, staf",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"文化祭の案内係を担当することになりました。",furigana:"文化祭の案内係を担当することになりました。",romaji:"",idText:"Saya ditugaskan menjadi bagian pemandu pada festival budaya."}}],explanations:[{id:"exp-1",grammarId:"gn4-00020",title:"Pola: Vたまま",formula:"Vた + まま / Adjい語幹 + まま / N + の + まま",meaning:"tetap dalam keadaan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vたまま",idText:"tetap dalam keadaan ..."}],examples:[{jp:"靴を履いたまま家に入ってはいけません。",romaji:"",idText:"Tidak boleh masuk rumah dengan sepatu masih dipakai."},{jp:"父はめがねをかけたまま寝ました。",romaji:"",idText:"Ayah tidur dengan kacamata masih terpasang."}]},{id:"exp-2",grammarId:"gn4-00086",title:"Pola: 〜まま",formula:"Vた / Adj-plain / N + の + まま",meaning:"begitu saja / apa adanya",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜まま",idText:"begitu saja / apa adanya"}],examples:[{jp:"窓を開けたまま出かけてしまった。",romaji:"",idText:"Saya pergi keluar dengan jendela masih terbuka."},{jp:"心のままに生きたい。",romaji:"",idText:"Ingin hidup mengikuti kata hati."}]},{id:"exp-3",grammarId:"gn4-00089",title:"Pola: 〜ことがある (kadang-kadang)",formula:"Vる (present) + ことがある",meaning:"kadang-kadang terjadi ... / ada kalanya ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ことがある (kadang-kadang)",idText:"kadang-kadang terjadi ... / ada kalanya ..."}],examples:[{jp:"私は朝ご飯を食べないことがあります。",romaji:"",idText:"Terkadang saya tidak sarapan."},{jp:"バスが遅れることがあるので、早めに出てください。",romaji:"",idText:"Karena bus kadang terlambat, berangkatlah lebih awal."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Kata): Pilihlah kata keterangan frekuensi yang bermakna "kadang-kadang / sesekali".',sentencePrompt:"Kata keterangan yang paling cocok menyertai pola [V-ru] ことが ある adalah:",options:["時々【ときどき】 / たまに (Kadang-kadang)","いつも (Selalu setiap saat)","ぜんぜん (Sama sekali tidak)","かならず (Pasti tanpa kecuali)"],correctAnswer:"時々【ときどき】 / たまに (Kadang-kadang)",explanation:"時々 (tokidoki) atau たまに (tamani) mencerminkan frekuensi berkala yang terjadi sesekali.",diagnosticFeedback:{"いつも (Selalu setiap saat)":"Salah: いつも menyatakan kebiasaan mutlak rutin terus-menerus.","ぜんぜん (Sama sekali tidak)":"Salah: ぜんぜん harus berpasangan dengan bentuk negatif.","かならず (Pasti tanpa kecuali)":"Salah: かならず menyatakan kepastian 100%."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Keadaan Bertahan): Lengkapi kalimat larangan tidur dengan sepatu masih terpasang.",sentencePrompt:"靴【くつ】を（　　）まま、部屋【へや】に 入【はい】らないで ください。",options:["履【は】いた","履【は】く","履【は】いて","履【は】かない"],correctAnswer:"履【は】いた",explanation:"Pola dibiarkan dalam kondisi aksi selesai adalah [Verba-ta] + まま (履いたまま = tetap memakai sepatu).",diagnosticFeedback:{履く:"Salah: Bentuk kamus tidak dipasangkan dengan mama untuk keadaan aksi tubuh.",履いて:"Salah: Bentuk te tidak bersambung langsung ke mama.",履かない:"Salah: Ini bermakna tanpa memakai sepatu (hakanai mama).","履【は】く":'Jebakan Partikel: Pilihan "履【は】く" tidak tepat untuk peran gramatikal kalimat ini.',"履【は】いて":'Jebakan Partikel: Pilihan "履【は】いて" tidak tepat untuk peran gramatikal kalimat ini.',"履【は】かない":'Jebakan Partikel: Pilihan "履【は】かない" tidak tepat untuk peran gramatikal kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Partikel Kata Benda Sebelum Mama): Tentukan partikel penyambung kata benda.",sentencePrompt:"昔【むかし】（　　）ままの 美【うつく】しい 景色【けしき】が 残【のこ】って います。",options:["の","な","に","で"],correctAnswer:"の",explanation:"Kata benda wajib menggunakan partikel の sebelum kata まま (昔のまま = apa adanya seperti zaman dulu).",diagnosticFeedback:{な:"Salah: な dipakai untuk kata sifat-na (例: 静かなまま).",に:"Salah: に tidak dipakai sebagai penyambung kata benda ke mama.",で:"Salah: で menandai sarana."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat pengakuan bahwa kadang-kadang sarapan terlewatkan.",sentencePrompt:'Susunlah kata-kata: "Kadang-kadang ada kalanya saya tidak sarapan pagi".',options:["忙【いそが】しい ときは 朝【あさ】ごはんを 食【た】べない ことが あります。","朝【あさ】ごはんを 忙【いそが】しい ときは ことが あります 食【た】べない。","食【た】べない 忙【いそが】しい ときは 朝【あさ】ごはんを ことが あります。","ことが あります 朝【あさ】ごはんを 食【た】べない 忙【いそが】しい ときは。"],correctAnswer:"忙【いそが】しい ときは 朝【あさ】ごはんを 食【た】べない ことが あります。",explanation:"Kondisi (忙しいときは) + Objek (朝ごはんを) + V-nai (食べない) + ことがあります.",diagnosticFeedback:{"朝【あさ】ごはんを 忙【いそが】しい ときは ことが あります 食【た】べない。":"Salah struktur predikat.","食【た】べない 忙【いそが】しい ときは 朝【あさ】ごはんを ことが あります。":"Salah susun verba terpotong.","ことが あります 朝【あさ】ごはんを 食【た】べない 忙【いそが】しい ときは。":"Salah susun fatal."},tokens:["忙【いそが】しい ときは","朝【あさ】ごはんを","食【た】べない","ことが あります"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Bedakan makna "日本へ行ったことがある" vs "日本へ行くことがある".',sentencePrompt:'Kalimat "仕事【しごと】で 日本【にほん】へ 行【い】く ことが あります" memiliki makna:',options:["Kadang-kadang dalam urusan kerja ada kalanya saya pergi ke Jepang (kebiasaan berkala)","Saya pernah punya pengalaman sekali pergi ke Jepang di masa lalu","Saya bertekad untuk pergi ke Jepang tahun depan","Saya sedang berada di dalam pesawat menuju ke Jepang sekarang"],correctAnswer:"Kadang-kadang dalam urusan kerja ada kalanya saya pergi ke Jepang (kebiasaan berkala)",explanation:"Verba Kamus + ことがある menyatakan kejadian rutin yang kadang terjadi. Kalau V-ta + ことがある barulah menyatakan riwayat pengalaman masa lalu.",diagnosticFeedback:{"Saya pernah punya pengalaman sekali pergi ke Jepang di masa lalu":"Salah: Ini adalah bentuk lampau 行ったことがある.","Saya bertekad untuk pergi ke Jepang tahun depan":"Salah: Ini adalah pola niat 行くつもりです.","Saya sedang berada di dalam pesawat menuju ke Jepang sekarang":"Salah: Ini adalah pola 行っているところです."}}],can_do_challenge:{statement:"Bisa menegur rekan yang lupa mematikan sakelar AC kantor.",situation:"Melihat AC di ruang istirahat masih berbunyi menyala padahal rekan kerja sudah beranjak pergi.",promptTask:"Tegur rekanmu dengan ramah bahwa pendingin ruangannya masih menyala!",modelAnswer:"エアコンが ついた ままでしたよ。消【け】しましょうか。",modelAnswerId:"AC-nya masih dibiarkan menyala begitu saja lho. Mau saya matikan?",culturalEtiquette:"Ucapkan dengan nada bersahabat dan tawarkan bantuan solusi tanpa nada menyalahkan.",skillUnlocked:["Menguasai ekspresi kondisi terabaikan via V-ta mama","Mampu membedakan rutinitas sesekali (V-ru koto ga aru) vs pengalaman lampau"]},pocket_summary:{keyFormula:"[V-ta / N-no] + まま (tetap dibiarkan apa adanya) / [V-ru / V-nai] + ことがある (kadang-kadang)",coreWords:["つけたまま","あけたまま","わすれる","たまに"],coreWarning:"V-ru koto ga aru = kadang-kadang terjadi; V-ta koto ga aru = pernah berpengalaman di masa lalu.",quickDialogue:"A: 電気がついたままだよ。 → B: ごめん、消してきます！"}}},k={"les-n4-u08-01":{pedagogical_framework:{what:{summary:"Sistem memberi dan menerima bantuan (授受表現 juju hyougen: 〜てあげる, 〜てくれる, 〜てもらう) dan menyampaikan harapan agar orang lain melakukan sesuatu (~te hoshii / moraitai).",canDo:"Bisa berterima kasih atas bantuan rekan kerja dan meminta tolong mengajari operasional sistem baru.",targetPatterns:["[Verba-te] あげる (melakukan bantuan untuk orang lain setara/bawah)","[Verba-te] くれる (seseorang berbuat baik untuk saya/kelompok saya)","[Verba-te] もらう (saya menerima jasa kebaikan dari seseorang)","[Orang] に [Verba-te] ほしい / もらいたい (ingin seseorang melakukan ...)"],coreVocabSample:["てつだう","おしえる","せつめい","あんない","うれしい","かんしゃ"]},sensei_context:{sceneIntro:"Di meja kerja departemen TI. Sakura dengan sabar membantu Budi yang kesulitan memasukkan data ke dalam sistem inventaris baru.",dailyMission:"Gunakan 〜てくれる saat menerima pertolongan spontan, dan 〜てもらう saat sengaja memohon bantuan orang lain.",whyOrder:"Hubungan interpersonal di tempat kerja Jepang sangat bertumpu pada kesadaran saling berutang budi (On) dan apresiasi pertolongan (〜てくれる / 〜てもらう)."},cultural_notes:{title:"Etika Memberi & Menerima Bantuan (授受表現の心理 - Juju Hyougen)",etiquette:'Jangan pernah mengatakan "...te agemashou ka" kepada atasan, karena mengesankan kamu merasa lebih superior dengan berbuat amal kepada atasan. Gunakan bentuk hormat O-... shimashou ka.',taboos:'Hindari memakai 〜てあげる di hadapan orang yang baru dikenal karena terdengar arogan ("saya sudi menolongmu"). Gunakan 〜てあげる hanya untuk bawahan, teman akrab, atau anak-anak.'},pronunciation_tips:{title:"Intonasi Partikel Penanda Arah Bantuan (Ni vs Ga)",moraNote:"Rumus baku: [Pemberi] が [Saya] に 〜てくれる; [Saya] が [Pemberi] に 〜てもらう.",soundTip:'Tekankan rasa terima kasih dengan intonasi hangat pada kata "kurete arigatou".'},common_pitfalls:[{title:"Tertukar Subjek antara 〜てくれる vs 〜てもらう",caseScenario:"Mengatakan bahwa rekan kerja membantu saya dengan subjek rekan kerja.",pitfallWarning:'"田中【たなか】さんは 私【わたし】を 手伝【てつだ】って もらいました。"',rightSolution:'"田中【たなか】さんが 私【わたし】を 手伝【てつだ】って くれました。" (Benar: Tanaka yang memberi) atau "私【わたし】は 田中【たなか】さんに 手伝【てつだ】って もらいました。" (Benar: Saya yang menerima bantuan dari Tanaka)',explanation:"Dalam 〜てくれる, subjek kalimat adalah si penolong (Tanaka-san ga). Dalam 〜てもらう, subjek kalimat adalah si penerima bantuan (Watashi wa)."},{title:"Memakai 〜てほしい Kepada Atasan",caseScenario:'Meminta atasan memeriksa dokumen: "Kachou ni mite hoshii desu".',pitfallWarning:'"課長【かちょう】に 見【み】て ほしいです。" (Terdengar menuntut/tidak sopan)',rightSolution:'"課長【かちょう】に 見【み】て いただきたいです。" atau "見【み】て いただけませんか。"',explanation:"〜てほしい mengekspresikan keinginan pribadi pembicara secara blak-blakan. Kepada atasan, wajib menggunakan Keigo itadaitai / itadakemasen ka."}],who_and_when:{situational_context:"Mengucapkan terima kasih saat dibantu rekan kerja, meminta bimbingan senior, atau menawarkan bantuan kepada teman magang.",social_relations:"Sangat vital dalam komunikasi horizontal antarrekan kerja dan vertikal dengan senior.",when_not_to_use:"Jangan gunakan 〜てあげる langsung kepada pelanggan (omokyaku-sama) atau atasan kantor."},scenario:{title:"Bantuan Mempelajari Software Sistem Baru",setting:"Meja kerja kantor, pukul 10.30",narrative:"Budi berterima kasih karena Sakura telah meluangkan waktu mengajarinya cara memasukkan data shift kerja."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"サクラさん、昨日【きのう】は システムの 使【つか】い方【かた】を 教【おし】えてくれて 本当【ほんとう】に ありがとうございました。",furigana:"サクラさん、昨日は システムの 使い方を 教えてくれて 本当に ありがとうございました。",romaji:"Sakura-san, kinou wa shisutemu no tsukaikata o oshiete kurete hontou ni arigatou gozaimashita.",idText:"Sakura-san, kemarin terima kasih banyak sudah berbaik hati mengajari saya cara menggunakan sistem."},{id:"d2",speaker:"Sakura",speakerRole:"Senior Kantor",avatar:"👩‍🏫",jp:"どういたしまして！ もう 一人【ひとり】で 入力【にゅうりょく】 できそうですか。",furigana:"どういたしまして！ もう 一人で 入力 できそうですか。",romaji:"Dou itashimashite! Mou hitori de nyuuryoku dekisou desu ka.",idText:"Sama-sama! Apakah kamu sudah merasa bisa menginput data sendiri?"},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ 田中【たなか】さんにも 画面【がめん】を 見【み】て もらって、無事【ぶじ】に 登録【とうろく】 できました。",furigana:"はい！ 田中さんにも 画面を 見て もらって、無事に 登録 できました。",romaji:"Hai! Tanaka-san ni mo gamen o mite moratte, buji ni touroku dekimashita.",idText:"Iya! Saya juga sudah dibantu diperiksakan layarnya oleh Tanaka-san, dan pendaftaran berhasil lancar."},{id:"d4",speaker:"Sakura",speakerRole:"Senior Kantor",avatar:"👩‍🏫",jp:"よかったですね。もし 分【わ】からない ことがあったら、遠慮【えんりょ】なく 言【い】ってくださいね。",furigana:"よかったですね。もし 分からない ことがあったら、遠慮なく 言ってくださいね。",romaji:"Yokatta desu ne. Moshi wakaranai koto ga attara, enryonaku itte kudasai ne.",idText:"Syukurlah ya. Kalau ada hal yang tidak kamu pahami, jangan sungkan berbicara ya."},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ありがとうございます。今度【こんど】は 私【わたし】も 後輩【こうはい】の 荷物【にもつ】運【はこ】びを 手伝【てつだ】って あげようと 思【おも】います。",furigana:"ありがとうございます。今度は 私も 後輩の 荷物運びを 手伝って あげようと 思います。",romaji:"Arigatou gozaimasu. Kondo wa watashi mo kouhai no nimotsuhakobi o tetsudatte ageyou to omoimasu.",idText:"Terima kasih banyak. Lain kali saya berniat ingin ganti membantu membawakan barang bawaan adik kelas."},{id:"d6",speaker:"Sakura",speakerRole:"Senior Kantor",avatar:"👩‍🏫",jp:"その 気持【きも】ちが 素敵【すてき】ですね！ チームで 助【たす】け合【あ】いましょう。",furigana:"その 気持ちが 素敵ですね！ チームで 助け合いましょう。",romaji:"Sono kimochi ga suteki desu ne! Chi-mu de tasukeaimashou.",idText:"Perasaan peduli itu sungguh luar biasa! Mari kita saling membantu dalam tim."}],vocab_breakdown:[{id:"vg-n4-00015",word:"洗濯",reading:"せんたく",romaji:"sentaku",meaning:"mencuci pakaian",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"天気がいいので、たくさんの服を洗濯しました。",furigana:"天気がいいので、たくさんの服を洗濯しました。",romaji:"",idText:"Karena cuacanya cerah, saya mencuci banyak pakaian."}},{id:"vg-n4-00018",word:"着く",reading:"つく",romaji:"tsuku",meaning:"tiba, sampai",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"駅に着いたら電話をかけてください。",furigana:"駅に着いたら電話をかけてください。",romaji:"",idText:"Tolong telepon saya begitu Anda tiba di stasiun."}},{id:"vg-n4-00059",word:"放送",reading:"ほうそう",romaji:"housou",meaning:"siaran",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"駅で次の電車のアナウンスが放送されています。",furigana:"駅で次の電車のアナウンスが放送されています。",romaji:"",idText:"Pengumuman kereta berikutnya sedang disiarkan di stasiun."}},{id:"vg-n4-00268",word:"持ち上げる",reading:"もちあげる",romaji:"mochiageru",meaning:"mengangkat",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"この段ボール箱は重すぎて一人では持ち上げられません。",furigana:"この段ボール箱は重すぎて一人では持ち上げられません。",romaji:"",idText:"Kotak kardus ini terlalu berat sehingga tak bisa diangkat sendiri."}},{id:"vg-n4-00397",word:"なさる",reading:"なさる",romaji:"nasaru",meaning:"melakukan",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"今度の週末は何をなさるご予定ですか。",furigana:"今度の週末は何をなさるご予定ですか。",romaji:"",idText:"Apa yang rencananya akan Anda lakukan pada akhir pekan nanti?"}},{id:"vg-n4-00402",word:"申す",reading:"もうす",romaji:"mousu",meaning:"berkata",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"はじめまして、インドネシアから参りましたサリと申します。",furigana:"はじめまして、インドネシアから参りましたサリと申します。",romaji:"",idText:"Salam kenal, nama saya Sari dari Indonesia."}},{id:"vg-n4-00403",word:"ございます",reading:"ございます",romaji:"gozaimasu",meaning:"ada",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"お手洗いはあちらのエレベーターの横にございます。",furigana:"お手洗いはあちらのエレベーターの横にございます。",romaji:"",idText:"Toilet tersedia di sebelah lift di sebelah sana."}},{id:"vg-n4-00427",word:"捨てる",reading:"すてる",romaji:"suteru",meaning:"membuang",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"燃えるゴミは毎週火曜日の朝に捨てます。",furigana:"燃えるゴミは毎週火曜日の朝に捨てます。",romaji:"",idText:"Sampah kategori terbakar dibuang tiap Selasa waktu pagi."}},{id:"vg-n4-00443",word:"育てる",reading:"そだてる",romaji:"sodateru",meaning:"membesarkan; mendidik",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"ベランダの植木鉢で野菜を大切に育てています。",furigana:"ベランダの植木鉢で野菜を大切に育てています。",romaji:"",idText:"Saya merawat sayuran di pot teras balkon dengan penuh perhatian."}},{id:"vg-n4-00655",word:"守る",reading:"まもる",romaji:"mamoru",meaning:"menaati, menjaga, melindungi",pos:"verb-u",nuance:"Dua nuansa: ルールを守る (menaati aturan) dan 人を守る (melindungi orang). Konteks tergantung objek.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"約束を守ってください。",furigana:"約束を守ってください。",romaji:"",idText:"Tolong tepati janji."}}],explanations:[{id:"exp-1",grammarId:"gn4-00032",title:"Pola: Vてあげる / くれる / もらう",formula:"Vて + あげる (pemberi) / くれる (ke saya) / もらう (menerima)",meaning:"melakukan untuk / menerima layanan",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vてあげる / くれる / もらう",idText:"melakukan untuk / menerima layanan"}],examples:[{jp:"友だちに傘を貸してあげました。",romaji:"",idText:"Saya meminjamkan payung kepada teman."},{jp:"母が弁当を作ってくれました。",romaji:"",idText:"Ibu membuatkan bento untuk saya."},{jp:"先生に漢字を教えてもらいました。",romaji:"",idText:"Saya diajari kanji oleh guru."}]},{id:"exp-2",grammarId:"gn4-00033",title:"Pola: Vてほしい / もらいたい",formula:"N (orang) + に + Vて + ほしい / もらいたい",meaning:"ingin seseorang melakukan ... / meminta ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vてほしい / もらいたい",idText:"ingin seseorang melakukan ... / meminta ..."}],examples:[{jp:"もっと静かにしてほしいです。",romaji:"",idText:"Saya ingin dia lebih tenang."},{jp:"一緒に来てもらいたいです。",romaji:"",idText:"Saya ingin dia ikut bersama."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah kata yang tepat untuk aksi saling tolong-menolong dalam tim.",sentencePrompt:"Istilah dalam bahasa Jepang untuk aksi saling membantu antarrekan adalah:",options:["助【たす】け合【あ】い (Saling membantu)","一人【ひとり】歩【ある】き (Berjalan sendirian)","言【い】い合【あ】い (Saling berdebat)","待【ま】ち合【あ】わせ (Janji bertemu)"],correctAnswer:"助【たす】け合【あ】い (Saling membantu)",explanation:"助け合い (tasukeai) adalah nilai kebajikan kerja sama gotong-royong dalam budaya Jepang.",diagnosticFeedback:{"一人歩き (Berjalan sendirian)":"Salah: 一人歩き berarti bertindak sendiri tanpa bimbingan.","言い合い (Saling berdebat)":"Salah: 言い合い berarti pertengkaran mulut.","待ち合わせ (Janji bertemu)":"Salah: 待ち合わせ adalah janji temu di tempat tertentu.","一人【ひとり】歩【ある】き (Berjalan sendirian)":'Pilihan "一人【ひとり】歩【ある】き (Berjalan sendirian)" keliru karena tidak selaras dengan kaidah pola gn4-00032.',"言【い】い合【あ】い (Saling berdebat)":'Pilihan "言【い】い合【あ】い (Saling berdebat)" keliru karena tidak selaras dengan kaidah pola gn4-00032.',"待【ま】ち合【あ】わせ (Janji bertemu)":'Pilihan "待【ま】ち合【あ】わせ (Janji bertemu)" keliru karena tidak selaras dengan kaidah pola gn4-00032.'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Seleksi Arah Bantuan): Pilihlah pola yang tepat saat rekan kerja membantumu membawa barang berat.",sentencePrompt:"重【おも】い 荷物【にもつ】を ケンジさんが（　　）。",options:["運【はこ】んで くれました","運【はこ】んで あげました","運【はこ】んで もらいました","運【はこ】びたいです"],correctAnswer:"運【はこ】んで くれました",explanation:"Subjek penolong adalah Kenji-san (ケンジさんが) dan penerima manfaat adalah pembicara, maka pola yang benar adalah 〜てくれました.",diagnosticFeedback:{"運んで あげました":"Salah: Ini bermakna pembicara yang membantu mengangkatkan untuk Kenji.","運んで もらいました":"Salah: Jika subjeknya ケンジさんが, polanya bukan moraimashita (moraimashita subjeknya adalah 私).",運びたいです:"Salah: Ini menyatakan keinginan pribadi diri sendiri.","運【はこ】んで あげました":'Jebakan Partikel: Pilihan "運【はこ】んで あげました" tidak tepat untuk peran gramatikal kalimat ini.',"運【はこ】んで もらいました":'Jebakan Partikel: Pilihan "運【はこ】んで もらいました" tidak tepat untuk peran gramatikal kalimat ini.',"運【はこ】びたいです":'Jebakan Partikel: Pilihan "運【はこ】びたいです" tidak tepat untuk peran gramatikal kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Partikel Penanda Sumber Bantuan): Lengkapi partikel untuk si penolong dalam pola morau.",sentencePrompt:"私【わたし】は 田中【たなか】さん（　　）日本語【にほんご】の 作文【さくぶん】を 直【なお】して もらいました。",options:["に","を","が","へ"],correctAnswer:"に",explanation:"Dalam pola [Penerima] は [Pemberi] に V-te morau, orang yang memberikan jasa kebaikan ditandai dengan partikel に.",diagnosticFeedback:{を:"Salah: を menandai objek karangan (作文を).",が:"Salah: が dipakai jika polanya kuremashita (田中さんが直してくれました).",へ:"Salah: へ menandai arah pergerakan fisik."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat ucapan terima kasih telah diajari bahasa Jepang.",sentencePrompt:'Susunlah kata-kata: "Terima kasih telah mengajari saya bahasa Jepang".',options:["日本語【にほんご】を 親切【しんせつ】に 教【おし】えてくれて ありがとうございました。","親切【しんせつ】に 日本語【にほんご】を ありがとうございました 教【おし】えてくれて。","教【おし】えてくれて 日本語【にほんご】を 親切【しんせつ】に ありがとうございました。","ありがとうございました 日本語【にほんご】を 親切【しんせつ】に 教【おし】えてくれて。"],correctAnswer:"日本語【にほんご】を 親切【しんせつ】に 教【おし】えてくれて ありがとうございました。",explanation:"Objek (日本語を) + Keterangan (親切に) + V-te kurete (教えてくれて) + Arigatou gozaimashita.",diagnosticFeedback:{"親切【しんせつ】に 日本語【にほんご】を ありがとうございました 教【おし】えてくれて。":"Salah susun frasa terima kasih terbalik.","教【おし】えてくれて 日本語【にほんご】を 親切【しんせつ】に ありがとうございました。":"Salah urutan awal.","ありがとうございました 日本語【にほんご】を 親切【しんせつ】に 教【おし】えてくれて。":"Salah penempatan salam penutup."},tokens:["日本語【にほんご】を","親切【しんせつ】に","教【おし】えてくれて","ありがとうございました"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Analisislah mengapa frasa "荷物を運んであげましょうか" tidak boleh diucapkan kepada atasan.',sentencePrompt:'Mengapa Anda sebaiknya TIDAK berkata "荷物を運んであげましょうか" kepada manajer kantor?',options:["Karena 〜てあげる terdengar sombong seperti memandang rendah atasan sebagai pihak yang dikasihani","Karena membawa barang atasan adalah tindakan yang dilarang oleh hukum perburuhan","Karena kata 運ぶ hanya boleh dipakai untuk hewan dan benda cair","Karena kalimat tersebut mengandung bentuk sangkalan negatif yang kasar"],correctAnswer:"Karena 〜てあげる terdengar sombong seperti memandang rendah atasan sebagai pihak yang dikasihani",explanation:"Pola 〜てあげる menyiratkan hubungan hierarki dari atas ke bawah. Kepada atasan, wajib menggunakan ragam merendah (Kenjougo): お持ちしましょうか.",diagnosticFeedback:{"Karena membawa barang atasan adalah tindakan yang dilarang oleh hukum perburuhan":"Salah: Membantu atasan adalah hal lumrah, yang salah hanyalah tata bahasanya.","Karena kata 運ぶ hanya boleh dipakai untuk hewan dan benda cair":"Salah: 運ぶ berarti mengangkut benda apa pun.","Karena kalimat tersebut mengandung bentuk sangkalan negatif yang kasar":"Salah: Kalimat tersebut bukan kalimat sangkalan."}}],can_do_challenge:{statement:"Bisa berterima kasih atas bantuan rekan kerja dan meminta bimbingan santun.",situation:"Rekan kerja meluangkan waktu 30 menit untuk mengajarimu cara mengoperasikan mesin bor.",promptTask:"Ucapkan terima kasih bahwa dia sudah berbaik hati mengajarimu dengan ramah!",modelAnswer:"親切【しんせつ】に 教【おし】えてくれて 本当【ほんとう】に ありがとうございました。",modelAnswerId:"Terima kasih banyak sudah berbaik hati mengajari saya dengan sangat ramah.",culturalEtiquette:"Tundukkan badan sedikit dan tersenyumlah hangat tanda ketulusan apresiasi.",skillUnlocked:["Menguasai sistem transaksi bantuan V-te kureru / morau","Mampu menyampaikan rasa syukur secara kultural Jepang"]},pocket_summary:{keyFormula:"[Pemberi] が 〜てくれる (kebaikan ke saya) / [Saya] が [Pemberi] に 〜てもらう (saya menerima bantuan)",coreWords:["てつだう","おしえる","せつめい","かんしゃ"],coreWarning:"Jangan gunakan 〜てあげる kepada atasan; gunakan Kenjougo お...します.",quickDialogue:"A: 教えてくれてありがとう！ → B: またいつでも聞いてね。"}},"les-n4-u08-02":{pedagogical_framework:{what:{summary:"Meminta tolong atau permohonan izin dengan tingkatan kesantunan bertingkat (~te kuremasen ka / moraemasen ka / kudasaimasen ka), serta menanyakan batas izin (~te mo ii) dan dispensasi kelonggaran (~nakute mo ii).",canDo:"Bisa memohon bimbingan pengisian formulir bank secara santun kepada staf loket dan menanyakan kelonggaran berkas.",targetPatterns:["[Verba-te] くれませんか / もらえませんか (maukah / bisakah tolong...)","[Verba-te] くださいませんか / いただけませんか (sangat santun: sudikah kiranya...)","[Verba-te] も いいですか (bolehkah saya... / apakah tidak masalah jika...)","[Verba-nai -> nakute] も いいです (tidak perlu ... juga boleh)"],coreVocabSample:["きにゅう","こうざ","ふりこみ","みぶんしょう","ハンコ","いんかん"]},sensei_context:{sceneIntro:"Di loket bank kantor pos Tokyo. Budi hendak membuka rekening tabungan gaji dan meminta staf loket membantunya memeriksa isian kanji pada formulir.",dailyMission:"Gunakan 〜てもらえませんか untuk memohon bantuan santun di loket publik, dan pastikan izin dokumen via 〜てもいいですか.",whyOrder:"Berinteraksi di loket bank, balai kota (kuyakusho), dan imigrasi membutuhkan formulir permohonan santun agar urusan administrasi berjalan mulus."},cultural_notes:{title:"Etika Berurusan di Loket Publik Jepang (窓口での丁寧な依頼)",etiquette:'Saat meminta bantuan staf publik, mendahului kalimat dengan kata maaf pengetuk pintu "Sumimasen ga..." lalu menutup dengan "...te itadakemasen ka" menciptakan impresi yang sangat terpelajar.',taboos:'Hindari memakai bentuk perintah langsung "Kite kudasai" kepada petugas jika kamu yang berstatus pemohon. Gunakan bentuk permohonan izin: "Mite moraemasen ka".'},pronunciation_tips:{title:"Intonasi Mengalun Lembut pada Permohonan Negatif Santun",moraNote:'Frasa "moraemasen ka" diucapkan dengan intonasi naik tipis di suku kata terakhir [ka?].',soundTip:'Jangan memotong suku kata "masen ka" dengan nada ketus datar.'},common_pitfalls:[{title:"Tertukar Antara 〜なくてもいい (Boleh Tidak Melakukan) vs 〜てはいけない (Dilarang)",caseScenario:'Ingin mengatakan "kamu tidak perlu tanda tangan di sini jika tidak punya cap stempel".',pitfallWarning:'"サインを しては いけません。" (Artinya: Dilarang keras tanda tangan!)',rightSolution:'"サインは 書【か】かなくても いいですよ。" (Benar: Boleh tidak tanda tangan / tidak wajib)',explanation:"〜てはいけません adalah larangan keras (prohibition). 〜なくてもいいです adalah dispensasi kelonggaran bahwa tindakan tersebut opsional (tidak wajib)."},{title:"Menggunakan 〜てもいいですか untuk Menawarkan Bantuan Diri Sendiri",caseScenario:"Ingin menawarkan membawakan payung teman tapi malah memakai te mo ii desu ka.",pitfallWarning:'"傘【かさ】を 貸【か】しても いいですか。" (Terdengar seperti meminta izin untuk meminjamkan)',rightSolution:'"傘【かさ】を 貸【か】しましょうか。" (Benar: Menawarkan jasa)',explanation:'〜てもいいですか berarti meminta izin untuk keuntungan diri sendiri ("bolehkah saya..."). Untuk menawarkan bantuan ke orang lain, gunakan 〜ましょうか.'}],who_and_when:{situational_context:"Loket bank pembukaan rekening, kantor pos, pendaftaran asuransi kantor desa, menanyakan aturan seragam pabrik.",social_relations:"Sangat lazim dan elegan digunakan pemohon jasa kepada petugas pelayanan publik.",when_not_to_use:"Jangan gunakan permohonan ultra-panjang berbelit kepada teman dekat saat santai di kamar asrama."},scenario:{title:"Membuka Rekening Tabungan di Bank Kantor Pos",setting:"Loket Bank Kantor Pos Shinjuku, pukul 11.00",narrative:"Budi meminta bantuan staf loket untuk memeriksa formulir pembukaan rekening tabungan dan menanyakan apakah stempel inkan wajib dibawa."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"すみません、口座【こうざ】を 作【つく】りたいのですが、書【か】き方【かた】を 教【おし】えて もらえませんか。",furigana:"すみません、口座を 作りたいのですが、書き方を 教えて もらえませんか。",romaji:"Sumimasen, kouza o tsukuritai no desu ga, kakikata o oshiete moraemasen ka.",idText:"Permisi, saya ingin membuka rekening tabungan, sudikah kiranya membantu mengajari cara pengisiannya?"},{id:"d2",speaker:"Sakura",speakerRole:"Staf Loket Bank",avatar:"👩‍💼",jp:"かしこまりました。こちらの 用紙【ようし】に お名前【なまえ】と ご住所【じゅうしょ】を ご記入【きにゅう】ください。",furigana:"かしこまりました。こちらの 用紙に お名前と ご住所を ご記入ください。",romaji:"Kashikomarimashita. Kochira no youshi ni onamae to gojuusho o gokinyuu kudasai.",idText:"Baik saya pahami dengan hormat. Silakan mengisi nama dan alamat Anda pada formulir ini."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"名前【なまえ】は アルファベットで 書【か】いても いいですか。",furigana:"名前は アルファベットで 書いても いいですか。",romaji:"Namae wa arufabetto de kaite mo ii desu ka.",idText:"Apakah namanya boleh saya tulis menggunakan huruf alfabet latin?"},{id:"d4",speaker:"Sakura",speakerRole:"Staf Loket Bank",avatar:"👩‍💼",jp:"はい、在留【ざいりゅう】カードと 同【おな】じ 表記【ひょうき】で 書【か】いていただければ 大丈夫【だいじょうぶ】ですよ。",furigana:"はい、在留カードと 同じ 表記で 書いていただければ 大丈夫ですよ。",romaji:"Hai, zairyuu ka-do to onaji hyouki de kaite itadakereba daijoubu desu yo.",idText:"Iya, asalkan ditulis sama persis dengan ejaan di Kartu Izin Tinggal (Zairyu Card) tidak masalah kok."},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"印鑑【いんかん】を 持【も】って いないのですが、サインでも いいですか。",furigana:"印鑑を 持って いないのですが、サインでも いいですか。",romaji:"Inkan o motte inai no desu ga, sain de mo ii desu ka.",idText:"Saya tidak membawa stempel inkan, apakah boleh menggunakan tanda tangan?"},{id:"d6",speaker:"Sakura",speakerRole:"Staf Loket Bank",avatar:"👩‍💼",jp:"外国籍【がいこくせき】の お客様【きゃくさま】は 印鑑【いんかん】が なくても いいですよ。サインで 結構【けっこう】です。",furigana:"外国籍の お客様は 印鑑が なくても いいですよ。サインで 結構です。",romaji:"Gaikokuseki no okyaku-sama wa inkan ga nakute mo ii desu yo. Sain de kekkou desu.",idText:"Untuk nasabah berkewarganegaraan asing boleh tidak ada stempel kok. Cukup dengan tanda tangan saja."}],vocab_breakdown:[{id:"vg-n4-00093",word:"引き出し",reading:"ひきだし",romaji:"hikidashi",meaning:"laci",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"机の引き出しからハサミを取り出しました。",furigana:"机の引き出しからハサミを取り出しました。",romaji:"",idText:"Saya mengambil gunting dari dalam laci meja."}},{id:"vg-n4-00095",word:"押し入れ",reading:"おしいれ",romaji:"oshiire",meaning:"lemari dinding (gaya Jepang)",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"朝起きて押し入れに布団を片付けました。",furigana:"朝起きて押し入れに布団を片付けました。",romaji:"",idText:"Bangun pagi hari saya merapikan futon ke dalam lemari dinding."}},{id:"vg-n4-00125",word:"建物",reading:"たてもの",romaji:"tatemono",meaning:"gedung, bangunan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"駅の前にとても高い建物が建ちました。",furigana:"駅の前にとても高い建物が建ちました。",romaji:"",idText:"Gedung yang sangat tinggi telah dibangun di depan stasiun."}},{id:"vg-n4-00282",word:"キャンセル",reading:"キャンセル",romaji:"kyanseru",meaning:"pembatalan, membatalkan",pos:"noun",nuance:"キャンセル = pembatalan. キャンセルする = membatalkan. キャンセル料 = biaya pembatalan.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"予約をキャンセルしたいのですが。",furigana:"予約をキャンセルしたいのですが。",romaji:"",idText:"Saya ingin membatalkan reservasi."}},{id:"vg-n4-00296",word:"夫",reading:"おっと",romaji:"otto",meaning:"suami (sendiri)",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"夫は毎朝早く起きて朝ごはんを作ってくれます。",furigana:"夫は毎朝早く起きて朝ごはんを作ってくれます。",romaji:"",idText:"Suami saya bangun pagi setiap hari dan membuatkan sarapan."}},{id:"vg-n4-00297",word:"妻",reading:"つま",romaji:"tsuma",meaning:"istri (sendiri)",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"妻は花が好きなので誕生日にバラを贈りました。",furigana:"妻は花が好きなので誕生日にバラを贈りました。",romaji:"",idText:"Karena istri saya suka bunga, saya menghadiahkan mawar di hari ulang tahunnya."}},{id:"vg-n4-00298",word:"息子",reading:"むすこ",romaji:"musuko",meaning:"anak laki-laki (sendiri)",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"息子は今年高校に入学しました。",furigana:"息子は今年高校に入学しました。",romaji:"",idText:"Anak laki-laki saya masuk SMA tahun ini."}},{id:"vg-n4-00299",word:"娘",reading:"むすめ",romaji:"musume",meaning:"anak perempuan (sendiri)",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"娘は絵を描くのがとても上手です。",furigana:"娘は絵を描くのがとても上手です。",romaji:"",idText:"Anak perempuan saya sangat pandai menggambar."}},{id:"vg-n4-00300",word:"兄",reading:"あに",romaji:"ani",meaning:"kakak laki-laki (sendiri)",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"兄は東京の大学で経済を勉強しています。",furigana:"兄は東京の大学で経済を勉強しています。",romaji:"",idText:"Kakak laki-laki saya belajar ekonomi di universitas di Tokyo."}},{id:"vg-n4-00301",word:"姉",reading:"あね",romaji:"ane",meaning:"kakak perempuan (sendiri)",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"姉は結婚して大阪に住んでいます。",furigana:"姉は結婚して大阪に住んでいます。",romaji:"",idText:"Kakak perempuan saya sudah menikah dan tinggal di Osaka."}}],explanations:[{id:"exp-1",grammarId:"gn4-00034",title:"Pola: Vてくれませんか / もらえませんか / くださいませんか",formula:"Vて + くれませんか / もらえませんか / くださいませんか",meaning:"bisakah kamu ... ? / maukah kamu ... ?",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vてくれませんか / もらえませんか / くださいませんか",idText:"bisakah kamu ... ? / maukah kamu ... ?"}],examples:[{jp:"手伝ってくれませんか。",romaji:"",idText:"Bisakah kamu membantu saya?"},{jp:"もう少し大きな声で話してもらえませんか。",romaji:"",idText:"Bisakah kamu berbicara dengan suara sedikit lebih keras?"}]},{id:"exp-2",grammarId:"gn4-00025",title:"Pola: 〜てもいい",formula:"Vて + もいい(です/ですか)",meaning:"boleh ... / tidak masalah jika ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てもいい",idText:"boleh ... / tidak masalah jika ..."}],examples:[{jp:"ここに座ってもいいですか。",romaji:"",idText:"Boleh saya duduk di sini?"},{jp:"早く帰ってもいいですよ。",romaji:"",idText:"Boleh pulang lebih awal."}]},{id:"exp-3",grammarId:"gn4-00026",title:"Pola: 〜なくてもいい",formula:"Vない → Vなく + てもいい",meaning:"tidak perlu ... / boleh tidak ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜なくてもいい",idText:"tidak perlu ... / boleh tidak ..."}],examples:[{jp:"その本はすぐに返さなくてもいいです。",romaji:"",idText:"Buku itu tidak harus dikembalikan segera."},{jp:"明日は来なくてもいいですよ。",romaji:"",idText:"Besok tidak perlu datang."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah istilah yang tepat untuk stempel resmi pribadi di Jepang.",sentencePrompt:"Stempel nama resmi pribadi yang digunakan untuk transaksi bank dan dokumen legal di Jepang disebut:",options:["印鑑【いんかん】 / 判子【はんこ】","領収書【りょうしゅうしょ】 (Kwitansi)","切符【きっぷ】 (Karcis)","看板【かんばん】 (Papan nama)"],correctAnswer:"印鑑【いんかん】 / 判子【はんこ】",explanation:"印鑑 (inkan) atau 判子 (hanko) adalah cap stempel legal pengganti tanda tangan di Jepang.",diagnosticFeedback:{"領収書【りょうしゅうしょ】 (Kwitansi)":"Salah: 領収書 adalah tanda bukti pembayaran uang.","切符【きっぷ】 (Karcis)":"Salah: 切符 adalah tiket transportasi.","看板【かんばん】 (Papan nama)":"Salah: 看板 adalah papan plang reklame toko."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Permohonan Santun Bertingkat): Pilihlah permohonan yang paling santun dan halus kepada petugas bank.",sentencePrompt:"この 漢字【かんじ】の 読【よ】み方【かた】を（　　）。",options:["教【おし】えて くださいませんか","教【おし】えろ","教【おし】えて くれ","教【おし】えなさい"],correctAnswer:"教【おし】えて くださいませんか",explanation:"Pola [V-te] + くださいませんか adalah tingkatan permohonan santun tinggi yang sangat elegan kepada petugas loket.",diagnosticFeedback:{教えろ:"Salah: Ini adalah bentuk perintah kasar (Meireikei).","教えて くれ":"Salah: Ini adalah ragam kasual akrab yang tidak sopan untuk staf bank.",教えなさい:"Salah: Ini adalah perintah orang tua/guru kepada anak kecil.","教【おし】えろ":'Pilihan "教【おし】えろ" keliru karena tidak selaras dengan kaidah pola gn4-00034.',"教【おし】えて くれ":'Pilihan "教【おし】えて くれ" keliru karena tidak selaras dengan kaidah pola gn4-00034.',"教【おし】えなさい":'Pilihan "教【おし】えなさい" keliru karena tidak selaras dengan kaidah pola gn4-00034.'}},{id:"drill-3",type:"trap_detect",instruction:'Langkah 3 (Kelonggaran Tanpa Keharusan): Pilihlah bentuk yang tepat untuk menyatakan "boleh tidak membayar sekarang".',sentencePrompt:"今日【きょう】は お金【かね】を（　　）いいですよ。明日【あした】 お願【ねが】いします。",options:["払【はら】わなくても","払【はら】って","払【はら】っては","払【はら】わなければ"],correctAnswer:"払【はら】わなくても",explanation:"Pola [V-nai -> nakute] + もいいです menyatakan kelonggaran izin (tidak wajib / boleh tidak melakukan).",diagnosticFeedback:{払って:"Salah: 払ってもいい berarti boleh membayar.",払っては:"Salah: 払ってはいけない berarti larangan membayar.",払わなければ:"Salah: 払わなければならない berarti harus membayar.","払【はら】って":'Jebakan Partikel: Pilihan "払【はら】って" tidak tepat untuk peran gramatikal kalimat ini.',"払【はら】っては":'Jebakan Partikel: Pilihan "払【はら】っては" tidak tepat untuk peran gramatikal kalimat ini.',"払【はら】わなければ":'Jebakan Partikel: Pilihan "払【はら】わなければ" tidak tepat untuk peran gramatikal kalimat ini.'}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai permohonan izin meminjam pulpen di loket formulir.",sentencePrompt:'Susunlah kata-kata: "Bolehkah saya meminjam pulpen ini sebentar?".',options:["この ボールペンを ちょっと 借【か】りても いいですか。","ちょっと この ボールペンを いいですか 借【か】りても。","借【か】りても この ボールペンを ちょっと いいですか。","いいですか ちょっと この ボールペンを 借【か】りても。"],correctAnswer:"この ボールペンを ちょっと 借【か】りても いいですか。",explanation:"Objek (このボールペンを) + Keterangan (ちょっと) + Permohonan izin (借りてもいいですか).",diagnosticFeedback:{"ちょっと この ボールペンを いいですか 借【か】りても。":"Salah susun partikel predikat terpotong.","借【か】りても この ボールペンを ちょっと いいですか。":"Salah posisi verba sambung.","いいですか ちょっと この ボールペンを 借【か】りても。":"Salah struktur total."},tokens:["この ボールペンを","ちょっと","借【か】りても","いいですか"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Analisislah perbedaan "書類を出さなくてもいい" vs "書類を出してはいけない".',sentencePrompt:'Pernyataan "今日【きょう】は 書類【しょるい】を 出【だ】さなくても いいです" berarti:',options:["Hari ini Anda tidak wajib menyerahkan dokumen (bisa diserahkan besok, tapi kalau mau diserahkan hari ini juga boleh)","Hari ini Anda dilarang keras menyerahkan dokumen karena kantor tutup","Anda harus segera menyerahkan dokumen sekarang juga tanpa ditunda","Dokumen Anda ditolak oleh petugas karena ada kekeliruan"],correctAnswer:"Hari ini Anda tidak wajib menyerahkan dokumen (bisa diserahkan besok, tapi kalau mau diserahkan hari ini juga boleh)",explanation:"〜なくてもいい menyatakan tiadanya kewajiban mutlak (kelonggaran sukarela), sangat berbeda dari 〜てはいけない (larangan keras).",diagnosticFeedback:{"Hari ini Anda dilarang keras menyerahkan dokumen karena kantor tutup":"Salah: Ini adalah pola 〜てはいけません.","Anda harus segera menyerahkan dokumen sekarang juga tanpa ditunda":"Salah: Ini adalah pola 〜なければなりません.","Dokumen Anda ditolak oleh petugas karena ada kekeliruan":"Salah: Ini bukan makna tata bahasa tersebut."}}],can_do_challenge:{statement:"Bisa memohon bimbingan pengisian formulir bank secara santun kepada staf loket.",situation:"Berada di loket kantor pos dan tidak tahu cara menulis kolom alamat kanji.",promptTask:"Mohonlah kepada petugas loket agar sudi membantumu melihat formulir ini!",modelAnswer:"すみません、この 申請書【しんせいしょ】を 見【み】て もらえませんか。",modelAnswerId:"Permisi, sudikah kiranya memeriksa formulir permohonan ini untuk saya?",culturalEtiquette:'Awali dengan kata "sumimasen" dan serahkan dokumen dengan kedua belah tangan.',skillUnlocked:["Menguasai hierarki permohonan santun bertingkat","Mampu berurusan di institusi publik Jepang secara mandiri"]},pocket_summary:{keyFormula:"[V-te] + もらえませんか / くださいませんか (mohon bantuan) / [V-te] もいい (boleh) / [V-nakute] もいい (tidak wajib)",coreWords:["きにゅう","こうざ","いんかん","ハンコ"],coreWarning:"V-nakute mo ii = tidak perlu/opsional; V-te wa ikenai = dilarang keras. Jangan sampai tertukar!",quickDialogue:"A: 印鑑は必要？ → B: サインがあれば無くてもいいですよ。"}}};export{u as a,r as b,t as c,i as d,e,n as f,a as g,k as u};
